-- 257_a_number_reaches_its_own_camper.sql
-- ▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲

-- ============================================================================
-- Migration 257: a camper number reaches THAT camper, even one who has left
-- while a new child has their name.                (Ted's audit, TED-001/006)
--
-- THE DEFECT. "Avi Katz" #10 leaves with money on his canteen account. A new
-- "Avi Katz" enrols and is #11. A late card payment or refund for the first
-- Avi arrives carrying #10 — and lands in the new Avi's account.
--
-- Why: about 35 functions accept a camper number and then work by name. They
-- turn the number into the camper's name (camp_person_label), and deeper down
-- turn the name back into a person (camp_person_by_name) — which prefers the
-- child enrolled NOW. #10 → "Avi Katz" → #11.
--
-- THE FIX. Names are never changed: two children may share a name, and no
-- number is ever added to one. Instead, when one of those functions turns a
-- number into a name, it PINS the pair for the rest of that call: within the
-- call, that name means that number. camp_person_by_name answers from the pin
-- first. So #10 → "Avi Katz" → #10.
--
--   * camp_person_name_for(camp, number) — the name, plus the pin. Every one of
--     those functions is switched from camp_person_label to it below (their
--     deployed text is rewritten in place; only that call changes).
--   * The pin lasts for that one call only: it is stamped with the start of
--     the statement that set it and ignored by any other statement. The one
--     function that handles many campers in one call — the offline register's
--     import — clears it at the start of every row.
--   * camp_person_label itself stays a plain read that never adds a number,
--     so lists and reports never pin anybody.
--
-- An earlier draft of this file added the number to the name ("Avi Katz #10").
-- Ted found a case where that sent money to the wrong child (TED-006), and the
-- camp does not want numbers after names. This version adds nothing to any name.
--
-- HOW TO APPLY. Paste into the SQL Editor after 256. Changes no data.
--
-- Standalone. NOT part of APPLY_BUNDLE.sql.
-- ============================================================================

SET LOCAL lock_timeout = '15s';

-- ─── the pin ────────────────────────────────────────────────────────────────
-- Pins belong to ONE call: they are stamped with the start time of the
-- statement that made them, and ignored by any later statement — so a pin can
-- never reach past the call from the page (or the line in the SQL Editor)
-- that set it, even inside a longer transaction.
CREATE OR REPLACE FUNCTION public._person_pins()
RETURNS jsonb
LANGUAGE sql
STABLE
SET search_path = public, pg_catalog
AS $$
    SELECT CASE WHEN v ->> 'at' = statement_timestamp()::text THEN COALESCE(v -> 'map', '{}'::jsonb)
                ELSE '{}'::jsonb END
      FROM (SELECT COALESCE(NULLIF(current_setting('campistry.person_pins', true), '')::jsonb, '{}'::jsonb) AS v) x
$$;

CREATE OR REPLACE FUNCTION public._person_pin_key(p_camp_id uuid, p_name text)
RETURNS text
LANGUAGE sql
IMMUTABLE
AS $$ SELECT p_camp_id::text || '|' || lower(btrim(COALESCE(p_name, ''))) $$;

CREATE OR REPLACE FUNCTION public.clear_person_pins()
RETURNS void
LANGUAGE plpgsql
VOLATILE
AS $$
BEGIN
    PERFORM set_config('campistry.person_pins', '', true);
END;
$$;

-- The camper's name for a number — and, for the rest of this call, that name
-- means that number.
CREATE OR REPLACE FUNCTION public.camp_person_name_for(p_camp_id uuid, p_person_id bigint)
RETURNS text
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
DECLARE
    v_name text;
BEGIN
    SELECT source_key INTO v_name FROM camp_people
     WHERE camp_id = p_camp_id AND kind = 'camper' AND person_id = p_person_id;
    IF v_name IS NULL THEN
        RETURN NULL;
    END IF;
    PERFORM set_config('campistry.person_pins',
        jsonb_build_object('at', statement_timestamp()::text,
                           'map', public._person_pins()
                                  || jsonb_build_object(public._person_pin_key(p_camp_id, v_name), p_person_id))::text,
        true);
    RETURN v_name;
END;
$$;
REVOKE ALL ON FUNCTION public.camp_person_name_for(uuid, bigint) FROM public, anon, authenticated;


-- ─── the label and the lookup ───────────────────────────────────────────────
-- The label is the plain roster key. (If an earlier draft of this file was
-- applied, this puts it back.)
CREATE OR REPLACE FUNCTION public.camp_person_label(p_camp_id uuid, p_person_id bigint)
RETURNS text
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
    SELECT source_key FROM camp_people
     WHERE camp_id = p_camp_id AND kind = 'camper' AND person_id = p_person_id
$$;
COMMENT ON FUNCTION public.camp_person_label(uuid, bigint) IS
    'The camper''s roster key for a person id, or NULL. A plain read: it never pins. Functions that go on to work by name use camp_person_name_for (257).';

CREATE OR REPLACE FUNCTION public.camp_person_by_name(p_camp_id uuid, p_name text)
RETURNS bigint
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
    SELECT COALESCE(
        -- 257: inside a call that started from a camper number, that number.
        (public._person_pins() ->> public._person_pin_key(p_camp_id, p_name))::bigint,
        -- Otherwise exactly as 223: exact key, then case/space-insensitive,
        -- then including departed campers; ambiguous at the matched rank → NULL.
        (WITH ranked AS (
            SELECT person_id, 1 AS rank FROM camp_people
             WHERE camp_id = p_camp_id AND kind = 'camper'
               AND deleted_at IS NULL AND source_key = p_name
            UNION ALL
            SELECT person_id, 2 FROM camp_people
             WHERE camp_id = p_camp_id AND kind = 'camper'
               AND deleted_at IS NULL AND lower(btrim(source_key)) = lower(btrim(p_name))
            UNION ALL
            SELECT person_id, 3 FROM camp_people
             WHERE camp_id = p_camp_id AND kind = 'camper'
               AND lower(btrim(source_key)) = lower(btrim(p_name))
         ),
         best AS (SELECT min(rank) AS rank FROM ranked)
         SELECT CASE WHEN count(DISTINCT r.person_id) = 1 THEN min(r.person_id) END
           FROM ranked r JOIN best b ON r.rank = b.rank
          WHERE NULLIF(btrim(COALESCE(p_name, '')), '') IS NOT NULL))
$$;
COMMENT ON FUNCTION public.camp_person_by_name(uuid, text) IS
    'The one name-to-camper-id matcher. Inside a call that started from a camper number, that number (257). Otherwise exact key, then case/space-insensitive, then including departed campers; ambiguous → NULL.';


-- ─── every function that starts from a number now pins ──────────────────────
-- Found in the catalog: every function whose body turns a number into a name
-- with camp_person_label, except the few that only READ (they must never pin),
-- and the lock/save pair, which refresh an account's label and must not change
-- which person later lookups in the same call mean.
CREATE OR REPLACE FUNCTION public._functions_that_must_pin()
RETURNS SETOF oid
LANGUAGE sql
STABLE
SET search_path = public, pg_catalog
AS $$
    SELECT p.oid
      FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
     WHERE n.nspname = 'public'
       AND p.prosrc ~ 'camp_person_label\('
       AND p.proname NOT IN ('camp_person_label', 'camp_person_name_for',
                             'canteen_account_lock', 'canteen_account_save',
                             'canteen_autoreload_accounts', 'canteen_refund_view')
       -- The database's self-checks (verify_*) only report. verify_my_camper
       -- is not one of them: it answers a parent "is this my child?", and
       -- must decide by the number like everything else (Ted, TED-008).
       AND (p.proname NOT LIKE 'verify\_%' OR p.proname = 'verify_my_camper')
$$;

DO $$
DECLARE
    f      oid;
    v_def  text;
    v_n    int := 0;
BEGIN
    FOR f IN SELECT * FROM public._functions_that_must_pin() LOOP
        v_def := pg_get_functiondef(f);
        v_def := regexp_replace(v_def, '(public\.)?camp_person_label\(', 'public.camp_person_name_for(', 'g');
        EXECUTE v_def;
        v_n := v_n + 1;
    END LOOP;
    RAISE NOTICE '257: % functions now pin the camper they start from', v_n;
END $$;

-- The offline import handles many campers in one call: each row starts clean.
DO $$
DECLARE
    f     oid;
    v_def text;
BEGIN
    FOR f IN SELECT p.oid FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
              WHERE n.nspname = 'public' AND p.proname = 'canteen_office_import_offline' LOOP
        v_def := pg_get_functiondef(f);
        IF position('clear_person_pins()' IN v_def) = 0 THEN
            v_def := regexp_replace(v_def,
                '(FOR r IN SELECT value FROM jsonb_array_elements\(p_rows\) LOOP)',
                E'\\1\n        PERFORM public.clear_person_pins();   -- 257: each row starts clean');
            IF position('clear_person_pins()' IN v_def) = 0 THEN
                RAISE EXCEPTION '257: could not find the row loop in canteen_office_import_offline';
            END IF;
            EXECUTE v_def;
        END IF;
    END LOOP;
END $$;


-- 242's own check looked for camp_person_label in the import; it now uses the
-- pinning form, which resolves by id just the same.
DO $$
DECLARE v_def text;
BEGIN
    IF to_regprocedure('public.verify_offline_import()') IS NOT NULL THEN
        v_def := pg_get_functiondef('public.verify_offline_import()'::regprocedure);
        IF position('camp_person_(label|name_for)' IN v_def) = 0 THEN
            EXECUTE replace(v_def, $q$~ 'camp_person_label'$q$, $q$~ 'camp_person_(label|name_for)'$q$);
        END IF;
    END IF;
END $$;


-- ─── the check ──────────────────────────────────────────────────────────────
-- For every camper, enrolled or departed: a call starting from their number
-- reaches them. For every ENROLLED camper: their stored name alone reaches
-- them. And no function that starts from a number still reads the name
-- without pinning it. Empty lists when right.
CREATE OR REPLACE FUNCTION public.verify_number_round_trip()
RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
DECLARE
    c         record;
    v_got     bigint;
    v_misses  jsonb := '[]'::jsonb;
    v_names   jsonb := '[]'::jsonb;
    v_n       bigint := 0;
BEGIN
    FOR c IN SELECT camp_id, person_id, source_key, deleted_at FROM camp_people WHERE kind = 'camper' LOOP
        v_n := v_n + 1;
        PERFORM public.clear_person_pins();
        v_got := public.camp_person_by_name(c.camp_id, public.camp_person_name_for(c.camp_id, c.person_id));
        IF v_got IS DISTINCT FROM c.person_id THEN
            v_misses := v_misses || jsonb_build_object('camp_id', c.camp_id, 'camperId', c.person_id,
                                                       'name', c.source_key, 'reaches', v_got);
        END IF;
        PERFORM public.clear_person_pins();
        IF c.deleted_at IS NULL THEN
            v_got := public.camp_person_by_name(c.camp_id, c.source_key);
            IF v_got IS DISTINCT FROM c.person_id THEN
                v_names := v_names || jsonb_build_object('camp_id', c.camp_id, 'camperId', c.person_id,
                                                         'name', c.source_key, 'reaches', v_got);
            END IF;
        END IF;
    END LOOP;
    PERFORM public.clear_person_pins();
    RETURN jsonb_build_object(
        'campers_checked', v_n,
        'numbers_that_miss_their_camper', v_misses,
        'enrolled_names_that_miss_their_camper', v_names,
        'functions_that_do_not_pin', COALESCE((
            SELECT jsonb_agg(p.proname ORDER BY p.proname)
              FROM pg_proc p
             WHERE p.oid IN (SELECT * FROM public._functions_that_must_pin())), '[]'::jsonb));
END;
$$;
REVOKE ALL ON FUNCTION public.verify_number_round_trip() FROM public, anon, authenticated;


-- ▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼
-- 258_a_parent_sees_only_their_own_child.sql
-- ▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲

-- ============================================================================
-- Migration 258: a parent sees only THEIR OWN child — decided by camper number.
--
-- THE CASE. A camper leaves. Next season a new child with the same name
-- enrols and gets a new camper number. Before this migration, everything
-- below went by the NAME, so the new child's parent was handed the departed
-- child's things, and the new child's own were filed on the departed child:
--
--   1. Health documents — the new child's parent saw the departed child's
--      shots, physicals and insurance cards (get_my_health_documents).
--   2. Photos — the new child's parent's gallery showed photos tagged with the
--      departed child, and could open them (get_my_camper_photos,
--      get_viewable_photo_ids, get_viewable_original_photo_ids).
--   3. Face recognition — the new child's parent's consent, and a WITHDRAWAL
--      of consent, was written on the departed child's face row: that table
--      held one row per NAME. The new child could not upload a front-facing
--      photo at all while the other's was on file.
--   4. The photo matcher merged both children's reference faces into one and
--      went on tagging new photos with a child who has left.
--   5. The post-acceptance form built a child's Camper Mail code from the
--      number found by name before the application's own number.
--
-- THE RULE, as everywhere since 248: a row with a number belongs to that
-- number. The name is used only for a row written before numbers.
--
-- Also: the office's health-document list carries each document's number.
--
-- HOW. Functions this file owns in full are replaced; the others are
-- rewritten in place, changing only the lines named, and the file stops with
-- a message if a function is not the text it expects. Safe to run twice.
--
-- Standalone. Paste into the Supabase SQL Editor and run. NOT part of
-- APPLY_BUNDLE.sql. Then run scripts/verify_identity_chain.sql: the 258 row
-- should read ok.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.get_my_health_documents(p_camp_id uuid)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER STABLE
SET search_path = public, pg_catalog
AS $$
DECLARE caller uuid := auth.uid(); result jsonb;
BEGIN
    IF caller IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'not_authenticated'); END IF;
    SELECT coalesce(jsonb_agg(jsonb_build_object(
        'id', s.id, 'camper_name', s.camper_name, 'person_id', s.person_id, 'file_name', s.file_name,
        'status', s.status, 'created_at', s.created_at
    ) ORDER BY s.created_at DESC), '[]'::jsonb)
    INTO result
    FROM link_health_submissions s
    WHERE s.camp_id = p_camp_id
      AND CASE WHEN s.person_id IS NOT NULL
               THEN public._parent_owns_person(p_camp_id, s.person_id)
               ELSE public._parent_owns_camper(p_camp_id, s.camper_name) END;
    RETURN jsonb_build_object('success', true, 'documents', result);
END;
$$;
REVOKE ALL ON FUNCTION public.get_my_health_documents(uuid) FROM public;
GRANT EXECUTE ON FUNCTION public.get_my_health_documents(uuid) TO authenticated;

CREATE OR REPLACE FUNCTION public.get_camp_health_documents(p_camp_id uuid)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER STABLE
SET search_path = public, pg_catalog
AS $$
DECLARE caller uuid := auth.uid(); result jsonb;
BEGIN
    IF caller IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'not_authenticated'); END IF;
    IF NOT EXISTS (SELECT 1 FROM camps c WHERE c.id = p_camp_id AND c.owner = caller)
       AND NOT EXISTS (SELECT 1 FROM camp_users u WHERE u.camp_id = p_camp_id AND u.user_id = caller) THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_a_member');
    END IF;
    SELECT coalesce(jsonb_agg(jsonb_build_object(
        'id', s.id, 'camper_name', s.camper_name, 'person_id', s.person_id, 'file_name', s.file_name,
        'file_type', s.file_type, 'file_data', s.file_data, 'note', s.note,
        'status', s.status, 'review_notes', s.review_notes,
        'reviewed_at', s.reviewed_at, 'created_at', s.created_at
    ) ORDER BY s.created_at DESC), '[]'::jsonb)
    INTO result
    FROM link_health_submissions s
    WHERE s.camp_id = p_camp_id;
    RETURN jsonb_build_object('success', true, 'documents', result);
END;
$$;
REVOKE ALL ON FUNCTION public.get_camp_health_documents(uuid) FROM public;
GRANT EXECUTE ON FUNCTION public.get_camp_health_documents(uuid) TO authenticated;

-- For scripts/verify_identity_chain.sql: parent read functions that still
-- decide ownership by a row's camper NAME alone. Should be empty.
CREATE OR REPLACE FUNCTION public.verify_parent_reads_by_number()
RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
    SELECT COALESCE(jsonb_agg(p.proname ORDER BY p.proname), '[]'::jsonb)
      FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
     WHERE n.nspname = 'public'
       AND p.prosrc ~ '_parent_owns_camper\s*\(\s*[^,]+,\s*[a-z_]+\.camper_name'
       AND p.prosrc !~ '_parent_owns_person\s*\(';
$$;
REVOKE ALL ON FUNCTION public.verify_parent_reads_by_number() FROM public, anon;
GRANT EXECUTE ON FUNCTION public.verify_parent_reads_by_number() TO authenticated, service_role;

-- ─── the post-acceptance form: the camper's code comes from their NUMBER ────
-- get_postaccept_bootstrap (209) built the Camper Mail code from the number
-- found by looking the camper's NAME up first, and the application's own
-- number second. The application's number goes first now, and the form is
-- told the number too. Rewritten in place: only these two lines change.
DO $$
DECLARE d text; n text;
BEGIN
    SELECT pg_get_functiondef(p.oid) INTO d
      FROM pg_proc p JOIN pg_namespace ns ON ns.oid = p.pronamespace
     WHERE ns.nspname = 'public' AND p.proname = 'get_postaccept_bootstrap';
    IF d IS NULL THEN
        RAISE NOTICE '258: get_postaccept_bootstrap is not here — nothing to do';
        RETURN;
    END IF;
    IF d ~ 'enroll_row ->> ''camperId'',\s*kv_value #>>' THEN
        RETURN;                                   -- already applied
    END IF;
    n := regexp_replace(d,
        'kv_value #>> ARRAY\[''roster'', v_camper_nm, ''camperId''\],\s*enroll_row ->> ''camperId'',',
        'enroll_row ->> ''camperId'',
                kv_value #>> ARRAY[''roster'', v_camper_nm, ''camperId''],');
    n := regexp_replace(n,
        '''camperName'', coalesce\(enroll_row ->> ''camperName'', ''''\),',
        '''camperName'', coalesce(enroll_row ->> ''camperName'', ''''),
        ''camperId'', CASE WHEN (enroll_row ->> ''camperId'') ~ ''^\d+$'' THEN (enroll_row ->> ''camperId'')::bigint END,');
    IF n = d OR n !~ '''camperId'', CASE WHEN' OR n !~ 'enroll_row ->> ''camperId'',\s*kv_value #>>' THEN
        RAISE EXCEPTION '258: get_postaccept_bootstrap is not the 209 text this expects — send this message to the builder';
    END IF;
    EXECUTE n;
END $$;

-- ─── the photo matcher's face index goes by camper NUMBER ───────────────────
-- get_camp_face_index (030) gathered each child's reference faces by NAME:
--
--     FROM link_camper_face_descriptors d WHERE d.camper_name = f.camper_name
--
-- When a camper leaves and a new child with the same name enrols, both
-- children's faces were merged into one reference, and the departed child's
-- face went on tagging new photos with the new child's name — photos a
-- parent then sees of somebody else's child. Now:
--   * each child's faces are gathered by their number (by name only for a
--     row that has none);
--   * a camper who has left does not tag today's photos;
--   * the index carries each child's number, so tags are filed on it.
CREATE OR REPLACE FUNCTION public.get_camp_face_index(p_camp_id uuid)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER STABLE
SET search_path = public, pg_catalog
AS $$
DECLARE caller uuid := auth.uid(); result jsonb;
BEGIN
    IF caller IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'not_authenticated'); END IF;
    IF NOT EXISTS (SELECT 1 FROM camps c WHERE c.id = p_camp_id AND c.owner = caller)
       AND NOT EXISTS (SELECT 1 FROM camp_users u WHERE u.camp_id = p_camp_id AND u.user_id = caller) THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_a_member');
    END IF;

    SELECT coalesce(jsonb_agg(jsonb_build_object(
        'camper_name', sub.camper_name,
        'person_id',   sub.person_id,
        'descriptors', sub.descriptors
    )), '[]'::jsonb)
    INTO result
    FROM (
        SELECT f.camper_name, f.person_id,
               (
                   SELECT coalesce(jsonb_agg(jsonb_build_object(
                       'descriptor', d.descriptor,
                       'model',      d.model,
                       'pose',       d.pose,
                       'source',     d.source,
                       'created_at', d.created_at
                   )), '[]'::jsonb)
                   FROM link_camper_face_descriptors d
                   WHERE d.camp_id = f.camp_id
                     AND CASE WHEN f.person_id IS NOT NULL AND d.person_id IS NOT NULL
                              THEN d.person_id = f.person_id
                              ELSE d.camper_name = f.camper_name END
               )
               ||
               -- legacy single descriptor, only when no v2 front/parent row exists
               CASE WHEN f.descriptor IS NOT NULL AND NOT EXISTS (
                        SELECT 1 FROM link_camper_face_descriptors d2
                        WHERE d2.camp_id = f.camp_id
                          AND CASE WHEN f.person_id IS NOT NULL AND d2.person_id IS NOT NULL
                                   THEN d2.person_id = f.person_id
                                   ELSE d2.camper_name = f.camper_name END
                          AND d2.model = 'faceapi-128' AND d2.pose = 'front' AND d2.source = 'parent'
                    )
                    THEN jsonb_build_array(jsonb_build_object(
                        'descriptor', f.descriptor, 'model', 'faceapi-128',
                        'pose', 'front', 'source', 'parent', 'created_at', f.updated_at))
                    ELSE '[]'::jsonb
               END AS descriptors
        FROM link_camper_faces f
        WHERE f.camp_id = p_camp_id AND f.consent = true
          -- a camper who has left is not in today's photos
          AND NOT EXISTS (SELECT 1 FROM camp_people cp
                           WHERE cp.camp_id = f.camp_id AND cp.kind = 'camper'
                             AND cp.person_id = f.person_id AND cp.deleted_at IS NOT NULL)
    ) sub
    WHERE jsonb_array_length(sub.descriptors) > 0;

    RETURN jsonb_build_object('success', true, 'faces', result);
END;
$$;
REVOKE ALL ON FUNCTION public.get_camp_face_index(uuid) FROM public;
GRANT EXECUTE ON FUNCTION public.get_camp_face_index(uuid) TO authenticated;

-- ─── one face row per CHILD, not per name ───────────────────────────────────
-- link_camper_faces was keyed PRIMARY KEY (camp_id, camper_name): one row per
-- NAME. When a camper leaves and a new child with the same name enrols, the
-- new child's parent's face-recognition consent — granting it, or WITHDRAWING
-- it — was written onto the departed child's row, and the new child never had
-- one. A parent's "no" to facial recognition landed on another child.
--
-- Now each camper number has its own row (a unique index on
-- (camp_id, person_id)); a row from before numbers keeps one per name. The
-- two functions that write the row — set_camper_face_consent and
-- submit_camper_headshot — upsert on the number, and keep the row's name
-- current. Rewritten in place: only their ON CONFLICT clauses change.
--
-- Rows already there: a child who was renamed can have two rows (226 explains
-- how). They are merged into the most recently updated one — that is the
-- parent's latest instruction, 226's rule — keeping a face descriptor from an
-- older row only where consent still stands.
DO $$
DECLARE r record; d text; n text; k int := 0;
BEGIN
    -- 1. merge duplicate rows of one child
    UPDATE link_camper_faces keep
       SET descriptor    = COALESCE(keep.descriptor, old.descriptor),
           headshot_data = COALESCE(keep.headshot_data, old.headshot_data)
      FROM (SELECT DISTINCT ON (camp_id, person_id) camp_id, person_id, descriptor, headshot_data
              FROM link_camper_faces
             WHERE person_id IS NOT NULL AND descriptor IS NOT NULL
             ORDER BY camp_id, person_id, updated_at DESC NULLS LAST) old
     WHERE keep.consent IS TRUE AND keep.camp_id = old.camp_id AND keep.person_id = old.person_id
       AND keep.ctid = (SELECT f.ctid FROM link_camper_faces f
                         WHERE f.camp_id = keep.camp_id AND f.person_id = keep.person_id
                         ORDER BY f.updated_at DESC NULLS LAST, f.camper_name LIMIT 1);
    DELETE FROM link_camper_faces f
     WHERE f.person_id IS NOT NULL
       AND f.ctid <> (SELECT g.ctid FROM link_camper_faces g
                       WHERE g.camp_id = f.camp_id AND g.person_id = f.person_id
                       ORDER BY g.updated_at DESC NULLS LAST, g.camper_name LIMIT 1);

    -- 2. the key: one row per number; one per name only for rows with none
    IF EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'public.link_camper_faces'::regclass
                  AND conname = 'link_camper_faces_pkey') THEN
        ALTER TABLE public.link_camper_faces DROP CONSTRAINT link_camper_faces_pkey;
    END IF;
    CREATE UNIQUE INDEX IF NOT EXISTS link_camper_faces_one_per_person
        ON public.link_camper_faces (camp_id, person_id) WHERE person_id IS NOT NULL;
    CREATE UNIQUE INDEX IF NOT EXISTS link_camper_faces_one_per_unnumbered_name
        ON public.link_camper_faces (camp_id, camper_name) WHERE person_id IS NULL;

    -- 3. the two writers upsert on the number
    FOR r IN SELECT p.oid FROM pg_proc p JOIN pg_namespace ns ON ns.oid = p.pronamespace
              WHERE ns.nspname = 'public'
                AND p.proname IN ('set_camper_face_consent', 'submit_camper_headshot')
                AND p.prosrc ~ 'INSERT INTO link_camper_faces'
    LOOP
        d := pg_get_functiondef(r.oid);
        n := regexp_replace(d,
            '(INSERT INTO link_camper_faces[^;]*?)ON CONFLICT \(camp_id, camper_name\) DO UPDATE\s+SET ',
            '\1ON CONFLICT (camp_id, person_id) WHERE person_id IS NOT NULL DO UPDATE
            SET camper_name = EXCLUDED.camper_name, ', 'g');
        IF n <> d THEN EXECUTE n; k := k + 1; END IF;
    END LOOP;
    IF EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace ns ON ns.oid = p.pronamespace
                WHERE ns.nspname = 'public' AND p.prosrc ~ 'INSERT INTO link_camper_faces'
                  AND p.prosrc ~ 'ON CONFLICT \(camp_id, camper_name\)') THEN
        RAISE EXCEPTION '258: a face writer still upserts by name — send this message to the builder';
    END IF;
END $$;

-- ─── a child's reference faces: one per pose per CHILD, not per name ────────
-- idx_lcfd_parent_pose (029) allowed one parent-uploaded face per pose per
-- NAME. A second child with the same name could not upload a front-facing
-- photo at all while the first child's was on file. Now it is one per pose per
-- child (by number), and per name only for rows with no number. A child
-- renamed before 258 can hold two for one pose; the newer is kept.
DO $$
BEGIN
    DELETE FROM link_camper_face_descriptors d
     WHERE d.source = 'parent' AND d.person_id IS NOT NULL
       AND EXISTS (SELECT 1 FROM link_camper_face_descriptors e
                    WHERE e.camp_id = d.camp_id AND e.person_id = d.person_id
                      AND e.model = d.model AND e.pose = d.pose AND e.source = 'parent'
                      AND (e.created_at, e.id::text) > (d.created_at, d.id::text));
    DROP INDEX IF EXISTS public.idx_lcfd_parent_pose;
    CREATE UNIQUE INDEX IF NOT EXISTS idx_lcfd_parent_pose_per_person
        ON public.link_camper_face_descriptors (camp_id, person_id, model, pose)
        WHERE source = 'parent' AND person_id IS NOT NULL;
    CREATE UNIQUE INDEX IF NOT EXISTS idx_lcfd_parent_pose_unnumbered
        ON public.link_camper_face_descriptors (camp_id, camper_name, model, pose)
        WHERE source = 'parent' AND person_id IS NULL;
END $$;

-- ─── what a parent sees of photos and faces, by camper NUMBER ───────────────
-- Four more parent reads decided "is this row my child's?" by the row's NAME:
--   get_my_camper_photos            — the parent's photo gallery
--   get_viewable_photo_ids          — may this parent open this photo
--   get_viewable_original_photo_ids — …and its full-resolution original
--   get_my_camper_face_status       — the face-recognition card
-- So the parent of a new child saw photos tagged with a departed child who
-- had the same name. The same rule as above, rewritten in place:
--
--     _parent_owns_camper(camp, t.camper_name)
--  →  CASE WHEN t.person_id IS NOT NULL THEN _parent_owns_person(camp, t.person_id)
--          ELSE _parent_owns_camper(camp, t.camper_name) END
--
-- and where two tables are joined on a camper, by number when both rows
-- have one (a photo purchase to its tag; a face to its reference photos).
DO $$
DECLARE r record; d text; n text;
BEGIN
    FOR r IN SELECT p.oid, p.proname FROM pg_proc p JOIN pg_namespace ns ON ns.oid = p.pronamespace
              WHERE ns.nspname = 'public'
                AND p.proname IN ('get_my_camper_photos', 'get_viewable_photo_ids',
                                  'get_viewable_original_photo_ids', 'get_my_camper_face_status')
                AND p.prosrc !~ '_parent_owns_person\s*\('
    LOOP
        d := pg_get_functiondef(r.oid);
        n := regexp_replace(d,
            '(public\.)?_parent_owns_camper\(\s*([a-z_.]+)\s*,\s*([a-z_]+)\.camper_name\s*\)',
            '(CASE WHEN \3.person_id IS NOT NULL THEN public._parent_owns_person(\2, \3.person_id) ELSE public._parent_owns_camper(\2, \3.camper_name) END)',
            'g');
        n := regexp_replace(n,
            '([a-z_]+)\.camper_name = ([a-z_]+)\.camper_name',
            '(CASE WHEN \1.person_id IS NOT NULL AND \2.person_id IS NOT NULL THEN \1.person_id = \2.person_id ELSE \1.camper_name = \2.camper_name END)',
            'g');
        IF n = d THEN
            RAISE EXCEPTION '258: % is not the text this expects — send this message to the builder', r.proname;
        END IF;
        EXECUTE n;
    END LOOP;
END $$;


-- ▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼
-- 259_a_roster_key_belongs_to_one_child.sql
-- ▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲

-- ============================================================================
-- Migration 259: a roster key belongs to ONE child, for as long as anything
-- about that child exists.
--
-- WHY. The pages keep every camper under a roster key — usually the camper's
-- name ("Avi Katz"; a second child with the same name is "Avi Katz #11" and
-- shows as "Avi Katz"). Records saved over the years reach a camper through
-- that key: bunk lists, families, Go addresses, health logs, luggage, orders.
-- Since 248-258 every such record also carries the camper NUMBER, and every
-- database function decides by the number. But a record written before its
-- number, or a page looking a saved key up in the roster, still goes by the
-- key — and until now a key could pass from one child to another:
--
--   * Avi Katz #10 leaves (his records are kept: money, history). A new Avi
--     Katz enrols and is numbered #11 — under the SAME key "Avi Katz". Every
--     record saved under "Avi Katz" now reaches the new child.
--   * Ayala Weiss is renamed Ayala Weiss-Katz. A new Ayala Weiss enrols under
--     the key "Ayala Weiss" — and reaches everything saved under Ayala's
--     old name.
--
-- THE RULE THIS FILE INSTALLS. A roster key belongs to the first child who
-- held it, until that child is erased (254). camp_person_keys remembers every
-- key each child has held. A save that gives a key to a DIFFERENT child — a
-- new camper, or a stated number — is not refused (a roster save must never
-- fail); the new child is filed under their own key instead:
--
--     "Avi Katz"  →  "Avi Katz #11"   (displayName "Avi Katz", camperId 11)
--
-- so no saved key can ever reach a child it was not written for. The Me page
-- adopts the new key on its next check (and picks it itself up front when it
-- can see the key is held: get_camper_numbers now lists held keys).
--
-- Erasing a child (254) deletes their rows here with everything else — the
-- key is free again only when nothing about them is left. Merging two
-- campers (254) moves the gone camper's keys to the one kept.
--
-- EXISTING DATA. Every child's current key is recorded. Where a key is today
-- shared by a live child and a departed one, it is given to the live child
-- (that is who the pages mean by it now); verify_roster_keys() reports those
-- camps so the office can look at the departed child's old records.
--
-- Standalone. Paste into the Supabase SQL Editor after 258 and run. Safe to
-- run twice. NOT part of APPLY_BUNDLE.sql. Then run
-- scripts/verify_identity_chain.sql: the 259 row should read ok.
-- ============================================================================

SET LOCAL lock_timeout = '15s';
LOCK TABLE public.camp_state_kv IN ACCESS EXCLUSIVE MODE;

CREATE TABLE IF NOT EXISTS public.camp_person_keys (
    camp_id    uuid   NOT NULL,
    kind       text   NOT NULL DEFAULT 'camper',
    key        text   NOT NULL,
    person_id  bigint NOT NULL,
    first_at   timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (camp_id, kind, key)
);
CREATE INDEX IF NOT EXISTS camp_person_keys_person ON public.camp_person_keys (camp_id, person_id);
ALTER TABLE public.camp_person_keys ENABLE ROW LEVEL SECURITY;
-- Read and written only by the functions below (SECURITY DEFINER).
REVOKE ALL ON public.camp_person_keys FROM anon, authenticated;

-- Every key held today: live children first, so a key shared today by a live
-- child and a departed one goes to the live child.
INSERT INTO public.camp_person_keys (camp_id, kind, key, person_id)
SELECT DISTINCT ON (camp_id, source_key) camp_id, 'camper', source_key, person_id
  FROM public.camp_people
 WHERE kind = 'camper' AND source_key IS NOT NULL AND source_key <> ''
 ORDER BY camp_id, source_key, (deleted_at IS NULL) DESC, updated_at DESC NULLS LAST
ON CONFLICT DO NOTHING;


-- The key a child must be filed under instead of p_key, which belongs to
-- somebody else: "<key> #<number>", or "<key> #<number>-2"… if even that is
-- taken. The trailing " #<number>" is what every page strips for display.
CREATE OR REPLACE FUNCTION public._own_roster_key(
    p_camp_id uuid, p_key text, p_person_id bigint, p_doc jsonb)
RETURNS text
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
DECLARE
    v_base text := regexp_replace(p_key, '\s#\d+(?:-\d+)?$', '');
    v_try  text;
    n      int := 1;
BEGIN
    LOOP
        v_try := v_base || ' #' || p_person_id || CASE WHEN n > 1 THEN '-' || n ELSE '' END;
        EXIT WHEN NOT (COALESCE(p_doc, '{}'::jsonb) ? v_try)
              AND NOT EXISTS (SELECT 1 FROM camp_person_keys
                               WHERE camp_id = p_camp_id AND kind = 'camper'
                                 AND key = v_try AND person_id <> p_person_id);
        n := n + 1;
        IF n > 50 THEN RETURN v_base || ' #' || p_person_id || '-' || md5(random()::text); END IF;
    END LOOP;
    RETURN v_try;
END;
$$;
REVOKE ALL ON FUNCTION public._own_roster_key(uuid, text, bigint, jsonb) FROM public, anon, authenticated;


-- Who holds a key: the child it was first given to, while anything about
-- them exists. A holder whose identity row is gone (erased by code older than
-- this file) holds nothing.
CREATE OR REPLACE FUNCTION public._roster_key_holder(p_camp_id uuid, p_key text)
RETURNS bigint
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
    SELECT k.person_id
      FROM camp_person_keys k
     WHERE k.camp_id = p_camp_id AND k.kind = 'camper' AND k.key = p_key
       AND EXISTS (SELECT 1 FROM camp_people p
                    WHERE p.camp_id = k.camp_id AND p.person_id = k.person_id AND p.kind = 'camper')
$$;
REVOKE ALL ON FUNCTION public._roster_key_holder(uuid, text) FROM public, anon, authenticated;


-- ─── the trigger: number, then file each child under a key that is theirs ───
CREATE OR REPLACE FUNCTION public.number_camp_campers()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
DECLARE
    v_old    jsonb := '{}'::jsonb;
    v_new    jsonb := '{}'::jsonb;
    v_all    boolean := COALESCE(current_setting('campistry.renumber_all', true), '') = 'on';
    v_ids    jsonb;
    e        record;
    v_holder bigint;
    v_back   record;
    v_key    text;
    v_entry  jsonb;
    v_id     bigint;
    v_prev   jsonb;
BEGIN
    IF TG_OP = 'UPDATE' AND NOT v_all AND jsonb_typeof(OLD.value -> 'camperRoster') = 'object' THEN
        v_old := OLD.value -> 'camperRoster';
    END IF;
    IF jsonb_typeof(NEW.value -> 'camperRoster') = 'object' THEN
        v_new := NEW.value -> 'camperRoster';
    END IF;

    -- What is saved now. An upsert (INSERT … ON CONFLICT DO UPDATE, which is
    -- how the pages save) runs this trigger as an INSERT first, with no OLD.
    IF TG_OP = 'UPDATE' THEN
        v_prev := OLD.value -> 'camperRoster';
    ELSE
        SELECT value -> 'camperRoster' INTO v_prev FROM camp_state_kv
         WHERE camp_id = NEW.camp_id AND key = NEW.key;
    END IF;
    IF jsonb_typeof(v_prev) IS DISTINCT FROM 'object' THEN v_prev := '{}'::jsonb; END IF;
    -- …and the numbering compares against it too. Before this, the INSERT
    -- run compared against nothing, so a RENAME (the same number under a new
    -- key) looked like a stranger claiming a number: the camper was given a
    -- new one, and their old number — with their money and history — was
    -- marked departed.
    IF TG_OP = 'INSERT' AND NOT v_all THEN
        v_old := v_prev;
    END IF;

    -- 1. A page that has not yet adopted a key this trigger gave (it still
    --    saves the child under the key it typed, and without the number) is
    --    put back under that child's own key before numbering — otherwise
    --    every such save would number a "new" child.
    FOR e IN SELECT n.key, n.value FROM jsonb_each(v_new) n(key, value)
              WHERE jsonb_typeof(n.value) = 'object'
                AND public._stated_person_id(n.value ->> 'camperId') IS NULL
    LOOP
        v_holder := public._roster_key_holder(NEW.camp_id, e.key);
        CONTINUE WHEN v_holder IS NULL
                   OR EXISTS (SELECT 1 FROM camp_people p WHERE p.camp_id = NEW.camp_id
                               AND p.person_id = v_holder AND p.kind = 'camper'
                               AND p.deleted_at IS NULL AND p.source_key = e.key);
        SELECT p.person_id, p.source_key INTO v_back
          FROM camp_people p
         WHERE p.camp_id = NEW.camp_id AND p.kind = 'camper' AND p.deleted_at IS NULL
           AND p.person_id <> v_holder
           AND regexp_replace(p.source_key, '\s#\d+(?:-\d+)?$', '') = e.key
           -- saved under that key before, or filed so a moment ago by this
           -- same save (an upsert runs this trigger twice)
           AND ((v_prev ? p.source_key) OR p.updated_at = now())
           AND NOT (v_new ? p.source_key)
         ORDER BY p.updated_at DESC NULLS LAST
         LIMIT 1;
        IF FOUND THEN
            v_new := (v_new - e.key) || jsonb_build_object(v_back.source_key,
                       e.value || jsonb_build_object('camperId', v_back.person_id,
                                                     'displayName', COALESCE(NULLIF(e.value ->> 'displayName', ''), e.key)));
        END IF;
    END LOOP;

    v_ids := public._number_people(NEW.camp_id, 'camper', v_old, v_new, 'camperId', 'name', v_all);

    -- 2. Every entry looked at now carries exactly the number it holds, under
    --    a key that is its own.
    FOR e IN SELECT key, value FROM jsonb_each(v_ids) LOOP
        v_id := (e.value #>> '{}')::bigint;
        v_key := e.key;
        v_holder := public._roster_key_holder(NEW.camp_id, e.key);
        IF v_holder IS NOT NULL AND v_holder <> v_id THEN
            v_key := public._own_roster_key(NEW.camp_id, e.key, v_id, v_new);
            v_entry := (v_new -> e.key)
                       || jsonb_build_object('displayName',
                              COALESCE(NULLIF(v_new #>> ARRAY[e.key, 'displayName'], ''),
                                       NULLIF(v_new #>> ARRAY[e.key, 'name'], ''),
                                       regexp_replace(e.key, '\s#\d+(?:-\d+)?$', '')));
            v_new := (v_new - e.key) || jsonb_build_object(v_key, v_entry);
            UPDATE camp_people SET source_key = v_key, updated_at = now()
             WHERE camp_id = NEW.camp_id AND person_id = v_id AND kind = 'camper';
        END IF;
        IF (v_new #> ARRAY[v_key, 'camperId']) IS DISTINCT FROM to_jsonb(v_id) THEN
            v_new := jsonb_set(v_new, ARRAY[v_key, 'camperId'], to_jsonb(v_id), true);
        END IF;
        INSERT INTO camp_person_keys (camp_id, kind, key, person_id)
        VALUES (NEW.camp_id, 'camper', v_key, v_id)
        ON CONFLICT (camp_id, kind, key) DO UPDATE
           SET person_id = EXCLUDED.person_id, first_at = now()
         WHERE NOT EXISTS (SELECT 1 FROM camp_people p
                            WHERE p.camp_id = camp_person_keys.camp_id
                              AND p.person_id = camp_person_keys.person_id AND p.kind = 'camper');
    END LOOP;

    IF v_new IS DISTINCT FROM COALESCE(NEW.value -> 'camperRoster', '{}'::jsonb) THEN
        NEW.value := jsonb_set(NEW.value, '{camperRoster}', v_new, true);
    END IF;
    RETURN NEW;
END;
$$;
REVOKE ALL ON FUNCTION public.number_camp_campers() FROM public, anon, authenticated;


-- ─── what the Me page asks: also, which keys a new child may not have ───────
CREATE OR REPLACE FUNCTION public.get_camper_numbers(p_camp_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
BEGIN
    IF NOT public.camp_reader(p_camp_id) THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_authorized');
    END IF;
    RETURN jsonb_build_object(
        'success', true,
        'campers', COALESCE((SELECT jsonb_object_agg(source_key, person_id)
                               FROM camp_people
                              WHERE camp_id = p_camp_id AND kind = 'camper'
                                AND deleted_at IS NULL), '{}'::jsonb),
        'next', GREATEST(
                  COALESCE((SELECT max(person_id) + 1 FROM camp_people WHERE camp_id = p_camp_id), 1),
                  COALESCE((SELECT next_id FROM camp_person_seq WHERE camp_id = p_camp_id), 1)),
        'departed', COALESCE((SELECT jsonb_object_agg(person_id::text, source_key)
                                FROM camp_people
                               WHERE camp_id = p_camp_id AND deleted_at IS NOT NULL), '{}'::jsonb),
        -- Keys that belong to a child other than whoever shows them today (a
        -- departed child, or a renamed child's old name): a NEW child may not
        -- be filed under one. {key: number of the child it belongs to}
        'held_keys', COALESCE((SELECT jsonb_object_agg(k.key, k.person_id)
                                 FROM camp_person_keys k
                                WHERE k.camp_id = p_camp_id AND k.kind = 'camper'
                                  AND EXISTS (SELECT 1 FROM camp_people p
                                               WHERE p.camp_id = k.camp_id AND p.person_id = k.person_id
                                                 AND p.kind = 'camper')
                                  AND NOT EXISTS (SELECT 1 FROM camp_people p
                                                   WHERE p.camp_id = k.camp_id AND p.person_id = k.person_id
                                                     AND p.kind = 'camper' AND p.deleted_at IS NULL
                                                     AND p.source_key = k.key)), '{}'::jsonb));
END;
$$;
REVOKE ALL ON FUNCTION public.get_camper_numbers(uuid) FROM public, anon;
GRANT EXECUTE ON FUNCTION public.get_camper_numbers(uuid) TO authenticated, service_role;


-- ─── the invariant, as a question anyone can ask ────────────────────────────
-- keys_shown_by_the_wrong_child must be []: a roster entry whose key belongs
-- to another child. keys_shared_before_259 lists camps where, before this
-- file, a key was held by a live child and a departed one at once — the
-- departed child's older records may be filed under the live child's key.
CREATE OR REPLACE FUNCTION public.verify_roster_keys()
RETURNS jsonb
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
    SELECT jsonb_build_object(
        'keys_shown_by_the_wrong_child', COALESCE((
            SELECT jsonb_agg(jsonb_build_object('camp_id', s.camp_id, 'key', e.key,
                                                'shows', public._stated_person_id(e.value ->> 'camperId'),
                                                'belongs_to', public._roster_key_holder(s.camp_id, e.key)))
              FROM camp_state_kv s
              CROSS JOIN LATERAL jsonb_each(CASE WHEN jsonb_typeof(s.value -> 'camperRoster') = 'object'
                                                 THEN s.value -> 'camperRoster' ELSE '{}'::jsonb END) e
             WHERE s.key = 'app1' AND jsonb_typeof(e.value) = 'object'
               AND public._roster_key_holder(s.camp_id, e.key) IS DISTINCT FROM
                   public._stated_person_id(e.value ->> 'camperId')), '[]'::jsonb),
        'keys_shared_before_259', COALESCE((
            SELECT jsonb_agg(jsonb_build_object('camp_id', a.camp_id, 'key', a.source_key,
                                                'live', a.person_id, 'departed', b.person_id))
              FROM camp_people a JOIN camp_people b
                ON b.camp_id = a.camp_id AND b.kind = 'camper' AND b.source_key = a.source_key
               AND b.deleted_at IS NOT NULL
             WHERE a.kind = 'camper' AND a.deleted_at IS NULL), '[]'::jsonb),
        'unrecorded_keys', (SELECT count(*) FROM camp_people p
                             WHERE p.kind = 'camper' AND p.source_key IS NOT NULL
                               AND NOT EXISTS (SELECT 1 FROM camp_person_keys k
                                                WHERE k.camp_id = p.camp_id AND k.kind = 'camper'
                                                  AND k.key = p.source_key)));
$$;
REVOKE ALL ON FUNCTION public.verify_roster_keys() FROM public, anon;
GRANT EXECUTE ON FUNCTION public.verify_roster_keys() TO authenticated, service_role;


-- ─── erasing a child clears every key they held ─────────────────────────────
-- 254's erase clears saved documents of the child's NUMBER, and of their
-- current key only when no enrolled camper shares their name — a shared name
-- could be somebody else's. Since this file a key is one child's, so every
-- key the child ever held (their current one and any older name) can be
-- cleared safely: nobody else can be filed under it. Without this, a key
-- freed by the erase could be given to a new child and reach a record the
-- erase left behind under it.
--
-- The erase itself is 254's, unchanged, renamed _erase_camper_254 and called
-- from here. Keys a live camper shows today are never touched, and a record
-- that carries ANOTHER child's number is never touched, whatever it is named.

-- The number a saved record carries, if any.
CREATE OR REPLACE FUNCTION public._json_person_id(p jsonb)
RETURNS bigint
LANGUAGE sql
IMMUTABLE
SET search_path = public, pg_catalog
AS $$
    SELECT CASE WHEN jsonb_typeof(p) = 'object' THEN
        COALESCE(public._stated_person_id(p ->> 'camperId'),  public._stated_person_id(p ->> 'personId'),
                 public._stated_person_id(p ->> 'person_id'), public._stated_person_id(p ->> 'camper_id'))
    END
$$;

-- Everything in a saved document filed under p_key — a map entry keyed by it,
-- a list item that is it, a record naming it — removed, unless the thing
-- carries a different child's number. Money subtrees are left alone (254).
CREATE OR REPLACE FUNCTION public._scrub_key_json(p_doc jsonb, p_id bigint, p_key text)
RETURNS jsonb
LANGUAGE plpgsql
IMMUTABLE
SET search_path = public, pg_catalog
AS $$
DECLARE
    v_out  jsonb;
    e      record;
    v_pid  bigint;
    v_keep text[] := public._erase_keeps_money_keys();
BEGIN
    IF jsonb_typeof(p_doc) = 'object' THEN
        v_out := '{}'::jsonb;
        FOR e IN SELECT key, value FROM jsonb_each(p_doc) LOOP
            v_pid := public._json_person_id(e.value);
            IF e.key = p_key AND (v_pid IS NULL OR v_pid = p_id) THEN
                CONTINUE;
            ELSIF e.key = ANY (v_keep) THEN
                v_out := v_out || jsonb_build_object(e.key, e.value);
            ELSE
                v_out := v_out || jsonb_build_object(e.key, public._scrub_key_json(e.value, p_id, p_key));
            END IF;
        END LOOP;
        RETURN v_out;
    ELSIF jsonb_typeof(p_doc) = 'array' THEN
        v_out := '[]'::jsonb;
        FOR e IN SELECT value FROM jsonb_array_elements(p_doc) LOOP
            v_pid := public._json_person_id(e.value);
            IF jsonb_typeof(e.value) = 'object'
               AND (e.value ->> 'camperName' = p_key OR e.value ->> 'camper' = p_key)
               AND (v_pid IS NULL OR v_pid = p_id) THEN
                CONTINUE;
            ELSIF jsonb_typeof(e.value) = 'string' AND e.value #>> '{}' = p_key THEN
                CONTINUE;
            END IF;
            v_out := v_out || jsonb_build_array(public._scrub_key_json(e.value, p_id, p_key));
        END LOOP;
        RETURN v_out;
    END IF;
    RETURN p_doc;
END;
$$;
DO $$
BEGIN
    IF to_regprocedure('public._erase_camper_254(uuid,bigint,boolean)') IS NULL THEN
        ALTER FUNCTION public.erase_camper(uuid, bigint, boolean) RENAME TO _erase_camper_254;
    END IF;
    REVOKE ALL ON FUNCTION public._erase_camper_254(uuid, bigint, boolean) FROM public, anon, authenticated;
END $$;

CREATE OR REPLACE FUNCTION public.erase_camper(
    p_camp_id   uuid,
    p_person_id bigint,
    p_confirm   boolean DEFAULT false
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
DECLARE
    v_keys  text[];
    v       jsonb;
    d       record;
    k       text;
    v_new   jsonb;
    v_docs  text[] := '{}';
BEGIN
    SELECT array_agg(key ORDER BY key) INTO v_keys
      FROM camp_person_keys
     WHERE camp_id = p_camp_id AND kind = 'camper' AND person_id = p_person_id;

    v := public._erase_camper_254(p_camp_id, p_person_id, p_confirm);
    IF (v ->> 'success')::boolean IS NOT TRUE OR v_keys IS NULL THEN
        RETURN v;
    END IF;

    FOR d IN
        SELECT key, value FROM camp_state_kv
         WHERE camp_id = p_camp_id
           AND key NOT IN ('campistryMeFinance', 'campistryMePayroll')
         FOR UPDATE
    LOOP
        v_new := d.value;
        FOREACH k IN ARRAY v_keys LOOP
            CONTINUE WHEN EXISTS (SELECT 1 FROM camp_people q
                                   WHERE q.camp_id = p_camp_id AND q.kind = 'camper'
                                     AND q.deleted_at IS NULL AND q.source_key = k
                                     AND q.person_id <> p_person_id);
            v_new := public._scrub_key_json(v_new, p_person_id, k);
        END LOOP;
        IF v_new IS DISTINCT FROM d.value THEN
            v_docs := v_docs || d.key;
            IF p_confirm THEN
                UPDATE camp_state_kv SET value = v_new, updated_at = now()
                 WHERE camp_id = p_camp_id AND key = d.key;
            END IF;
        END IF;
    END LOOP;

    RETURN v || jsonb_build_object('keys_released', to_jsonb(v_keys),
                                   'documents_cleared_by_key', to_jsonb(v_docs));
END;
$$;
REVOKE ALL ON FUNCTION public.erase_camper(uuid, bigint, boolean) FROM public, anon;
GRANT EXECUTE ON FUNCTION public.erase_camper(uuid, bigint, boolean) TO authenticated, service_role;


-- ─── a parent's form submissions carry the child's number ───────────────────
-- The parent portal decides "has this form been sent for this child?" from
-- get_my_form_responses (013), which returned only the name. It returns the
-- number too, and the portal matches by it.
CREATE OR REPLACE FUNCTION public.get_my_form_responses()
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
STABLE
SET search_path = public, pg_catalog
AS $$
DECLARE caller uuid := auth.uid(); result jsonb;
BEGIN
    IF caller IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_authenticated');
    END IF;

    SELECT coalesce(jsonb_agg(jsonb_build_object(
        'id',          r.id,
        'form_id',     r.form_id,
        'form_name',   r.form_name,
        'mode',        r.mode,
        'camper_name', r.camper_name,
        'person_id',   r.person_id,
        'created_at',  r.created_at
    ) ORDER BY r.created_at DESC), '[]'::jsonb)
    INTO result
    FROM link_form_responses r
    WHERE r.user_id = caller;

    RETURN jsonb_build_object('success', true, 'responses', result);
END;
$$;
REVOKE ALL ON FUNCTION public.get_my_form_responses() FROM public;
GRANT EXECUTE ON FUNCTION public.get_my_form_responses() TO authenticated;


-- ▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼
-- 260_numbers_stay_with_their_child.sql
-- ▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲

-- ============================================================================
-- Migration 260: a camper's number stays with that child — in a family's
-- invitation, through a renumber, after an erase, and after the 253 rename
-- bug.   (Ted TED-010, TED-011, TED-012, TED-016 … TED-021)
--
-- 1. MOVED NUMBERS. When the office types a new Camper ID (1 → 7), the
--    child's rows in the tables move to 7 (237). Now the move is also
--    WRITTEN DOWN (camp_person_renumbers), and from then on:
--      * every saved document is rewritten to 7 — right after the save that
--        made the change, never inside it (a save writes several documents
--        in one statement, and rewriting one of them from inside another's
--        trigger made the whole save fail: TED-016);
--      * a document saved LATER with the old number (a tab opened before the
--        change) is corrected as it is saved;
--      * every family invitation that says 1 now says 7 (TED-017);
--      * number 1 is never given to anybody else: it is not minted, and a
--        roster entry asking for it is either this child (then it gets 7) or
--        somebody else (then it gets a number of its own).
--
-- 2. INVITATIONS. Each slot's number is decided on every save, not only
--    when the names change (TED-010, TED-018):
--      * the number the office sent for that child (camper_data camperId);
--      * else the number the slot already had, carried through any move;
--      * else the enrolled camper who holds that roster key — only one who
--        was already there when the invitation was last decided (232);
--    and never a departed child found by name. The office's repair,
--    restamp_parent_invite, decides the same way (TED-019).
--
-- 3. RENAME + RENUMBER IN ONE EDIT (TED-020). The Me page tells the server
--    which number the child had ("renumberedFrom"); the child is renamed and
--    renumbered as ONE person. The hint is never stored.
--
-- 4. AN ERASED CHILD STAYS ERASED (TED-021). Erasing a child remembers their
--    number. A roster save that still carries them (a tab opened before the
--    erase) does not bring them back; a child added again on purpose — the
--    page stamps addedAt — does.
--
-- 5. THE 253 RENAME BUG (TED-011). split_renames() lists every child that
--    bug split in two (dry run). split_renames(true) puts each back together
--    on their original number — but only where nothing else could be that
--    child: a sibling removed in the same save, or an old record with no
--    birthday or email, leaves the child for a person to decide
--    ('needs_a_person').
--
-- Standalone. Paste into the Supabase SQL Editor after 259 and run. Safe to
-- run twice. Then run scripts/verify_identity_chain.sql and read the 260 row.
-- ============================================================================

SET LOCAL lock_timeout = '15s';
LOCK TABLE public.camp_state_kv IN ACCESS EXCLUSIVE MODE;


-- ─── 0. what is remembered ──────────────────────────────────────────────────
-- A number that was moved to another: from_id is never given out again while
-- the child it moved to exists. Chains are kept flat (1→7, then 7→9, is 1→9).
CREATE TABLE IF NOT EXISTS public.camp_person_renumbers (
    camp_id    uuid   NOT NULL,
    from_id    bigint NOT NULL,
    to_id      bigint NOT NULL,
    moved_at   timestamptz NOT NULL DEFAULT now(),
    applied_at timestamptz,
    PRIMARY KEY (camp_id, from_id)
);
CREATE INDEX IF NOT EXISTS camp_person_renumbers_pending
    ON public.camp_person_renumbers (camp_id) WHERE applied_at IS NULL;
ALTER TABLE public.camp_person_renumbers ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.camp_person_renumbers FROM anon, authenticated;

-- A child who was erased: their number is free for a NEW child, but a saved
-- copy of the erased child does not bring them back.
CREATE TABLE IF NOT EXISTS public.camp_erased_people (
    camp_id    uuid   NOT NULL,
    person_id  bigint NOT NULL,
    key        text,
    erased_at  timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (camp_id, person_id)
);
ALTER TABLE public.camp_erased_people ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.camp_erased_people FROM anon, authenticated;

-- A roster key or a name as the pages show it, for comparing two names:
-- without the " #<number>" a shared name is filed under, case and spaces aside.
CREATE OR REPLACE FUNCTION public._name_base(p text)
RETURNS text
LANGUAGE sql
IMMUTABLE
SET search_path = public, pg_catalog
AS $$
    SELECT lower(btrim(regexp_replace(COALESCE(p, ''), '\s#\d+(?:-\d+)?\s*$', '')))
$$;

-- The number a child has today, following any move.
CREATE OR REPLACE FUNCTION public._current_person_number(p_camp_id uuid, p_id bigint)
RETURNS bigint
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
DECLARE v bigint := p_id; v_to bigint; n int := 0;
BEGIN
    IF p_id IS NULL THEN RETURN NULL; END IF;
    LOOP
        SELECT to_id INTO v_to FROM camp_person_renumbers WHERE camp_id = p_camp_id AND from_id = v;
        EXIT WHEN NOT FOUND OR v_to = v;
        v := v_to; n := n + 1;
        EXIT WHEN n > 20;
    END LOOP;
    RETURN v;
END;
$$;
REVOKE ALL ON FUNCTION public._current_person_number(uuid, bigint) FROM public, anon, authenticated;

-- p_doc with every record's number that is a key of p_map ({"1": 7, …})
-- replaced by its value (camperId, personId, person_id, camper_id — as a
-- number or a string). ONE pass over the document, whatever the number of
-- moves (TED-024): each object is rebuilt with a single aggregate, and only
-- objects and arrays are descended into.
CREATE OR REPLACE FUNCTION public._json_renumber_map(p_doc jsonb, p_map jsonb)
RETURNS jsonb
LANGUAGE plpgsql
IMMUTABLE
SET search_path = public, pg_catalog
AS $$
DECLARE v_out jsonb;
BEGIN
    IF jsonb_typeof(p_doc) = 'object' THEN
        SELECT COALESCE(jsonb_object_agg(e.key,
                 CASE
                   WHEN jsonb_typeof(e.value) IN ('object', 'array')
                     THEN public._json_renumber_map(e.value, p_map)
                   WHEN e.key IN ('camperId', '_camperId', 'personId', 'person_id', 'camper_id')
                        AND jsonb_typeof(e.value) IN ('number', 'string')
                        AND p_map ? COALESCE(public._stated_person_id(e.value #>> '{}')::text, '')
                     THEN CASE WHEN jsonb_typeof(e.value) = 'string'
                               THEN to_jsonb(p_map ->> public._stated_person_id(e.value #>> '{}')::text)
                               ELSE p_map -> public._stated_person_id(e.value #>> '{}')::text END
                   ELSE e.value
                 END), '{}'::jsonb)
          INTO v_out FROM jsonb_each(p_doc) e;
        RETURN v_out;
    ELSIF jsonb_typeof(p_doc) = 'array' THEN
        SELECT COALESCE(jsonb_agg(CASE WHEN jsonb_typeof(x.value) IN ('object', 'array')
                                       THEN public._json_renumber_map(x.value, p_map) ELSE x.value END
                                  ORDER BY x.ord), '[]'::jsonb)
          INTO v_out FROM jsonb_array_elements(p_doc) WITH ORDINALITY x(value, ord);
        RETURN v_out;
    END IF;
    RETURN p_doc;
END;
$$;

-- One move: the same walk with a map of one.
CREATE OR REPLACE FUNCTION public._json_renumber(p_doc jsonb, p_from bigint, p_to bigint)
RETURNS jsonb
LANGUAGE sql
IMMUTABLE
SET search_path = public, pg_catalog
AS $$
    SELECT public._json_renumber_map(p_doc, jsonb_build_object(p_from::text, p_to))
$$;

-- p_doc with the number p_id taken off every record that carries it (the
-- record itself is kept). Used on money an erased child leaves behind: the
-- amounts stay in the books, but no longer point at a number that can be
-- given to a new child.
CREATE OR REPLACE FUNCTION public._detach_person_json(p_doc jsonb, p_id bigint)
RETURNS jsonb
LANGUAGE plpgsql
IMMUTABLE
SET search_path = public, pg_catalog
AS $$
DECLARE v_out jsonb;
BEGIN
    IF jsonb_typeof(p_doc) = 'object' THEN
        SELECT COALESCE(jsonb_object_agg(e.key,
                 CASE WHEN jsonb_typeof(e.value) IN ('object', 'array')
                      THEN public._detach_person_json(e.value, p_id) ELSE e.value END), '{}'::jsonb)
          INTO v_out FROM jsonb_each(p_doc) e
         WHERE NOT (e.key IN ('camperId', '_camperId', 'personId', 'person_id', 'camper_id')
                    AND jsonb_typeof(e.value) IN ('number', 'string')
                    AND public._stated_person_id(e.value #>> '{}') = p_id);
        RETURN v_out;
    ELSIF jsonb_typeof(p_doc) = 'array' THEN
        SELECT COALESCE(jsonb_agg(CASE WHEN jsonb_typeof(x.value) IN ('object', 'array')
                                       THEN public._detach_person_json(x.value, p_id) ELSE x.value END
                                  ORDER BY x.ord), '[]'::jsonb)
          INTO v_out FROM jsonb_array_elements(p_doc) WITH ORDINALITY x(value, ord);
        RETURN v_out;
    END IF;
    RETURN p_doc;
END;
$$;

-- The same, for a number that has since been given to a NEW child: only a
-- record that carries the number AND names the erased child (camperName,
-- camper, name) loses the number — that is a stale copy of the erased child
-- (a tab opened before the erase), never the new child's own record (TED-021).
CREATE OR REPLACE FUNCTION public._detach_named_json(p_doc jsonb, p_id bigint, p_name text)
RETURNS jsonb
LANGUAGE plpgsql
IMMUTABLE
SET search_path = public, pg_catalog
AS $$
DECLARE
    v_out jsonb;
    v_own boolean;
BEGIN
    IF jsonb_typeof(p_doc) = 'object' THEN
        v_own := COALESCE(p_name, '') <> '' AND EXISTS (
                   SELECT 1 FROM jsonb_each_text(p_doc) f
                    WHERE f.key IN ('camperName', 'camper', 'name', 'displayName')
                      AND public._name_base(f.value) = p_name)
                 AND EXISTS (
                   SELECT 1 FROM jsonb_each(p_doc) f
                    WHERE f.key IN ('camperId', '_camperId', 'personId', 'person_id', 'camper_id')
                      AND jsonb_typeof(f.value) IN ('number', 'string')
                      AND public._stated_person_id(f.value #>> '{}') = p_id);
        SELECT COALESCE(jsonb_object_agg(e.key,
                 CASE -- a record filed UNDER the erased child's name (Go's addresses)
                      WHEN jsonb_typeof(e.value) = 'object' AND COALESCE(p_name, '') <> ''
                           AND public._name_base(e.key) = p_name
                        THEN public._detach_person_json(e.value, p_id)
                      WHEN jsonb_typeof(e.value) IN ('object', 'array')
                        THEN public._detach_named_json(e.value, p_id, p_name)
                      ELSE e.value END), '{}'::jsonb)
          INTO v_out FROM jsonb_each(p_doc) e
         WHERE NOT (v_own AND e.key IN ('camperId', '_camperId', 'personId', 'person_id', 'camper_id')
                    AND jsonb_typeof(e.value) IN ('number', 'string')
                    AND public._stated_person_id(e.value #>> '{}') = p_id);
        RETURN v_out;
    ELSIF jsonb_typeof(p_doc) = 'array' THEN
        SELECT COALESCE(jsonb_agg(CASE WHEN jsonb_typeof(x.value) IN ('object', 'array')
                                       THEN public._detach_named_json(x.value, p_id, p_name) ELSE x.value END
                                  ORDER BY x.ord), '[]'::jsonb)
          INTO v_out FROM jsonb_array_elements(p_doc) WITH ORDINALITY x(value, ord);
        RETURN v_out;
    END IF;
    RETURN p_doc;
END;
$$;

-- A saved document with the camp's numbers put right, in one pass:
--   * a number that MOVED is carried to where it went (TED-012/017);
--   * a number whose child was ERASED, and that nobody holds now, is taken
--     out: records filed under it go (as the erase removed them), and money
--     keeps its amounts but loses the number (TED-021) — so a copy saved by a
--     tab opened before the erase brings nothing back, and a new child later
--     given the freed number inherits nothing.
-- The roster inside app1 is left to the roster trigger, which knows which
-- child each entry is. Cheap when nothing matches: one text search.
CREATE OR REPLACE FUNCTION public._carry_moved_numbers(p_camp_id uuid, p_key text, p_doc jsonb)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
DECLARE
    v_map  jsonb;
    v_body jsonb;
    v_seen bigint[];
    g      bigint;
    r      record;
BEGIN
    IF p_doc IS NULL OR jsonb_typeof(p_doc) NOT IN ('object', 'array') THEN RETURN p_doc; END IF;
    IF NOT EXISTS (SELECT 1 FROM camp_person_renumbers WHERE camp_id = p_camp_id)
       AND NOT EXISTS (SELECT 1 FROM camp_erased_people WHERE camp_id = p_camp_id) THEN
        RETURN p_doc;
    END IF;
    v_body := CASE WHEN p_key = 'app1' AND jsonb_typeof(p_doc) = 'object' THEN p_doc - 'camperRoster' ELSE p_doc END;
    -- Every number the document's records carry, read once from its text.
    SELECT array_agg(DISTINCT public._stated_person_id(m[2])) INTO v_seen
      FROM regexp_matches(v_body::text, '"(_?camperId|personId|person_id|camper_id)": "?(\d{1,15})"?[,}\]]', 'g') m;
    IF v_seen IS NULL THEN RETURN p_doc; END IF;

    SELECT jsonb_object_agg(from_id::text, to_id) INTO v_map
      FROM camp_person_renumbers WHERE camp_id = p_camp_id AND from_id = ANY (v_seen);
    IF v_map IS NOT NULL THEN
        v_body := public._json_renumber_map(v_body, v_map);
    END IF;
    FOR g IN SELECT e.person_id FROM camp_erased_people e
              WHERE e.camp_id = p_camp_id AND e.person_id = ANY (v_seen)
                AND NOT EXISTS (SELECT 1 FROM camp_people p WHERE p.camp_id = e.camp_id AND p.person_id = e.person_id)
    LOOP
        v_body := public._detach_person_json(public._scrub_person_json(v_body, g, NULL), g);
    END LOOP;
    -- …and once a NEW child holds it: only the erased child's own records,
    -- by number AND name, lose the number.
    FOR r IN SELECT e.person_id, public._name_base(e.key) AS base
               FROM camp_erased_people e
              WHERE e.camp_id = p_camp_id AND e.person_id = ANY (v_seen) AND COALESCE(e.key, '') <> ''
                AND EXISTS (SELECT 1 FROM camp_people p WHERE p.camp_id = e.camp_id AND p.person_id = e.person_id
                                                          AND public._name_base(p.source_key) <> public._name_base(e.key))
    LOOP
        v_body := public._detach_named_json(v_body, r.person_id, r.base);
    END LOOP;

    IF p_key = 'app1' AND jsonb_typeof(p_doc) = 'object' AND p_doc ? 'camperRoster' THEN
        v_body := jsonb_set(v_body, '{camperRoster}', p_doc -> 'camperRoster', true);
    END IF;
    RETURN v_body;
END;
$$;
REVOKE ALL ON FUNCTION public._carry_moved_numbers(uuid, text, jsonb) FROM public, anon, authenticated;

-- An invitation's numbers carried through every move.
CREATE OR REPLACE FUNCTION public._carry_moved_ids(p_camp_id uuid, p_ids jsonb)
RETURNS jsonb
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
    SELECT CASE WHEN jsonb_typeof(p_ids) IS DISTINCT FROM 'array' THEN p_ids
                WHEN NOT EXISTS (SELECT 1 FROM camp_person_renumbers WHERE camp_id = p_camp_id) THEN p_ids
                ELSE (SELECT COALESCE(jsonb_agg(
                          CASE WHEN public._stated_person_id(x.value #>> '{}') IS NULL THEN x.value
                               ELSE to_jsonb(public._current_person_number(p_camp_id, public._stated_person_id(x.value #>> '{}')))
                          END ORDER BY x.ord), '[]'::jsonb)
                        FROM jsonb_array_elements(p_ids) WITH ORDINALITY x(value, ord))
           END
$$;
REVOKE ALL ON FUNCTION public._carry_moved_ids(uuid, jsonb) FROM public, anon, authenticated;

-- Write a move down. Its keys go with the child (259), a chain is kept flat,
-- and a number moved back to is somebody's again.
CREATE OR REPLACE FUNCTION public._record_renumber(p_camp_id uuid, p_from bigint, p_to bigint)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
BEGIN
    IF p_from IS NULL OR p_to IS NULL OR p_from = p_to THEN RETURN; END IF;
    INSERT INTO camp_person_renumbers (camp_id, from_id, to_id)
    VALUES (p_camp_id, p_from, p_to)
    ON CONFLICT (camp_id, from_id) DO UPDATE
       SET to_id = EXCLUDED.to_id, moved_at = now(), applied_at = NULL
     WHERE camp_person_renumbers.to_id IS DISTINCT FROM EXCLUDED.to_id;
    UPDATE camp_person_renumbers SET to_id = p_to, applied_at = NULL
     WHERE camp_id = p_camp_id AND to_id = p_from;
    DELETE FROM camp_person_renumbers WHERE camp_id = p_camp_id AND from_id = p_to;
    UPDATE camp_person_keys SET person_id = p_to
     WHERE camp_id = p_camp_id AND kind = 'camper' AND person_id = p_from;
END;
$$;
REVOKE ALL ON FUNCTION public._record_renumber(uuid, bigint, bigint) FROM public, anon, authenticated;

-- Carry every move not yet carried into the saved documents and the
-- invitations. Runs AFTER the statement that made the move (never inside
-- it), and from split_renames.
CREATE OR REPLACE FUNCTION public._apply_pending_renumbers()
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
DECLARE
    c     uuid;
    d     record;
    v_new jsonb;
    n     int := 0;
BEGIN
    FOR c IN SELECT DISTINCT camp_id FROM camp_person_renumbers WHERE applied_at IS NULL LOOP
        UPDATE camp_person_renumbers SET applied_at = now() WHERE camp_id = c AND applied_at IS NULL;
        FOR d IN SELECT key, value FROM camp_state_kv WHERE camp_id = c FOR UPDATE LOOP
            v_new := public._carry_moved_numbers(c, d.key, d.value);
            IF v_new IS DISTINCT FROM d.value THEN
                UPDATE camp_state_kv SET value = v_new, updated_at = now() WHERE camp_id = c AND key = d.key;
                n := n + 1;
            END IF;
        END LOOP;
        UPDATE link_parent_invites i
           SET person_ids = public._carry_moved_ids(c, i.person_ids)
         WHERE i.camp_id = c AND jsonb_typeof(i.person_ids) = 'array'
           AND i.person_ids IS DISTINCT FROM public._carry_moved_ids(c, i.person_ids);
    END LOOP;
    RETURN n;
END;
$$;
REVOKE ALL ON FUNCTION public._apply_pending_renumbers() FROM public, anon, authenticated;

-- Every document, as it is saved: a moved number in it is carried.
CREATE OR REPLACE FUNCTION public.carry_moved_numbers()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
BEGIN
    NEW.value := public._carry_moved_numbers(NEW.camp_id, NEW.key, NEW.value);
    RETURN NEW;
END;
$$;
REVOKE ALL ON FUNCTION public.carry_moved_numbers() FROM public, anon, authenticated;
DROP TRIGGER IF EXISTS trg_yy_carry_moved_numbers ON public.camp_state_kv;
CREATE TRIGGER trg_yy_carry_moved_numbers
BEFORE INSERT OR UPDATE ON public.camp_state_kv
FOR EACH ROW EXECUTE FUNCTION public.carry_moved_numbers();

CREATE OR REPLACE FUNCTION public.apply_moved_numbers()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
BEGIN
    IF EXISTS (SELECT 1 FROM camp_person_renumbers WHERE applied_at IS NULL) THEN
        PERFORM public._apply_pending_renumbers();
    END IF;
    RETURN NULL;
END;
$$;
REVOKE ALL ON FUNCTION public.apply_moved_numbers() FROM public, anon, authenticated;
DROP TRIGGER IF EXISTS trg_zz_apply_moved_numbers ON public.camp_state_kv;
CREATE TRIGGER trg_zz_apply_moved_numbers
AFTER INSERT OR UPDATE ON public.camp_state_kv
FOR EACH STATEMENT EXECUTE FUNCTION public.apply_moved_numbers();

-- A moved number is never minted for anybody else.
CREATE OR REPLACE FUNCTION public.mint_person_id(p_camp_id uuid)
RETURNS bigint
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
DECLARE
    v_id    bigint;
    v_guard integer := 0;
BEGIN
    INSERT INTO camp_person_seq (camp_id, next_id)
    VALUES (p_camp_id,
            COALESCE((SELECT max(person_id) + 1 FROM camp_people WHERE camp_id = p_camp_id), 1))
    ON CONFLICT (camp_id) DO UPDATE
       SET next_id = GREATEST(camp_person_seq.next_id, EXCLUDED.next_id);

    LOOP
        v_guard := v_guard + 1;
        IF v_guard > 100000 THEN
            RAISE EXCEPTION 'mint_person_id: no free id for camp % after % tries', p_camp_id, v_guard;
        END IF;

        UPDATE camp_person_seq
           SET next_id = next_id + 1
         WHERE camp_id = p_camp_id
        RETURNING next_id - 1 INTO v_id;

        EXIT WHEN NOT EXISTS (SELECT 1 FROM camp_people WHERE camp_id = p_camp_id AND person_id = v_id)
              AND NOT EXISTS (SELECT 1 FROM camp_person_renumbers WHERE camp_id = p_camp_id AND from_id = v_id)
              -- an erased child's number is free, but only when a person
              -- gives it out on purpose — never by itself (TED-021)
              AND NOT EXISTS (SELECT 1 FROM camp_erased_people WHERE camp_id = p_camp_id AND person_id = v_id);
    END LOOP;

    RETURN v_id;
END;
$$;
REVOKE ALL ON FUNCTION public.mint_person_id(uuid) FROM public, anon, authenticated;

-- When a roster entry says a child was added (addedAt: epoch ms or a date).
CREATE OR REPLACE FUNCTION public._entry_added_at(p jsonb)
RETURNS timestamptz
LANGUAGE plpgsql
IMMUTABLE
SET search_path = public, pg_catalog
AS $$
DECLARE v text := p ->> 'addedAt';
BEGIN
    IF COALESCE(v, '') = '' THEN RETURN NULL; END IF;
    IF v ~ '^\d{10,15}$' THEN RETURN to_timestamp(v::numeric / 1000); END IF;
    RETURN v::timestamptz;
EXCEPTION WHEN OTHERS THEN
    RETURN NULL;
END;
$$;


-- ─── 1. the roster trigger (259), with moves, erases and rename+renumber ────
CREATE OR REPLACE FUNCTION public.number_camp_campers()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
DECLARE
    v_old    jsonb := '{}'::jsonb;
    v_new    jsonb := '{}'::jsonb;
    v_all    boolean := COALESCE(current_setting('campistry.renumber_all', true), '') = 'on';
    v_ids    jsonb;
    e        record;
    v_holder bigint;
    v_back   record;
    v_key    text;
    v_entry  jsonb;
    v_id     bigint;
    v_prev   jsonb;
    v_to     bigint;
    v_when   timestamptz;
    v_from   bigint;
    v_was    bigint;
    v_hinted jsonb := '{}'::jsonb;
    v_stale  timestamptz;
    v_seen   bigint[];
BEGIN
    IF TG_OP = 'UPDATE' AND NOT v_all AND jsonb_typeof(OLD.value -> 'camperRoster') = 'object' THEN
        v_old := OLD.value -> 'camperRoster';
    END IF;
    IF jsonb_typeof(NEW.value -> 'camperRoster') = 'object' THEN
        v_new := NEW.value -> 'camperRoster';
    END IF;

    -- What is saved now. An upsert (INSERT … ON CONFLICT DO UPDATE, which is
    -- how the pages save) runs this trigger as an INSERT first, with no OLD.
    IF TG_OP = 'UPDATE' THEN
        v_prev := OLD.value -> 'camperRoster';
    ELSE
        SELECT value -> 'camperRoster' INTO v_prev FROM camp_state_kv
         WHERE camp_id = NEW.camp_id AND key = NEW.key;
    END IF;
    IF jsonb_typeof(v_prev) IS DISTINCT FROM 'object' THEN v_prev := '{}'::jsonb; END IF;
    -- …and the numbering compares against it too (259).
    IF TG_OP = 'INSERT' AND NOT v_all THEN
        v_old := v_prev;
    END IF;

    -- 0a. (260) Numbers that are no longer anybody's, stated by an entry.
    FOR e IN SELECT n.key, n.value FROM jsonb_each(v_new) n(key, value)
              WHERE jsonb_typeof(n.value) = 'object'
                AND public._stated_person_id(n.value ->> 'camperId') IS NOT NULL
    LOOP
        v_id := public._stated_person_id(e.value ->> 'camperId');
        -- An erased child: their number, under their name. A saved copy of
        -- them (a tab opened before the erase) does not bring them back —
        -- whether the number is still free or a NEW child holds it now (the
        -- stale copy never takes it over: TED-021). A child added again on
        -- purpose, after the erase (addedAt), does come back. A different
        -- child given the freed number is simply given it.
        SELECT erased_at INTO v_when FROM camp_erased_people x
         WHERE x.camp_id = NEW.camp_id AND x.person_id = v_id
           AND public._name_base(x.key) = public._name_base(COALESCE(NULLIF(e.value ->> 'displayName', ''), e.key))
           AND NOT EXISTS (SELECT 1 FROM camp_people p WHERE p.camp_id = NEW.camp_id AND p.person_id = v_id
                                                        AND public._name_base(p.source_key) = public._name_base(x.key));
        IF FOUND THEN
            IF public._entry_added_at(e.value) > v_when THEN
                DELETE FROM camp_erased_people WHERE camp_id = NEW.camp_id AND person_id = v_id;
            ELSE
                v_new := v_new - e.key;
                -- This save comes from a tab opened before that erase: a child
                -- added since is not missing from it on purpose.
                v_stale := LEAST(COALESCE(v_stale, v_when), v_when);
                CONTINUE;
            END IF;
        END IF;
        CONTINUE WHEN EXISTS (SELECT 1 FROM camp_people p WHERE p.camp_id = NEW.camp_id AND p.person_id = v_id);
        -- A number that moved: this entry is either that child (it gets their
        -- number today) or somebody else (who gets a number of their own).
        v_to := public._current_person_number(NEW.camp_id, v_id);
        -- The office putting the child BACK on a number they were moved off
        -- (the page says which number they have now): honoured — the move is
        -- simply undone below (TED-025).
        IF v_to IS DISTINCT FROM v_id
           AND public._stated_person_id(e.value ->> 'renumberedFrom') = v_to
           AND EXISTS (SELECT 1 FROM camp_people p WHERE p.camp_id = NEW.camp_id AND p.person_id = v_to
                                                  AND p.kind = 'camper' AND p.deleted_at IS NULL
                                                  AND (p.source_key = e.key OR NOT (v_new ? p.source_key))) THEN
            CONTINUE;
        END IF;
        IF v_to IS DISTINCT FROM v_id THEN
            IF EXISTS (SELECT 1 FROM camp_people p WHERE p.camp_id = NEW.camp_id AND p.person_id = v_to
                                                     AND p.kind = 'camper' AND p.source_key = e.key)
               OR public._roster_key_holder(NEW.camp_id, e.key) = v_to THEN
                v_new := jsonb_set(v_new, ARRAY[e.key, 'camperId'], to_jsonb(v_to), true);
            ELSE
                v_new := jsonb_set(v_new, ARRAY[e.key], e.value - 'camperId', true);
            END IF;
        END IF;
    END LOOP;

    -- A save from a tab opened before an erase never removes a child added
    -- after it (it could not have known them): they are kept as they were.
    IF v_stale IS NOT NULL THEN
        FOR e IN SELECT p.source_key AS key, p.payload AS value FROM camp_people p
                  WHERE p.camp_id = NEW.camp_id AND p.kind = 'camper' AND p.deleted_at IS NULL
                    AND p.first_seen >= v_stale AND jsonb_typeof(p.payload) = 'object'
                    AND NOT (v_new ? p.source_key)
        LOOP
            v_new := v_new || jsonb_build_object(e.key, COALESCE(v_prev -> e.key, e.value));
        END LOOP;
    END IF;

    -- A Me tab says which children it has ever had on screen (_rosterSeen,
    -- their numbers). A child it never saw is not missing from its save on
    -- purpose — the tab was opened (or asleep, or offline) before they were
    -- added — so they are kept as they were (TED-033). Never stored.
    IF jsonb_typeof(NEW.value -> '_rosterSeen') = 'array' THEN
        v_seen := ARRAY(SELECT public._current_person_number(NEW.camp_id, public._stated_person_id(x #>> '{}'))
                          FROM jsonb_array_elements(NEW.value -> '_rosterSeen') x);
        FOR e IN SELECT p.source_key AS key, p.payload AS value, p.person_id FROM camp_people p
                  WHERE p.camp_id = NEW.camp_id AND p.kind = 'camper' AND p.deleted_at IS NULL
                    AND jsonb_typeof(p.payload) = 'object'
                    AND NOT (v_new ? p.source_key)
                    AND NOT (p.person_id = ANY (v_seen))
                    AND NOT EXISTS (SELECT 1 FROM jsonb_each(v_new) n
                                     WHERE public._stated_person_id(n.value ->> 'camperId') = p.person_id)
        LOOP
            v_new := v_new || jsonb_build_object(e.key, COALESCE(v_prev -> e.key, e.value));
        END LOOP;
    END IF;

    -- 0b. (260) Renamed AND renumbered in one edit: the page says which number
    --     the child had. The child takes the new key first, so the numbering
    --     below sees one child renumbered, not a new one. Never stored.
    FOR e IN SELECT n.key, n.value FROM jsonb_each(v_new) n(key, value)
              WHERE jsonb_typeof(n.value) = 'object' AND n.value ? 'renumberedFrom'
    LOOP
        v_new := jsonb_set(v_new, ARRAY[e.key], e.value - 'renumberedFrom', true);
        v_from := public._stated_person_id(e.value ->> 'renumberedFrom');
        CONTINUE WHEN v_from IS NULL;
        -- Only the child who holds that number now, renamed in this very save
        -- (their old key was saved, and is gone from the roster now), is this
        -- entry. A leftover hint on anybody else is ignored (TED-027).
        SELECT p.source_key INTO v_key FROM camp_people p
         WHERE p.camp_id = NEW.camp_id AND p.person_id = v_from AND p.kind = 'camper' AND p.deleted_at IS NULL;
        CONTINUE WHEN NOT FOUND OR v_key = e.key OR (v_new ? v_key) OR NOT (v_prev ? v_key)
                   OR EXISTS (SELECT 1 FROM camp_people p WHERE p.camp_id = NEW.camp_id AND p.kind = 'camper'
                                 AND p.deleted_at IS NULL AND p.source_key = e.key);
        UPDATE camp_people SET source_key = e.key, updated_at = now()
         WHERE camp_id = NEW.camp_id AND person_id = v_from;
        v_hinted := v_hinted || jsonb_build_object(e.key, v_from);
    END LOOP;

    -- 1. A page that has not yet adopted a key this trigger gave (259).
    FOR e IN SELECT n.key, n.value FROM jsonb_each(v_new) n(key, value)
              WHERE jsonb_typeof(n.value) = 'object'
                AND public._stated_person_id(n.value ->> 'camperId') IS NULL
    LOOP
        v_holder := public._roster_key_holder(NEW.camp_id, e.key);
        CONTINUE WHEN v_holder IS NULL
                   OR EXISTS (SELECT 1 FROM camp_people p WHERE p.camp_id = NEW.camp_id
                               AND p.person_id = v_holder AND p.kind = 'camper'
                               AND p.deleted_at IS NULL AND p.source_key = e.key);
        SELECT p.person_id, p.source_key INTO v_back
          FROM camp_people p
         WHERE p.camp_id = NEW.camp_id AND p.kind = 'camper' AND p.deleted_at IS NULL
           AND p.person_id <> v_holder
           AND regexp_replace(p.source_key, '\s#\d+(?:-\d+)?$', '') = e.key
           AND ((v_prev ? p.source_key) OR p.updated_at = now())
           AND NOT (v_new ? p.source_key)
         ORDER BY p.updated_at DESC NULLS LAST
         LIMIT 1;
        IF FOUND THEN
            v_new := (v_new - e.key) || jsonb_build_object(v_back.source_key,
                       e.value || jsonb_build_object('camperId', v_back.person_id,
                                                     'displayName', COALESCE(NULLIF(e.value ->> 'displayName', ''), e.key)));
        END IF;
    END LOOP;

    v_ids := public._number_people(NEW.camp_id, 'camper', v_old, v_new, 'camperId', 'name', v_all);

    -- 2. Every entry looked at now carries exactly the number it holds, under
    --    a key that is its own (259) — and a number it moved off is written
    --    down, so everything else follows it (260).
    FOR e IN SELECT key, value FROM jsonb_each(v_ids) LOOP
        v_id := (e.value #>> '{}')::bigint;
        v_key := e.key;
        v_holder := public._roster_key_holder(NEW.camp_id, e.key);
        IF v_holder IS NOT NULL AND v_holder <> v_id THEN
            v_key := public._own_roster_key(NEW.camp_id, e.key, v_id, v_new);
            v_entry := (v_new -> e.key)
                       || jsonb_build_object('displayName',
                              COALESCE(NULLIF(v_new #>> ARRAY[e.key, 'displayName'], ''),
                                       NULLIF(v_new #>> ARRAY[e.key, 'name'], ''),
                                       regexp_replace(e.key, '\s#\d+(?:-\d+)?$', '')));
            v_new := (v_new - e.key) || jsonb_build_object(v_key, v_entry);
            UPDATE camp_people SET source_key = v_key, updated_at = now()
             WHERE camp_id = NEW.camp_id AND person_id = v_id AND kind = 'camper';
        END IF;
        IF (v_new #> ARRAY[v_key, 'camperId']) IS DISTINCT FROM to_jsonb(v_id) THEN
            v_new := jsonb_set(v_new, ARRAY[v_key, 'camperId'], to_jsonb(v_id), true);
        END IF;
        v_was := COALESCE(public._stated_person_id(v_hinted ->> e.key),
                          public._stated_person_id(v_prev #>> ARRAY[e.key, 'camperId']));
        IF v_was IS NOT NULL AND v_was <> v_id
           AND NOT EXISTS (SELECT 1 FROM camp_people p WHERE p.camp_id = NEW.camp_id AND p.person_id = v_was) THEN
            PERFORM public._record_renumber(NEW.camp_id, v_was, v_id);
        END IF;
        INSERT INTO camp_person_keys (camp_id, kind, key, person_id)
        VALUES (NEW.camp_id, 'camper', v_key, v_id)
        ON CONFLICT (camp_id, kind, key) DO UPDATE
           SET person_id = EXCLUDED.person_id, first_at = now()
         WHERE NOT EXISTS (SELECT 1 FROM camp_people p
                            WHERE p.camp_id = camp_person_keys.camp_id
                              AND p.person_id = camp_person_keys.person_id AND p.kind = 'camper');
    END LOOP;

    IF v_new IS DISTINCT FROM COALESCE(NEW.value -> 'camperRoster', '{}'::jsonb) THEN
        NEW.value := jsonb_set(NEW.value, '{camperRoster}', v_new, true);
    END IF;
    NEW.value := NEW.value - '_rosterSeen';
    -- The rest of this document follows any move now; the other documents
    -- and the invitations follow when this statement is done (apply_moved_numbers).
    NEW.value := public._carry_moved_numbers(NEW.camp_id, NEW.key, NEW.value);
    RETURN NEW;
END;
$$;
REVOKE ALL ON FUNCTION public.number_camp_campers() FROM public, anon, authenticated;

-- Numbers that moved, for the Me page: a moved number is taken.
CREATE OR REPLACE FUNCTION public.get_camper_numbers(p_camp_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
BEGIN
    -- The camp's staff only (TED-034). camp_reader also lets in parents, who
    -- must not get every child's name and number.
    IF NOT public.camp_staff_member(p_camp_id) THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_authorized');
    END IF;
    RETURN jsonb_build_object(
        'success', true,
        'campers', COALESCE((SELECT jsonb_object_agg(source_key, person_id)
                               FROM camp_people
                              WHERE camp_id = p_camp_id AND kind = 'camper'
                                AND deleted_at IS NULL), '{}'::jsonb),
        -- The page hands this out to a new child by itself: never below an
        -- erased child's number (TED-021).
        'next', GREATEST(
                  COALESCE((SELECT max(person_id) + 1 FROM camp_people WHERE camp_id = p_camp_id), 1),
                  COALESCE((SELECT next_id FROM camp_person_seq WHERE camp_id = p_camp_id), 1),
                  COALESCE((SELECT max(person_id) + 1 FROM camp_erased_people WHERE camp_id = p_camp_id), 1),
                  COALESCE((SELECT max(from_id) + 1 FROM camp_person_renumbers WHERE camp_id = p_camp_id), 1)),
        -- Numbers of erased children (no names: nothing about them is kept):
        -- free, but the page warns before one is typed for a new child.
        'erased', COALESCE((SELECT jsonb_object_agg(person_id::text, true)
                              FROM camp_erased_people WHERE camp_id = p_camp_id), '{}'::jsonb),
        'departed', COALESCE((SELECT jsonb_object_agg(person_id::text, source_key)
                                FROM camp_people
                               WHERE camp_id = p_camp_id AND deleted_at IS NOT NULL), '{}'::jsonb),
        'held_keys', COALESCE((SELECT jsonb_object_agg(k.key, k.person_id)
                                 FROM camp_person_keys k
                                WHERE k.camp_id = p_camp_id AND k.kind = 'camper'
                                  AND EXISTS (SELECT 1 FROM camp_people p
                                               WHERE p.camp_id = k.camp_id AND p.person_id = k.person_id
                                                 AND p.kind = 'camper')
                                  AND NOT EXISTS (SELECT 1 FROM camp_people p
                                                   WHERE p.camp_id = k.camp_id AND p.person_id = k.person_id
                                                     AND p.kind = 'camper' AND p.deleted_at IS NULL
                                                     AND p.source_key = k.key)), '{}'::jsonb),
        -- {old number: the number that child has now}
        'moved', COALESCE((SELECT jsonb_object_agg(from_id::text, to_id)
                             FROM camp_person_renumbers WHERE camp_id = p_camp_id), '{}'::jsonb));
END;
$$;
REVOKE ALL ON FUNCTION public.get_camper_numbers(uuid) FROM public, anon;
GRANT EXECUTE ON FUNCTION public.get_camper_numbers(uuid) TO authenticated, service_role;


-- ─── 2. erasing a child is remembered ───────────────────────────────────────
DO $$
BEGIN
    IF to_regprocedure('public._erase_camper_259(uuid,bigint,boolean)') IS NULL THEN
        ALTER FUNCTION public.erase_camper(uuid, bigint, boolean) RENAME TO _erase_camper_259;
    END IF;
    REVOKE ALL ON FUNCTION public._erase_camper_259(uuid, bigint, boolean) FROM public, anon, authenticated;
END $$;

CREATE OR REPLACE FUNCTION public.erase_camper(
    p_camp_id   uuid,
    p_person_id bigint,
    p_confirm   boolean DEFAULT false
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
DECLARE
    v_key text;
    v     jsonb;
BEGIN
    SELECT source_key INTO v_key FROM camp_people
     WHERE camp_id = p_camp_id AND person_id = p_person_id AND kind = 'camper';
    v := public._erase_camper_259(p_camp_id, p_person_id, p_confirm);
    IF p_confirm AND (v ->> 'success')::boolean IS TRUE
       AND NOT EXISTS (SELECT 1 FROM camp_people WHERE camp_id = p_camp_id AND person_id = p_person_id) THEN
        INSERT INTO camp_erased_people (camp_id, person_id, key, erased_at)
        VALUES (p_camp_id, p_person_id, v_key, now())
        ON CONFLICT (camp_id, person_id) DO UPDATE SET key = EXCLUDED.key, erased_at = now();
        -- the numbers this child moved off are free with theirs
        DELETE FROM camp_person_renumbers WHERE camp_id = p_camp_id AND to_id = p_person_id;
        -- The erase keeps money (254) — but not on this number, which is free
        -- now and may be given to a new child: the amounts stay, the number goes.
        UPDATE camp_state_kv s
           SET value = public._carry_moved_numbers(s.camp_id, s.key, s.value), updated_at = now()
         WHERE s.camp_id = p_camp_id
           AND s.value IS DISTINCT FROM public._carry_moved_numbers(s.camp_id, s.key, s.value);
        -- …and every page opened before this reloads before it saves (2b).
        v := v || jsonb_build_object('cache_epoch', public._bump_cache_epoch(p_camp_id));
    END IF;
    RETURN v;
END;
$$;
REVOKE ALL ON FUNCTION public.erase_camper(uuid, bigint, boolean) FROM public, anon;
GRANT EXECUTE ON FUNCTION public.erase_camper(uuid, bigint, boolean) TO authenticated, service_role;


-- ─── 2b. after an erase or a merge, every open page reloads ────────────────
-- A page that was open before a child was erased (or merged away) still
-- holds that child in its memory and its local cache, and would write them
-- back on its next save. So an erase or merge moves the camp's cache version
-- on; every office page asks for it before it saves (and when it wakes up),
-- and a page opened before the change clears its cache and reloads instead
-- of saving (supabase_client.js). The owner's rule: "when a child is erased
-- we force a reload that clears the cache."
CREATE TABLE IF NOT EXISTS public.camp_cache_epoch (
    camp_id    uuid PRIMARY KEY,
    epoch      bigint NOT NULL DEFAULT 0,
    changed_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.camp_cache_epoch ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.camp_cache_epoch FROM anon, authenticated;

CREATE OR REPLACE FUNCTION public._bump_cache_epoch(p_camp_id uuid)
RETURNS bigint
LANGUAGE sql
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
    INSERT INTO camp_cache_epoch (camp_id, epoch, changed_at) VALUES (p_camp_id, 1, now())
    ON CONFLICT (camp_id) DO UPDATE SET epoch = camp_cache_epoch.epoch + 1, changed_at = now()
    RETURNING epoch
$$;
REVOKE ALL ON FUNCTION public._bump_cache_epoch(uuid) FROM public, anon, authenticated;

-- The camp's cache version, for its staff's pages (NULL for anyone else).
CREATE OR REPLACE FUNCTION public.get_camp_cache_epoch(p_camp_id uuid)
RETURNS bigint
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
    SELECT CASE WHEN public.camp_staff_member(p_camp_id)
                THEN COALESCE((SELECT epoch FROM camp_cache_epoch WHERE camp_id = p_camp_id), 0) END
$$;
REVOKE ALL ON FUNCTION public.get_camp_cache_epoch(uuid) FROM public, anon;
GRANT EXECUTE ON FUNCTION public.get_camp_cache_epoch(uuid) TO authenticated, service_role;

-- A merge takes a camper away for good too (254): the same reload.
DO $$
BEGIN
    IF to_regprocedure('public._merge_campers_254(uuid,bigint,bigint)') IS NULL THEN
        ALTER FUNCTION public.merge_campers(uuid, bigint, bigint) RENAME TO _merge_campers_254;
    END IF;
    REVOKE ALL ON FUNCTION public._merge_campers_254(uuid, bigint, bigint) FROM public, anon, authenticated;
END $$;
CREATE OR REPLACE FUNCTION public.merge_campers(p_camp_id uuid, p_keep bigint, p_gone bigint)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
DECLARE v jsonb;
BEGIN
    v := public._merge_campers_254(p_camp_id, p_keep, p_gone);
    IF (v ->> 'success')::boolean IS TRUE THEN
        v := v || jsonb_build_object('cache_epoch', public._bump_cache_epoch(p_camp_id));
    END IF;
    RETURN v;
END;
$$;
REVOKE ALL ON FUNCTION public.merge_campers(uuid, bigint, bigint) FROM public, anon;
GRANT EXECUTE ON FUNCTION public.merge_campers(uuid, bigint, bigint) TO authenticated, service_role;


-- ─── 3. invitations: each slot decided on every save ────────────────────────
-- The number for one invitation slot. p_data is the invitation's camper_data
-- (the office's entries, keyed by roster key), p_old_names/p_old_ids the
-- invitation as it was, p_bound the latest arrival a slot may be given by
-- key (232: a camper enrolled after the invitation was decided is not who it
-- meant; restamp_parent_invite passes now()).
DROP FUNCTION IF EXISTS public._invite_slot_person(uuid, text, jsonb, jsonb, jsonb);
CREATE OR REPLACE FUNCTION public._invite_slot_person(
    p_camp_id uuid, p_name text, p_data jsonb, p_old_names jsonb, p_old_ids jsonb,
    p_bound timestamptz DEFAULT now())
RETURNS bigint
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
DECLARE
    v_id  bigint;
    v_pos int;
BEGIN
    IF COALESCE(btrim(p_name), '') = '' THEN RETURN NULL; END IF;

    -- The number the office sent for this child — if it is a camper here.
    v_id := public._current_person_number(p_camp_id,
                public._stated_person_id(p_data #>> ARRAY[p_name, 'camperId']));
    IF v_id IS NOT NULL AND EXISTS (SELECT 1 FROM camp_people
                                     WHERE camp_id = p_camp_id AND kind = 'camper' AND person_id = v_id) THEN
        RETURN v_id;
    END IF;

    -- The number this name had in the invitation before, wherever it moved.
    IF jsonb_typeof(p_old_names) = 'array' AND jsonb_typeof(p_old_ids) = 'array' THEN
        SELECT e.ord - 1 INTO v_pos
          FROM jsonb_array_elements(p_old_names) WITH ORDINALITY e(value, ord)
         WHERE e.value #>> '{}' = p_name
         LIMIT 1;
        IF v_pos IS NOT NULL THEN
            v_id := public._current_person_number(p_camp_id, public._stated_person_id(p_old_ids ->> v_pos));
            IF v_id IS NOT NULL AND EXISTS (SELECT 1 FROM camp_people
                                             WHERE camp_id = p_camp_id AND kind = 'camper' AND person_id = v_id) THEN
                RETURN v_id;
            END IF;
        END IF;
    END IF;

    -- The enrolled camper who holds that key, and was there by p_bound.
    -- Never a departed child.
    SELECT person_id INTO v_id
      FROM camp_people
     WHERE camp_id = p_camp_id AND kind = 'camper' AND deleted_at IS NULL AND source_key = p_name
       AND first_seen <= COALESCE(p_bound, now())
     LIMIT 1;
    RETURN v_id;
END;
$$;
REVOKE ALL ON FUNCTION public._invite_slot_person(uuid, text, jsonb, jsonb, jsonb, timestamptz) FROM public, anon, authenticated;

CREATE OR REPLACE FUNCTION public.stamp_invite_person_ids()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
DECLARE
    v_old_names jsonb := NULL;
    v_old_ids   jsonb := NULL;
    v_bound     timestamptz := now();
BEGIN
    IF TG_OP = 'INSERT' OR NEW.camper_names IS DISTINCT FROM OLD.camper_names
       OR NEW.camper_data IS DISTINCT FROM OLD.camper_data THEN
        NEW.person_ids_resolved_at := now();
    END IF;
    IF NEW.camp_id IS NULL OR jsonb_typeof(NEW.camper_names) IS DISTINCT FROM 'array' THEN
        RETURN NEW;
    END IF;
    -- A caller that set the numbers itself is taken at its word — carried
    -- through any move.
    IF (TG_OP = 'INSERT' AND NEW.person_ids IS NOT NULL)
       OR (TG_OP = 'UPDATE' AND NEW.person_ids IS DISTINCT FROM OLD.person_ids) THEN
        NEW.person_ids := public._carry_moved_ids(NEW.camp_id, NEW.person_ids);
        RETURN NEW;
    END IF;
    IF TG_OP = 'UPDATE' THEN
        v_old_names := OLD.camper_names;
        v_old_ids   := OLD.person_ids;
        v_bound     := COALESCE(OLD.person_ids_resolved_at, now());
    END IF;
    NEW.person_ids := (
        SELECT jsonb_agg(to_jsonb(public._invite_slot_person(
                   NEW.camp_id, e.value #>> '{}', NEW.camper_data, v_old_names, v_old_ids, v_bound))
               ORDER BY e.ord)
          FROM jsonb_array_elements(NEW.camper_names) WITH ORDINALITY AS e(value, ord));
    RETURN NEW;
END;
$$;
REVOKE ALL ON FUNCTION public.stamp_invite_person_ids() FROM public, anon, authenticated;

DROP TRIGGER IF EXISTS trg_stamp_invite_person_ids ON public.link_parent_invites;
CREATE TRIGGER trg_stamp_invite_person_ids
BEFORE INSERT OR UPDATE OF camper_names, camper_data, person_ids ON public.link_parent_invites
FOR EACH ROW EXECUTE FUNCTION public.stamp_invite_person_ids();

-- The office's deliberate repair of one invitation: every slot decided the
-- same way, with any enrolled key holder allowed (a person asked for it).
-- Never a departed child found by name (TED-019).
CREATE OR REPLACE FUNCTION public.restamp_parent_invite(p_invite uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
DECLARE
    caller   uuid := auth.uid();
    v_camp   uuid;
    v_names  jsonb;
    v_data   jsonb;
    v_before jsonb;
    v_after  jsonb;
BEGIN
    IF caller IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_authenticated');
    END IF;
    SELECT i.camp_id, i.camper_names, i.camper_data, i.person_ids
      INTO v_camp, v_names, v_data, v_before
      FROM link_parent_invites i WHERE i.id = p_invite
       FOR UPDATE;
    IF v_camp IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'invite_not_found');
    END IF;
    IF NOT public._is_camp_admin(v_camp, caller) THEN
        RETURN jsonb_build_object('success', false, 'error', 'forbidden');
    END IF;
    IF jsonb_typeof(v_names) IS DISTINCT FROM 'array' OR jsonb_array_length(v_names) = 0 THEN
        UPDATE link_parent_invites SET person_ids_resolved_at = now() WHERE id = p_invite;
        RETURN jsonb_build_object('success', true, 'camp_wide', true, 'person_ids', v_before);
    END IF;

    SELECT jsonb_agg(to_jsonb(public._invite_slot_person(v_camp, e.value #>> '{}', v_data,
                                                         v_names, v_before, 'infinity')) ORDER BY e.ord)
      INTO v_after
      FROM jsonb_array_elements(v_names) WITH ORDINALITY AS e(value, ord);

    UPDATE link_parent_invites
       SET person_ids = COALESCE(v_after, person_ids),
           person_ids_resolved_at = now()
     WHERE id = p_invite;

    RETURN jsonb_build_object(
        'success', true,
        'camp_id', v_camp,
        'was', COALESCE(v_before, 'null'::jsonb),
        'now', COALESCE(v_after, 'null'::jsonb),
        'still_unresolved',
            (SELECT count(*) FROM jsonb_array_elements(COALESCE(v_after, '[]'::jsonb)) AS s(v)
              WHERE s.v = 'null'::jsonb));
END;
$$;
REVOKE ALL ON FUNCTION public.restamp_parent_invite(uuid) FROM public, anon;
GRANT EXECUTE ON FUNCTION public.restamp_parent_invite(uuid) TO authenticated;

-- The invitations whose numbers disagree with their names, or still carry a
-- number that moved.
CREATE OR REPLACE FUNCTION public.verify_invite_numbers()
RETURNS jsonb
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
    SELECT jsonb_build_object(
        'slots_on_the_wrong_child', COALESCE((
            SELECT jsonb_agg(jsonb_build_object('invite', i.id, 'name', e.value #>> '{}',
                                                'has', i.person_ids -> (e.ord - 1)::int,
                                                'should_have', p.person_id))
              FROM link_parent_invites i
              CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(i.camper_names) = 'array'
                                                           THEN i.camper_names ELSE '[]'::jsonb END)
                         WITH ORDINALITY e(value, ord)
              JOIN camp_people p ON p.camp_id = i.camp_id AND p.kind = 'camper'
                                AND p.deleted_at IS NULL AND p.source_key = e.value #>> '{}'
             WHERE public._stated_person_id(i.person_ids ->> (e.ord - 1)::int) IS DISTINCT FROM p.person_id),
            '[]'::jsonb),
        'slots_on_a_moved_number', (
            SELECT count(*) FROM link_parent_invites i
              CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(i.person_ids) = 'array'
                                                           THEN i.person_ids ELSE '[]'::jsonb END) x(value)
              JOIN camp_person_renumbers r ON r.camp_id = i.camp_id
                                          AND r.from_id = public._stated_person_id(x.value #>> '{}')),
        'lists_of_different_lengths', (
            SELECT count(*) FROM link_parent_invites
             WHERE jsonb_typeof(person_ids) = 'array' AND jsonb_typeof(camper_names) = 'array'
               AND jsonb_array_length(person_ids) <> jsonb_array_length(camper_names)));
$$;
REVOKE ALL ON FUNCTION public.verify_invite_numbers() FROM public, anon;
GRANT EXECUTE ON FUNCTION public.verify_invite_numbers() TO authenticated, service_role;

-- Realign every invitation written before this file: each slot decided from
-- the office's data, then the enrolled key holder; a slot nothing can decide
-- keeps what it had (an erased or departed child's slot, which grants nothing
-- to anyone else).
UPDATE public.link_parent_invites i
   SET person_ids = (
        SELECT jsonb_agg(COALESCE(
                   to_jsonb(public._invite_slot_person(i.camp_id, e.value #>> '{}', i.camper_data, NULL, NULL,
                                                       i.person_ids_resolved_at)),
                   NULLIF(i.person_ids -> (e.ord - 1)::int, 'null'::jsonb),
                   'null'::jsonb)
               ORDER BY e.ord)
          FROM jsonb_array_elements(i.camper_names) WITH ORDINALITY e(value, ord))
 WHERE i.camp_id IS NOT NULL AND jsonb_typeof(i.camper_names) = 'array'
   AND jsonb_array_length(i.camper_names) > 0;

DROP FUNCTION IF EXISTS public._renumber_in_documents(uuid, bigint, bigint, text);


-- ─── 4. the children the 253 rename bug split in two ────────────────────────
-- The bug left a signature: in one roster save, the child's original number
-- was marked departed and a new number was minted, at the same instant, for
-- the same child under the new name. "The same child" is decided by what
-- does not change with a name, never by the name: the date of birth when both
-- records have one (siblings share an email, never a birthday); the parent's
-- email only when neither has a birthday.
CREATE OR REPLACE FUNCTION public._split_same_child(a jsonb, b jsonb)
RETURNS boolean
LANGUAGE sql
IMMUTABLE
SET search_path = public, pg_catalog
AS $$
    SELECT CASE
        WHEN COALESCE(a ->> 'dob', '') <> '' AND COALESCE(b ->> 'dob', '') <> ''
            THEN a ->> 'dob' = b ->> 'dob'
        WHEN COALESCE(a ->> 'dob', '') = '' AND COALESCE(b ->> 'dob', '') = ''
            THEN COALESCE(lower(btrim(a ->> 'parent1Email')), '') <> ''
                 AND lower(btrim(a ->> 'parent1Email')) = lower(btrim(b ->> 'parent1Email'))
        ELSE false
    END
$$;
-- Only ONE of the two records has a birthday (it was filled in by the same
-- edit that renamed the child), and the parent's email matches: maybe the
-- same child — never repaired automatically, listed for a person (TED-026).
CREATE OR REPLACE FUNCTION public._split_maybe_same_child(a jsonb, b jsonb)
RETURNS boolean
LANGUAGE sql
IMMUTABLE
SET search_path = public, pg_catalog
AS $$
    SELECT (COALESCE(a ->> 'dob', '') = '') <> (COALESCE(b ->> 'dob', '') = '')
       AND COALESCE(lower(btrim(a ->> 'parent1Email')), '') <> ''
       AND lower(btrim(a ->> 'parent1Email')) = lower(btrim(b ->> 'parent1Email'))
$$;
-- A record with nothing to tell a child by: it could be anyone.
CREATE OR REPLACE FUNCTION public._split_unknown(a jsonb)
RETURNS boolean
LANGUAGE sql
IMMUTABLE
SET search_path = public, pg_catalog
AS $$
    SELECT COALESCE(a ->> 'dob', '') = '' AND COALESCE(btrim(a ->> 'parent1Email'), '') = ''
$$;

-- Every pairing the signature allows, and whether it is certain: exactly one
-- original could be this child, and this original could be exactly one child.
DROP FUNCTION IF EXISTS public._split_rename_pairs();
CREATE OR REPLACE FUNCTION public._split_rename_pairs()
RETURNS TABLE (camp_id uuid, original bigint, original_key text, split bigint, split_key text,
               how text, certain boolean)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
    SELECT o.camp_id, o.person_id, o.source_key, s.person_id, s.source_key,
           CASE WHEN COALESCE(o.payload ->> 'dob', '') <> '' AND COALESCE(s.payload ->> 'dob', '') <> ''
                THEN 'same date of birth' ELSE 'same parent email' END,
           -- certain only on a real match (a maybe-match is for a person)…
           public._split_same_child(o.payload, s.payload)
           -- …no other child who left at that instant could be this one…
           AND NOT EXISTS (SELECT 1 FROM camp_people o2
                        WHERE o2.camp_id = o.camp_id AND o2.kind = 'camper' AND o2.person_id <> o.person_id
                          AND o2.deleted_at = o.deleted_at
                          AND (public._split_same_child(o2.payload, s.payload) OR public._split_unknown(o2.payload)))
           -- …and no other child who arrived at that instant could be this original
           AND NOT EXISTS (SELECT 1 FROM camp_people s2
                            WHERE s2.camp_id = o.camp_id AND s2.kind = 'camper' AND s2.minted
                              AND s2.deleted_at IS NULL AND s2.person_id NOT IN (s.person_id, o.person_id)
                              AND s2.first_seen = o.deleted_at
                              AND (public._split_same_child(o.payload, s2.payload) OR public._split_unknown(s2.payload)))
      FROM camp_people o
      JOIN camp_people s
        ON s.camp_id = o.camp_id AND s.kind = 'camper' AND s.minted
       AND s.deleted_at IS NULL AND s.person_id <> o.person_id
       AND s.first_seen = o.deleted_at
     WHERE o.kind = 'camper' AND o.deleted_at IS NOT NULL
       AND (public._split_same_child(o.payload, s.payload) OR public._split_unknown(o.payload)
            OR public._split_maybe_same_child(o.payload, s.payload))
$$;
REVOKE ALL ON FUNCTION public._split_rename_pairs() FROM public, anon, authenticated;

-- Dry run by default: lists every split child, and those a person must look
-- at. With true, each certain one is put back together on the ORIGINAL
-- number (where their money and history are): the split number's rows move
-- onto it, the roster, the saved documents and the invitations show it, and
-- the split number is written down as moved (never given out again).
CREATE OR REPLACE FUNCTION public.split_renames(p_confirm boolean DEFAULT false)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
DECLARE
    r       record;
    v_list  jsonb := '[]'::jsonb;
    v_ask   jsonb := '[]'::jsonb;
    v_item  jsonb;
    n       int := 0;
BEGIN
    FOR r IN SELECT * FROM public._split_rename_pairs() ORDER BY camp_id, split, original LOOP
        v_item := jsonb_build_object('camp_id', r.camp_id, 'camper', r.split_key,
                                     'original_number', r.original, 'split_number', r.split,
                                     'matched_by', r.how);
        IF NOT r.certain OR public._split_unknown((SELECT payload FROM camp_people
                                                    WHERE camp_id = r.camp_id AND person_id = r.original)) THEN
            v_ask := v_ask || (v_item || jsonb_build_object('original_key', r.original_key));
            CONTINUE;
        END IF;
        IF NOT p_confirm THEN
            v_list := v_list || v_item;
            CONTINUE;
        END IF;
        BEGIN
            -- the rows in the tables (refused if both numbers hold a canteen
            -- account — that child is left for a person)…
            PERFORM public._move_person_references(r.camp_id, r.split, r.original);
            -- …the identity: the original number, under the current key…
            DELETE FROM camp_people WHERE camp_id = r.camp_id AND person_id = r.split;
            UPDATE camp_people
               SET source_key = r.split_key, deleted_at = NULL, updated_at = now()
             WHERE camp_id = r.camp_id AND person_id = r.original;
            PERFORM public._record_renumber(r.camp_id, r.split, r.original);
            -- …the roster entry…
            UPDATE camp_state_kv
               SET value = jsonb_set(value, ARRAY['camperRoster', r.split_key, 'camperId'], to_jsonb(r.original), true)
             WHERE camp_id = r.camp_id AND key = 'app1' AND (value -> 'camperRoster') ? r.split_key;
            -- …then every saved document and invitation.
            PERFORM public._apply_pending_renumbers();
            n := n + 1;
            v_list := v_list || v_item;
        EXCEPTION WHEN OTHERS THEN
            v_ask := v_ask || (v_item || jsonb_build_object('not_repaired', SQLERRM));
        END;
    END LOOP;
    RETURN jsonb_build_object('success', true, 'dry_run', NOT p_confirm, 'split_children', v_list,
                              'repaired', n, 'needs_a_person', v_ask,
                              'to_repair', CASE WHEN NOT p_confirm AND jsonb_array_length(v_list) > 0
                                                THEN 'SELECT public.split_renames(true);' END);
END;
$$;
REVOKE ALL ON FUNCTION public.split_renames(boolean) FROM public, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.split_renames(boolean) TO service_role;


-- ─── a parent's photos carry the child's number ─────────────────────────────
-- get_my_camper_photos (081, gated by number since 258) returned each photo's
-- camper by name only, so the portal filed photos under a child by name. It
-- returns the number too. Rewritten in place: one line added.
DO $$
DECLARE d text; n text;
BEGIN
    SELECT pg_get_functiondef(p.oid) INTO d FROM pg_proc p JOIN pg_namespace ns ON ns.oid = p.pronamespace
     WHERE ns.nspname = 'public' AND p.proname = 'get_my_camper_photos';
    IF d IS NULL OR d ~ '''camper_id'',\s*t\.person_id' THEN RETURN; END IF;
    n := regexp_replace(d, '''camper'',\s*t\.camper_name', '''camper'',     t.camper_name,
            ''camper_id'',  t.person_id');
    IF n = d THEN RAISE EXCEPTION '260: get_my_camper_photos is not the text this expects — send this message to the builder'; END IF;
    EXECUTE n;
END $$;


-- ▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼
-- 261_only_the_camp_office_writes_parent_invites.sql
-- ▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲

-- ============================================================================
-- Migration 261: only the camp's office can write a parent invitation.
-- (Ted TED-023)
--
-- THE HOLE. upsert_parent_invite (011 → 087 → 131) checked only that the
-- caller was logged in. Any account — a parent of another camp, or a stranger
-- who signed up — could write an invitation for ANY camp under their own
-- email, naming any child (or naming none, which covers every child in the
-- camp), then claim it with the access code the function handed back. The
-- portal then treated them as that child's parent.
--
-- THE RULE. Writing an invitation is the office's act: the camp owner, or a
-- member of the camp with the owner, admin or manager role — the same people
-- who enrol campers. Everyone else is refused. And the function never writes
-- an invitation that names no children (which would cover the whole camp):
-- a missing list is written as an empty one, which covers nobody.
--
-- AND (TED-047) whether a family is still at camp is decided by its children's
-- numbers, not their names.
--
-- THE SAME HOLE FROM INSIDE (TED-028). The office's list of invitations —
-- with every family's access code — was open to ANY member of the camp, a
-- counselor or a viewer too, who could then claim a family's code on their own
-- login. That list, and every other function that binds or changes a family's
-- invitation, is the office's too now.
--
-- Standalone. Does NOT need 260 — paste it into the Supabase SQL Editor and
-- run it as soon as you can. Safe to run twice — and if you ran an EARLIER
-- copy of this file, run this one again: it closes more (the verify script's
-- 261 row says "run 261 again" until you do). NOT part of APPLY_BUNDLE.sql.
-- Afterwards, run the read-only check at the bottom of this file.
-- ============================================================================

-- The code a parent claims with (010); already there on a live database.
ALTER TABLE public.link_parent_invites ADD COLUMN IF NOT EXISTS access_code text;

CREATE OR REPLACE FUNCTION public._is_camp_office(p_camp_id uuid, p_caller uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
    SELECT p_camp_id IS NOT NULL AND p_caller IS NOT NULL AND (
           EXISTS (SELECT 1 FROM camps WHERE id = p_camp_id AND owner = p_caller)
        OR EXISTS (SELECT 1 FROM camp_users
                    WHERE camp_id = p_camp_id AND user_id = p_caller
                      AND role IN ('owner', 'admin', 'manager')));
$$;
REVOKE ALL ON FUNCTION public._is_camp_office(uuid, uuid) FROM public, anon, authenticated;

CREATE OR REPLACE FUNCTION public.upsert_parent_invite(
    p_camp_id      uuid,
    p_token        text,
    p_parent_name  text,
    p_parent_email text,
    p_camper_names jsonb,
    p_camper_data  jsonb,
    p_expires_at   timestamptz
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
DECLARE
    v_existing_id    uuid;
    v_existing_token text;
    v_existing_code  text;
    v_code           text;
    v_names          jsonb;
BEGIN
    IF auth.uid() IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_authenticated');
    END IF;
    -- 261: only this camp's office writes its invitations.
    IF NOT public._is_camp_office(p_camp_id, auth.uid()) THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_camp_office');
    END IF;
    IF COALESCE(btrim(p_parent_email), '') = '' THEN
        RETURN jsonb_build_object('success', false, 'error', 'missing_email');
    END IF;
    -- Never an invitation that covers the whole camp: no list is an empty list.
    v_names := CASE WHEN jsonb_typeof(p_camper_names) = 'array' THEN p_camper_names ELSE '[]'::jsonb END;

    SELECT id, token, access_code
    INTO v_existing_id, v_existing_token, v_existing_code
    FROM link_parent_invites
    WHERE camp_id      = p_camp_id
      AND parent_email = p_parent_email
      AND status       = 'active'
    ORDER BY created_at DESC
    LIMIT 1;

    IF FOUND THEN
        v_code := COALESCE(
            NULLIF(v_existing_code, ''),
            upper(
                substring(replace(gen_random_uuid()::text, '-', '') from 1 for 4) || '-' ||
                substring(replace(gen_random_uuid()::text, '-', '') from 5 for 4)
            )
        );
        -- user_id intentionally NOT reset (087); camp_connected reset (131).
        UPDATE link_parent_invites
        SET parent_name    = p_parent_name,
            camper_names   = v_names,
            camper_data    = p_camper_data,
            access_code    = v_code,
            camp_connected = true
        WHERE id = v_existing_id;

        RETURN jsonb_build_object('success', true, 'action', 'updated',
                                  'token', v_existing_token, 'access_code', v_code);
    ELSE
        v_code := upper(
            substring(replace(gen_random_uuid()::text, '-', '') from 1 for 4) || '-' ||
            substring(replace(gen_random_uuid()::text, '-', '') from 5 for 4)
        );
        INSERT INTO link_parent_invites
            (camp_id, token, access_code, parent_name, parent_email,
             camper_names, camper_data, status, expires_at)
        VALUES
            (p_camp_id, p_token, v_code, p_parent_name, p_parent_email,
             v_names, p_camper_data, 'active', p_expires_at);

        RETURN jsonb_build_object('success', true, 'action', 'created',
                                  'token', p_token, 'access_code', v_code);
    END IF;
END;
$$;
REVOKE ALL ON FUNCTION public.upsert_parent_invite(uuid, text, text, text, jsonb, jsonb, timestamptz) FROM public, anon;
GRANT EXECUTE ON FUNCTION public.upsert_parent_invite(uuid, text, text, text, jsonb, jsonb, timestamptz) TO authenticated;

-- ─── the office functions that let ANY camp member through (TED-028) ────────
-- These let the camp owner or ANY member of the camp in — counselors and
-- viewers included:
--   get_camp_parent_invites      (032) lists every family's invitation WITH its
--                                      access code — which anyone can then claim
--                                      on their own login (claim_invite_by_code)
--   resolve_join_request         (032) binds a login to a family
--   set_parent_invite_email      (034) points a family's invitation at an email
--   set_parent_billing_access    (070) opens a family's billing to its login
--   revoke_orphaned_parent_invites (122) closes families' invitations
-- Each is the office's act. Rewritten in place: the membership check becomes
-- "the camp office" (owner, admin, manager); nothing else changes.
DO $$
DECLARE
    f     text;
    d     text;
    n     text;
    v_re  text := 'IF\s+NOT\s+EXISTS\s*\(\s*SELECT\s+1\s+FROM\s+camps\s+c\s+WHERE\s+c\.id\s*=\s*([a-z_.]+)\s+AND\s+c\.owner\s*=\s*caller\s*\)\s*AND\s+NOT\s+EXISTS\s*\(\s*SELECT\s+1\s+FROM\s+camp_users\s+u\s+WHERE\s+u\.camp_id\s*=\s*[a-z_.]+\s+AND\s+u\.user_id\s*=\s*caller\s*\)\s*THEN\s*RETURN\s+jsonb_build_object\(\s*''success'',\s*false,\s*''error'',\s*''not_a_member''\s*\)';
BEGIN
    FOREACH f IN ARRAY ARRAY['get_camp_parent_invites', 'resolve_join_request', 'set_parent_invite_email',
                             'set_parent_billing_access', 'revoke_orphaned_parent_invites'] LOOP
        FOR d IN SELECT pg_get_functiondef(p.oid) FROM pg_proc p JOIN pg_namespace ns ON ns.oid = p.pronamespace
                  WHERE ns.nspname = 'public' AND p.proname = f LOOP
            CONTINUE WHEN d ~ '_is_camp_office';                  -- already done
            n := regexp_replace(d, v_re,
                   'IF NOT public._is_camp_office(\1, caller) THEN RETURN jsonb_build_object(''success'', false, ''error'', ''not_camp_office'')');
            IF n = d THEN
                RAISE EXCEPTION '261: % does not look the way this file expects — send this message to the builder', f;
            END IF;
            EXECUTE n;
        END LOOP;
    END LOOP;
END $$;

-- ─── "is this family still at camp?" goes by number (TED-047) ───────────────
-- When a family's last child leaves, their parent app is switched off for live
-- camp features (122). That was decided by NAME — a new child with the same
-- name kept a departed child's family switched on. Now by number: an
-- invitation stays connected while one of its children's numbers is still an
-- enrolled camper. Only an invitation that carries no number at all (written
-- before its child was numbered) is still decided by its names.
--
-- A number counts as enrolled when the page says so OR the database's own
-- roster copy (camp_people: on the roster, not unenrolled) says so — the page
-- can hold a child's old number for a few seconds after a save, and a family
-- must never be switched off on that (TED-049). A slot whose number is not
-- filled in yet (a sibling added a moment ago) keeps the family on when that
-- slot's name is on the roster. A list of numbers with no usable number in it
-- counts as empty.
CREATE OR REPLACE FUNCTION public.revoke_orphaned_parent_invites(
    p_camp_id      uuid,
    p_roster_names jsonb,
    p_roster_ids   jsonb             -- the numbers of every camper still enrolled
)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
DECLARE
    caller uuid := auth.uid();
    n      int := 0;
    v_ids  bigint[];
BEGIN
    IF caller IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'not_authenticated'); END IF;
    IF NOT public._is_camp_office(p_camp_id, caller) THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_camp_office');
    END IF;
    -- Safety: never mass-disconnect when we were handed an empty roster —
    -- counted in usable numbers, not list items ('[null]' is empty).
    IF p_roster_ids IS NOT NULL AND jsonb_typeof(p_roster_ids) = 'array' THEN
        v_ids := ARRAY(SELECT DISTINCT public._stated_person_id(x #>> '{}') FROM jsonb_array_elements(p_roster_ids) x
                        WHERE public._stated_person_id(x #>> '{}') IS NOT NULL);
    END IF;
    IF COALESCE(cardinality(v_ids), 0) = 0 THEN
        RETURN jsonb_build_object('success', true, 'revoked', 0, 'skipped', 'empty_roster');
    END IF;
    -- plus every camper the database itself has on the roster and enrolled
    v_ids := v_ids || ARRAY(SELECT p.person_id FROM camp_people p
                             WHERE p.camp_id = p_camp_id AND p.kind = 'camper' AND p.deleted_at IS NULL
                               AND lower(COALESCE(p.payload ->> 'unenrolled', '')) NOT IN ('true', '1', 'yes'));

    WITH stale AS (
        SELECT i.id
          FROM link_parent_invites i
         WHERE i.camp_id = p_camp_id
           AND i.camp_connected = true
           AND CASE
                 -- the invitation's children by number
                 WHEN EXISTS (SELECT 1 FROM jsonb_array_elements(CASE WHEN jsonb_typeof(i.person_ids) = 'array'
                                                                      THEN i.person_ids ELSE '[]'::jsonb END) x
                               WHERE public._stated_person_id(x #>> '{}') IS NOT NULL)
                 THEN NOT EXISTS (SELECT 1 FROM jsonb_array_elements(i.person_ids) x
                                   WHERE public._stated_person_id(x #>> '{}') = ANY (v_ids))
                      -- a child on it whose number is not filled in yet, still on the roster
                      AND NOT (jsonb_typeof(p_roster_names) = 'array' AND jsonb_typeof(i.camper_names) = 'array'
                               AND EXISTS (SELECT 1 FROM jsonb_array_elements_text(i.camper_names) WITH ORDINALITY cn(name, ord)
                                            WHERE public._stated_person_id(i.person_ids ->> (cn.ord - 1)::int) IS NULL
                                              AND p_roster_names ? cn.name))
                 -- no number on it yet: its names, as before
                 ELSE jsonb_typeof(p_roster_names) = 'array' AND jsonb_array_length(p_roster_names) > 0
                      AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements_text(COALESCE(i.camper_names, '[]'::jsonb)) cn
                                       WHERE p_roster_names ? cn)
               END
    )
    UPDATE link_parent_invites SET camp_connected = false
     WHERE id IN (SELECT id FROM stale);
    GET DIAGNOSTICS n = ROW_COUNT;
    RETURN jsonb_build_object('success', true, 'revoked', n);
END;
$$;
REVOKE ALL ON FUNCTION public.revoke_orphaned_parent_invites(uuid, jsonb, jsonb) FROM public, anon;
GRANT EXECUTE ON FUNCTION public.revoke_orphaned_parent_invites(uuid, jsonb, jsonb) TO authenticated;

-- ─── reading the invitations table itself (TED-028) ─────────────────────────
-- The table's staff read rule (098) let a scheduler read every column —
-- every family's access code and token — straight from the table, and claim
-- a family with it. Staff reads are the office's now, like the functions
-- above. (A parent still reads their OWN invitation: 009's parent rule.)
ALTER TABLE public.link_parent_invites ENABLE ROW LEVEL SECURITY;   -- as it is live (008)
DROP POLICY IF EXISTS link_parent_invites_select ON public.link_parent_invites;
CREATE POLICY link_parent_invites_select ON public.link_parent_invites
    FOR SELECT
    USING (
        camp_id = get_user_camp_id()
        AND get_user_role() = ANY (ARRAY['owner'::text, 'admin'::text, 'manager'::text])
    );

-- ─── read-only check: was the hole used? ────────────────────────────────────
-- Every claimed invitation that covers a whole camp (it names no children).
