-- 262_autopay_waits_for_a_bank_debit.sql
-- ▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲

-- ============================================================================
-- Migration 262: autopay waits for a bank debit instead of starting another.
--
-- Standalone. Paste into the Supabase SQL Editor and click Run. Safe to run
-- more than once.
--
-- ── THE PROBLEM (TED-064) ──────────────────────────────────────────────────
-- A bank-account (ACH) debit takes days to clear. Stripe answers the nightly
-- autopay charge with status "processing", and charge-due-installments
-- deliberately recorded nothing — so the next night the same instalment still
-- looked unpaid and was debited AGAIN, every night until the first cleared. A
-- $500 instalment became three or four $500 debits.
--
-- ── THE CHANGE ─────────────────────────────────────────────────────────────
-- The runner now writes the debit onto the plan as `pendingCharge`
-- ({paymentIntentId, index, dueDate, amount, since}) the moment Stripe says
-- "processing". While it is there, the runner does not charge that plan: each
-- night it asks Stripe how that one debit is doing — succeeded: record it as
-- the instalment it was for; failed: the normal decline path; still
-- processing: wait. This function is the only writer of that field.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.hold_autopay_charge(
    p_camp_id    uuid,
    p_family_key text,
    p_plan_id    text,
    p_hold       jsonb        -- NULL clears the hold
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
DECLARE
    v_fam   jsonb;
    v_plans jsonb;
    v_pi    integer := NULL;
    i       integer;
BEGIN
    IF p_camp_id IS NULL OR COALESCE(p_family_key, '') = '' OR COALESCE(p_plan_id, '') = '' THEN
        RETURN jsonb_build_object('success', false, 'error', 'bad_arguments');
    END IF;
    v_fam := public.camp_family_for_update(p_camp_id, p_family_key);
    IF v_fam IS NULL OR jsonb_typeof(v_fam) <> 'object' THEN
        RETURN jsonb_build_object('success', false, 'error', 'family_not_found');
    END IF;
    v_plans := CASE WHEN jsonb_typeof(v_fam->'plans') = 'array' THEN v_fam->'plans' ELSE '[]'::jsonb END;
    FOR i IN 0 .. GREATEST(jsonb_array_length(v_plans) - 1, -1) LOOP
        IF v_plans->i->>'id' = p_plan_id THEN v_pi := i; EXIT; END IF;
    END LOOP;
    IF v_pi IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'plan_not_found');
    END IF;

    IF p_hold IS NULL OR jsonb_typeof(p_hold) <> 'object' THEN
        v_plans := jsonb_set(v_plans, ARRAY[v_pi::text], (v_plans->v_pi) - 'pendingCharge', true);
    ELSE
        v_plans := jsonb_set(v_plans, ARRAY[v_pi::text, 'pendingCharge'], p_hold, true);
    END IF;
    v_fam := jsonb_set(v_fam, '{plans}', v_plans, true);
    PERFORM public.camp_family_save(p_camp_id, p_family_key, v_fam);
    RETURN jsonb_build_object('success', true);
END;
$$;
REVOKE ALL ON FUNCTION public.hold_autopay_charge(uuid, text, text, jsonb) FROM public, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.hold_autopay_charge(uuid, text, text, jsonb) TO service_role;


-- ▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼
-- 263_a_cancelled_charge_leaves_the_ledger.sql
-- ▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲

-- ============================================================================
-- Migration 263: a charge that is cancelled or re-priced leaves the ledger too.
--
-- Standalone. Paste into the Supabase SQL Editor and click Run. Safe to run
-- more than once.
--
-- ── THE PROBLEM (TED-066) ──────────────────────────────────────────────────
-- A family's extra charges (a Camp Shop order billed to the family, a late fee)
-- live in families[].charges AND, since the office's Billing started posting
-- them (TED-053), on the family's ledger — which is what both balances read.
-- Cancelling a Camp Shop order removed it from charges[] only, so a $40 order
-- that was cancelled kept billing the family $40.
--
-- ── THE CHANGE ─────────────────────────────────────────────────────────────
-- _sync_charge_to_ledger(family, chargeId) makes the ledger agree with what
-- charges[] now says for that one charge: it adds up what the ledger already
-- holds for it (entries whose source.chargeId is that id) and posts the
-- difference — nothing when they agree. The first posting uses the id the Me
-- page uses (le_chg_<id>), later ones le_chgadj_<id>_<n>, so the database and
-- the Me page can never post the same charge twice. A family with no ledger
-- yet is left alone (its balance still comes from charges[]).
--
-- settle_shop_order (239) now runs it on the family it saves.
-- ============================================================================

CREATE OR REPLACE FUNCTION public._sync_charge_to_ledger(p_fam jsonb, p_charge_id text)
RETURNS jsonb
LANGUAGE plpgsql
IMMUTABLE
SET search_path = public, pg_catalog
AS $$
DECLARE
    v_entries jsonb := CASE WHEN jsonb_typeof(p_fam->'entries') = 'array' THEN p_fam->'entries' ELSE '[]'::jsonb END;
    v_target  numeric := 0;
    v_posted  numeric := 0;
    v_any     boolean := false;
    v_n       integer := 0;
    v_diff    numeric;
    v_desc    text := '';
    v_date    text;
    c         jsonb;
    e         jsonb;
BEGIN
    IF p_fam IS NULL OR COALESCE(p_charge_id, '') = '' OR jsonb_array_length(v_entries) = 0 THEN
        RETURN p_fam;
    END IF;
    FOR c IN SELECT * FROM jsonb_array_elements(CASE WHEN jsonb_typeof(p_fam->'charges') = 'array'
                                                     THEN p_fam->'charges' ELSE '[]'::jsonb END) LOOP
        IF c->>'id' = p_charge_id THEN
            v_target := v_target + GREATEST(COALESCE((c->>'amount')::numeric, 0), 0);
            v_desc := COALESCE(c->>'description', c->>'category', 'Charge');
        END IF;
    END LOOP;
    FOR e IN SELECT * FROM jsonb_array_elements(v_entries) LOOP
        IF e->'source'->>'chargeId' = p_charge_id THEN
            v_any := true;
            v_n := v_n + 1;
            v_posted := v_posted + CASE e->>'kind'
                WHEN 'charge' THEN COALESCE((e->>'amount')::numeric, 0)
                WHEN 'credit' THEN -COALESCE((e->>'amount')::numeric, 0)
                ELSE 0 END;
        END IF;
    END LOOP;
    v_diff := round(v_target - v_posted, 2);
    IF v_diff = 0 THEN RETURN p_fam; END IF;
    v_date := to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD');
    RETURN jsonb_set(p_fam, '{entries}', v_entries || jsonb_build_array(jsonb_build_object(
        'id', CASE WHEN v_any THEN 'le_chgadj_' || p_charge_id || '_' || v_n ELSE 'le_chg_' || p_charge_id END,
        'kind', CASE WHEN v_diff > 0 THEN 'charge' ELSE 'credit' END,
        'amount', abs(v_diff),
        'reason', CASE WHEN v_diff > 0 THEN (CASE WHEN v_any THEN 'other' ELSE 'fee' END) ELSE 'reversal' END,
        'date', v_date,
        'postedAt', to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
        'note', CASE WHEN v_target = 0 THEN 'Cancelled — ' || COALESCE(NULLIF(v_desc, ''), 'charge')
                     WHEN v_any THEN 'Changed — ' || v_desc ELSE v_desc END,
        'by', 'system',
        'source', jsonb_build_object('chargeId', p_charge_id)
    )), true);
END;
$$;
REVOKE ALL ON FUNCTION public._sync_charge_to_ledger(jsonb, text) FROM public, anon, authenticated;


-- settle_shop_order: sync the order's charge onto the ledger in the same save.
DO $$
DECLARE
    d   text := pg_get_functiondef('public.settle_shop_order(uuid,text,text,numeric,boolean)'::regprocedure);
    old text := $o$v_fam || jsonb_build_object('charges', v_kept));$o$;
    new text := $n$public._sync_charge_to_ledger(v_fam || jsonb_build_object('charges', v_kept), v_chargeId));$n$;
BEGIN
    IF position('_sync_charge_to_ledger' IN d) > 0 THEN
        RAISE NOTICE '263: settle_shop_order already syncs the ledger';
        RETURN;
    END IF;
    IF position(old IN d) = 0 THEN
        RAISE EXCEPTION '263: settle_shop_order does not look the way this file expects — send this message to the builder';
    END IF;
    EXECUTE replace(d, old, new);
END $$;


-- ▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼
-- 264_a_plan_charges_the_amounts_the_office_set.sql
-- ▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲

-- ============================================================================
-- Migration 264: a payment plan charges the amounts the office set.
--
-- Standalone. Paste into the Supabase SQL Editor and click Run. Safe to run
-- more than once.
--
-- ── THE PROBLEM (TED-068) ──────────────────────────────────────────────────
-- A ledger plan (172/181) stores only dates; each instalment is worked out at
-- charge time as "what is still owed / instalments left". The office's plan
-- editor asks for an amount per payment — $1,000 then $200 and $200, or $600
-- of a $1,400 balance — and those amounts were thrown away: autopay charged
-- $466.67 three times, or $700 + $700.
--
-- ── THE CHANGE ─────────────────────────────────────────────────────────────
-- A plan may carry `amounts`, one per due date. When the instalment being
-- charged has one, that is what is charged — never more than is still owed.
-- A plan without amounts (every plan a parent builds) is worked out exactly as
-- before. 172's plan_due with that one branch added; the rest is unchanged.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.plan_due(p_fam jsonb, p_plan jsonb, p_as_of text)
RETURNS jsonb
LANGUAGE plpgsql
IMMUTABLE
SET search_path = public, pg_catalog
AS $$
DECLARE
    v_dates jsonb;
    v_i     integer;
    v_due   text;
    v_bal   numeric;
    v_rem   integer;
    v_amt   numeric;
    v_fixed numeric;
BEGIN
    IF p_plan IS NULL OR jsonb_typeof(p_plan) <> 'object' THEN RETURN NULL; END IF;
    IF COALESCE((p_plan->>'paused')::boolean, false) THEN RETURN NULL; END IF;
    IF NOT COALESCE((p_plan->>'autopay')::boolean, true) THEN RETURN NULL; END IF;

    v_dates := CASE WHEN jsonb_typeof(p_plan->'dueDates') = 'array'
                    THEN p_plan->'dueDates' ELSE '[]'::jsonb END;
    v_i := COALESCE((p_plan->>'nextIndex')::integer, 0);
    IF v_i >= jsonb_array_length(v_dates) THEN RETURN NULL; END IF;

    v_due := v_dates->>v_i;
    IF v_due IS NULL OR (p_as_of IS NOT NULL AND v_due > p_as_of) THEN RETURN NULL; END IF;

    v_bal := public.family_ledger_balance(p_fam);
    v_rem := jsonb_array_length(v_dates) - v_i;

    -- Nothing owed: due nothing, and — crucially — destroy nothing.
    IF v_bal <= 0.005 THEN
        RETURN jsonb_build_object('index', v_i, 'dueDate', v_due,
                                  'amount', 0, 'remaining', v_rem,
                                  'reason', 'nothing_owed');
    END IF;

    -- The amount the office set for this instalment, when it set one (TED-068).
    IF jsonb_typeof(p_plan->'amounts') = 'array'
       AND jsonb_typeof(p_plan->'amounts'->v_i) = 'number' THEN
        v_fixed := (p_plan->'amounts'->>v_i)::numeric;
    END IF;

    IF v_fixed IS NOT NULL AND v_fixed > 0 THEN
        v_amt := LEAST(ROUND(v_fixed, 2), v_bal);
    ELSE
        -- The last instalment sweeps the remainder, so rounding cannot leave
        -- cents uncollectable at the end of every plan.
        v_amt := CASE WHEN v_rem <= 1 THEN v_bal ELSE ROUND(v_bal / v_rem, 2) END;
        IF v_amt > v_bal THEN v_amt := v_bal; END IF;
    END IF;

    RETURN jsonb_build_object('index', v_i, 'dueDate', v_due,
                              'amount', v_amt, 'remaining', v_rem);
END;
$$;
REVOKE ALL ON FUNCTION public.plan_due(jsonb, jsonb, text) FROM public, anon;
GRANT EXECUTE ON FUNCTION public.plan_due(jsonb, jsonb, text) TO authenticated, service_role;


-- ▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼
-- 265_a_bank_deposit_reaches_the_ledger.sql
-- ▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲

-- ============================================================================
-- Migration 265: a Zelle / bank-transfer payment reaches the family's ledger.
--
-- Standalone. Paste into the Supabase SQL Editor and click Run. Safe to run
-- more than once.
--
-- ── THE PROBLEM (TED-077) ──────────────────────────────────────────────────
-- Bank deposits (Zelle, ACH — read from the bank's alert emails) live in the
-- bank_deposits table. When one is posted to a family, nothing put it on that
-- family's LEDGER, and the ledger is what the office's Billing, the parent's
-- balance and autopay all read once a family has one. A family that paid $400
-- by Zelle on a $1,000 bill still showed $1,000, and autopay collected $500 +
-- $500 — $1,400 in all. (sync_family_ledger_payments, 178/215, can post them,
-- but nothing calls it.)
--
-- ── THE CHANGE ─────────────────────────────────────────────────────────────
-- A trigger on bank_deposits keeps each family's ledger equal to what the
-- deposit table says, whatever changed it — the email reader posting it, the
-- office matching or re-matching it, ignoring it, a bank return:
--   * what the ledger holds for a deposit is the sum of its entries tagged
--     source.depositId (payment +, refund −);
--   * what it should hold is the amount (negative for a return) when the
--     deposit is 'posted' to THIS family, else nothing;
--   * the difference is posted — first as le_dep_<id> (the id
--     sync_family_ledger_payments uses, so the two never double up), later as
--     le_depadj_<id>_<n>. Nothing when they already agree.
-- A family with no ledger yet is left alone (its balance is still derived, and
-- that already counts deposits). An entry the 171 conversion wrote for the
-- deposit (no id; matched by family_covers_deposit) counts as posted.
--
-- Every deposit already posted is brought into line once, at the end.
-- ============================================================================

CREATE OR REPLACE FUNCTION public._sync_deposit_to_ledger(p_camp_id uuid, p_family_key text, p_dep_id uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
DECLARE
    v_fam     jsonb;
    v_entries jsonb;
    d         record;
    v_target  numeric := 0;
    v_net     numeric := 0;
    v_n       integer := 0;
    v_diff    numeric;
    v_date    text;
    e         jsonb;
BEGIN
    IF p_camp_id IS NULL OR COALESCE(p_family_key, '') = '' OR p_dep_id IS NULL THEN RETURN; END IF;
    SELECT id, amount_cents, is_reversal, status, family_key, deposit_date, created_at
      INTO d FROM bank_deposits WHERE id = p_dep_id;

    v_fam := public.camp_family_for_update(p_camp_id, p_family_key);
    IF v_fam IS NULL OR jsonb_typeof(v_fam) <> 'object' THEN RETURN; END IF;
    v_entries := CASE WHEN jsonb_typeof(v_fam->'entries') = 'array' THEN v_fam->'entries' ELSE '[]'::jsonb END;
    IF jsonb_array_length(v_entries) = 0 THEN RETURN; END IF;       -- no ledger yet

    IF d.id IS NOT NULL AND d.status = 'posted' AND d.family_key = p_family_key THEN
        v_target := ROUND(ABS(d.amount_cents::numeric) / 100, 2)
                    * CASE WHEN d.is_reversal THEN -1 ELSE 1 END;
    END IF;
    v_date := COALESCE(to_char(d.deposit_date, 'YYYY-MM-DD'), to_char(d.created_at, 'YYYY-MM-DD'),
                       to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD'));

    FOR e IN SELECT * FROM jsonb_array_elements(v_entries) LOOP
        IF e->'source'->>'depositId' = p_dep_id::text OR e->>'id' = 'le_dep_' || p_dep_id::text THEN
            v_n := v_n + 1;
            v_net := v_net + CASE e->>'kind'
                WHEN 'payment' THEN COALESCE((e->>'amount')::numeric, 0)
                WHEN 'refund'  THEN -COALESCE((e->>'amount')::numeric, 0)
                ELSE 0 END;
        END IF;
    END LOOP;
    -- The 171 conversion posted deposits with no id: one it covers is posted.
    IF v_n = 0 AND v_target <> 0 AND d.id IS NOT NULL
       AND public.family_covers_deposit(v_fam, d.id, ABS(v_target), v_date) THEN
        RETURN;
    END IF;

    v_diff := ROUND(v_target - v_net, 2);
    IF v_diff = 0 THEN RETURN; END IF;

    v_entries := v_entries || jsonb_build_array(jsonb_build_object(
        'id',       CASE WHEN v_n = 0 THEN 'le_dep_' || p_dep_id::text
                         ELSE 'le_depadj_' || p_dep_id::text || '_' || v_n END,
        'kind',     CASE WHEN v_diff > 0 THEN 'payment' ELSE 'refund' END,
        'amount',   ABS(v_diff),
        'reason',   CASE WHEN v_diff > 0 THEN 'zelle' ELSE 'reversal' END,
        'date',     v_date,
        'postedAt', to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
        'note',     CASE WHEN v_target = 0 THEN 'Bank deposit no longer on this account'
                         WHEN v_diff < 0 THEN 'Bank deposit reversed'
                         ELSE 'Bank deposit' END,
        'by',       'system',
        'source',   jsonb_build_object('depositId', p_dep_id::text)));
    PERFORM public.camp_family_save(p_camp_id, p_family_key, jsonb_set(v_fam, '{entries}', v_entries, true));
END;
$$;
REVOKE ALL ON FUNCTION public._sync_deposit_to_ledger(uuid, text, uuid) FROM public, anon, authenticated;


CREATE OR REPLACE FUNCTION public._bank_deposit_to_ledger()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
BEGIN
    IF TG_OP IN ('UPDATE', 'DELETE') AND OLD.family_key IS NOT NULL THEN
        PERFORM public._sync_deposit_to_ledger(OLD.camp_id, OLD.family_key, OLD.id);
    END IF;
    IF TG_OP IN ('INSERT', 'UPDATE') AND NEW.family_key IS NOT NULL
       AND (TG_OP = 'INSERT' OR NEW.family_key IS DISTINCT FROM OLD.family_key
            OR NEW.status IS DISTINCT FROM OLD.status
            OR NEW.amount_cents IS DISTINCT FROM OLD.amount_cents
            OR NEW.is_reversal IS DISTINCT FROM OLD.is_reversal
            OR OLD.family_key IS NULL) THEN
        PERFORM public._sync_deposit_to_ledger(NEW.camp_id, NEW.family_key, NEW.id);
    END IF;
    RETURN NULL;
END;
$$;
REVOKE ALL ON FUNCTION public._bank_deposit_to_ledger() FROM public, anon, authenticated;

DROP TRIGGER IF EXISTS trg_bank_deposit_to_ledger ON public.bank_deposits;
CREATE TRIGGER trg_bank_deposit_to_ledger
AFTER INSERT OR UPDATE OF status, family_key, amount_cents, is_reversal OR DELETE
ON public.bank_deposits
FOR EACH ROW EXECUTE FUNCTION public._bank_deposit_to_ledger();

-- Every deposit already posted to a family with a ledger, once.
DO $$
DECLARE r record;
BEGIN
    FOR r IN SELECT id, camp_id, family_key FROM bank_deposits
              WHERE status = 'posted' AND family_key IS NOT NULL LOOP
        PERFORM public._sync_deposit_to_ledger(r.camp_id, r.family_key, r.id);
    END LOOP;
END $$;


-- ▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼
-- 266_an_old_tab_cannot_undo_the_server.sql
-- ▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲

-- ============================================================================
-- Migration 266: an office tab left open cannot undo what the server wrote.
--
-- Standalone. Paste into the Supabase SQL Editor and click Run. Safe to run
-- more than once.
--
-- ── THE PROBLEM (TED-078) ──────────────────────────────────────────────────
-- The Me page saves a family as a WHOLE object, from the copy it loaded. The
-- nightly autopay runner, the payment webhooks, the shop and the bank-deposit
-- trigger all write to the same family in between. An office tab opened
-- yesterday and saved this morning wrote yesterday's copy back over all of it:
-- the "bank debit in flight" hold (so the family was debited again that
-- night), the plan's payment counter and history, a card decline flag, and any
-- ledger entry posted since the tab loaded.
--
-- ── THE CHANGE ─────────────────────────────────────────────────────────────
-- _merge_family_from_page(server, page) keeps the office's edits and never
-- drops what only the server writes:
--   * ledger entries: every entry already on the row is kept (the ledger is
--     append-only; the page never deletes one), plus whatever the page adds;
--   * each plan the page still has (by id): pendingCharge and collectionBlocked
--     are the server's; nextIndex is the higher of the two; history is the
--     longer; an old-style instalment the server marked paid, or recorded a
--     decline on, keeps that;
--   * a plan the page removed is removed (the office cancelled it), and the
--     page's dates/amounts/autopay switch are the office's to set.
-- Both of the page's save paths use it: sync_camp_billing, and the trigger
-- that copies families out of the settings document (project_camp_families).
-- ============================================================================

-- Only when nothing newer is in place: re-running this file on its own must
-- not put back an older merge over a later migration's (TED-094).
DO $guard$
BEGIN
    IF to_regprocedure('public._merge_family_from_page(jsonb,jsonb)') IS NULL
       OR pg_get_functiondef(to_regprocedure('public._merge_family_from_page(jsonb,jsonb)')) !~ '_keep_charge_links|_merge_plan_state' THEN
        EXECUTE $fn$
CREATE OR REPLACE FUNCTION public._merge_family_from_page(p_server jsonb, p_page jsonb)
RETURNS jsonb
LANGUAGE plpgsql
IMMUTABLE
SET search_path = public, pg_catalog
AS $$
DECLARE
    v_out     jsonb := p_page;
    v_pe      jsonb;
    v_se      jsonb;
    v_ids     text[];
    v_plans   jsonb := '[]'::jsonb;
    v_sp      jsonb;
    v_pp      jsonb;
    v_insts   jsonb;
    v_si      jsonb;
    e         jsonb;
    p         jsonb;
    i         jsonb;
BEGIN
    IF p_server IS NULL OR jsonb_typeof(p_server) <> 'object'
       OR p_page IS NULL OR jsonb_typeof(p_page) <> 'object' THEN
        RETURN p_page;
    END IF;

    -- ── ledger entries: never lose one ───────────────────────────────────────
    v_pe := CASE WHEN jsonb_typeof(p_page->'entries') = 'array' THEN p_page->'entries' ELSE '[]'::jsonb END;
    v_se := CASE WHEN jsonb_typeof(p_server->'entries') = 'array' THEN p_server->'entries' ELSE '[]'::jsonb END;
    IF jsonb_array_length(v_se) > 0 THEN
        SELECT COALESCE(array_agg(x->>'id'), '{}') INTO v_ids FROM jsonb_array_elements(v_pe) x;
        FOR e IN SELECT * FROM jsonb_array_elements(v_se) LOOP
            IF COALESCE(e->>'id', '') <> '' AND NOT (e->>'id' = ANY (v_ids)) THEN
                v_pe := v_pe || jsonb_build_array(e);
            END IF;
        END LOOP;
        v_out := jsonb_set(v_out, '{entries}', v_pe, true);
    END IF;

    -- ── plans: the server's running state on every plan the page kept ───────
    IF jsonb_typeof(p_page->'plans') = 'array' AND jsonb_typeof(p_server->'plans') = 'array' THEN
        FOR p IN SELECT * FROM jsonb_array_elements(p_page->'plans') LOOP
            v_pp := p;
            v_sp := NULL;
            IF COALESCE(p->>'id', '') <> '' THEN
                SELECT x INTO v_sp FROM jsonb_array_elements(p_server->'plans') x WHERE x->>'id' = p->>'id' LIMIT 1;
            END IF;
            IF v_sp IS NOT NULL THEN
                v_pp := v_pp - 'pendingCharge' - 'collectionBlocked';
                IF v_sp ? 'pendingCharge' THEN v_pp := v_pp || jsonb_build_object('pendingCharge', v_sp->'pendingCharge'); END IF;
                IF v_sp ? 'collectionBlocked' THEN v_pp := v_pp || jsonb_build_object('collectionBlocked', v_sp->'collectionBlocked'); END IF;
                IF COALESCE((v_sp->>'nextIndex')::int, 0) > COALESCE((v_pp->>'nextIndex')::int, 0) THEN
                    v_pp := jsonb_set(v_pp, '{nextIndex}', v_sp->'nextIndex', true);
                END IF;
                IF jsonb_typeof(v_sp->'history') = 'array'
                   AND jsonb_array_length(v_sp->'history') >
                       (CASE WHEN jsonb_typeof(v_pp->'history') = 'array' THEN jsonb_array_length(v_pp->'history') ELSE 0 END) THEN
                    v_pp := jsonb_set(v_pp, '{history}', v_sp->'history', true);
                END IF;
                -- old-style instalments: what the runner recorded on each one
                IF jsonb_typeof(v_pp->'installments') = 'array' AND jsonb_typeof(v_sp->'installments') = 'array' THEN
                    v_insts := '[]'::jsonb;
                    FOR i IN SELECT * FROM jsonb_array_elements(v_pp->'installments') LOOP
                        SELECT x INTO v_si FROM jsonb_array_elements(v_sp->'installments') x
                         WHERE x->>'dueDate' = i->>'dueDate' LIMIT 1;
                        IF v_si IS NOT NULL AND v_si->>'status' = 'paid' AND COALESCE(i->>'status', 'pending') <> 'paid' THEN
                            i := v_si;
                        ELSIF v_si IS NOT NULL AND COALESCE((v_si->>'attempts')::int, 0) > COALESCE((i->>'attempts')::int, 0) THEN
                            i := i || jsonb_strip_nulls(jsonb_build_object('attempts', v_si->'attempts',
                                     'failReason', v_si->'failReason', 'lastFailedAt', v_si->'lastFailedAt'));
                        END IF;
                        v_insts := v_insts || jsonb_build_array(i);
                    END LOOP;
                    v_pp := jsonb_set(v_pp, '{installments}', v_insts, true);
                END IF;
            END IF;
            v_plans := v_plans || jsonb_build_array(v_pp);
        END LOOP;
        v_out := jsonb_set(v_out, '{plans}', v_plans, true);
    END IF;

    RETURN v_out;
END;
$$;
$fn$;
    ELSE
        RAISE NOTICE '266: a newer _merge_family_from_page is in place — left as it is';
    END IF;
END $guard$;
REVOKE ALL ON FUNCTION public._merge_family_from_page(jsonb, jsonb) FROM public, anon, authenticated;


-- Both save paths merge instead of overwrite.
DO $$
DECLARE
    d text;
BEGIN
    -- 1. sync_camp_billing (213)
    d := pg_get_functiondef('public.sync_camp_billing(uuid,jsonb,jsonb,jsonb,jsonb)'::regprocedure);
    IF position('_merge_family_from_page' IN d) = 0 THEN
        IF position('PERFORM public.camp_family_save(p_camp_id, r.key, r.value);' IN d) = 0 THEN
            RAISE EXCEPTION '266: sync_camp_billing does not look the way this file expects — send this message to the builder';
        END IF;
        EXECUTE replace(d, 'PERFORM public.camp_family_save(p_camp_id, r.key, r.value);',
            'PERFORM public.camp_family_save(p_camp_id, r.key, public._merge_family_from_page((SELECT f.payload FROM public.camp_families f WHERE f.camp_id = p_camp_id AND f.family_key = r.key AND f.deleted_at IS NULL), r.value));');
    END IF;

    -- 2. the settings-document projection (234)
    d := pg_get_functiondef('public.project_camp_families()'::regprocedure);
    IF position('_merge_family_from_page' IN d) = 0 THEN
        IF position('payload    = EXCLUDED.payload,' IN d) = 0 THEN
            RAISE EXCEPTION '266: project_camp_families does not look the way this file expects — send this message to the builder';
        END IF;
        EXECUTE replace(d, 'payload    = EXCLUDED.payload,',
            'payload    = CASE WHEN camp_families.deleted_at IS NULL THEN public._merge_family_from_page(camp_families.payload, EXCLUDED.payload) ELSE EXCLUDED.payload END,');
    END IF;
END $$;


-- ▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼
-- 267_a_converted_charge_knows_its_charge.sql
-- ▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲

-- ============================================================================
-- Migration 267: a charge the ledger conversion posted knows which charge it is.
--
-- Standalone. Paste into the Supabase SQL Editor and click Run. Safe to run
-- more than once.
--
-- ── THE PROBLEM (TED-082) ──────────────────────────────────────────────────
-- The ledger conversion (171/215) copied each family's extra charges onto the
-- ledger as le_conv_<family>_<n> entries with nothing saying WHICH charge each
-- one was. 263's _sync_charge_to_ledger, and the Me page's catch-up, recognise
-- a charge's entries by source.chargeId, so for a charge billed before the
-- conversion they saw nothing posted:
--   * a $40 Camp Shop order re-priced to $55 posted another $55 — the family
--     owed $95;
--   * the same order cancelled took nothing off — the family still owed $40.
--
-- ── THE CHANGE ─────────────────────────────────────────────────────────────
-- 1. _link_converted_charges(family) stamps source.chargeId on each converted
--    fee entry, matching it to one charge of the same amount (the same date
--    first) — the matching the Me page already used (TED-065) — once, one to
--    one. A charge something already carries the id of is left alone.
-- 2. Every family is linked once, now.
-- 3. The conversion itself writes source.chargeId (and source.creditId on
--    credits) from now on, so a camp converting later needs no repair.
-- 4. A page saved from a tab that loaded before the link keeps the link
--    (_merge_family_from_page, 266).
-- 5. _sync_charge_to_ledger reads the clock, so it is STABLE, not IMMUTABLE
--    (TED-087).
-- ============================================================================

CREATE OR REPLACE FUNCTION public._link_converted_charges(p_fam jsonb)
RETURNS jsonb
LANGUAGE plpgsql
IMMUTABLE
SET search_path = public, pg_catalog
AS $$
DECLARE
    v_entries jsonb;
    v_charges jsonb;
    v_linked  text[];
    v_idx     integer;
    v_cents   bigint;
    v_changed boolean := false;
    c         jsonb;
BEGIN
    -- COALESCE: a missing key's type is NULL, and "NULL <> 'array'" is not true.
    IF p_fam IS NULL OR COALESCE(jsonb_typeof(p_fam), '') <> 'object'
       OR COALESCE(jsonb_typeof(p_fam->'entries'), '') <> 'array'
       OR COALESCE(jsonb_typeof(p_fam->'charges'), '') <> 'array' THEN
        RETURN p_fam;
    END IF;
    v_entries := p_fam->'entries';
    v_charges := p_fam->'charges';
    SELECT COALESCE(array_agg(DISTINCT x->'source'->>'chargeId'), '{}') INTO v_linked
      FROM jsonb_array_elements(v_entries) x
     WHERE COALESCE(x->'source'->>'chargeId', '') <> '';

    FOR c IN SELECT * FROM jsonb_array_elements(v_charges) LOOP
        IF COALESCE(c->>'id', '') = '' OR c->>'id' = ANY (v_linked) THEN CONTINUE; END IF;
        v_cents := ROUND(COALESCE((c->>'amount')::numeric, 0) * 100);
        IF v_cents <= 0 THEN CONTINUE; END IF;
        -- an unlinked converted fee of the same amount: the same date first
        SELECT o - 1 INTO v_idx
          FROM jsonb_array_elements(v_entries) WITH ORDINALITY AS t(x, o)
         WHERE x->>'id' LIKE 'le\_conv\_%' AND x->>'kind' = 'charge' AND x->>'reason' = 'fee'
           AND COALESCE(x->'source'->>'chargeId', '') = ''
           AND ROUND(COALESCE((x->>'amount')::numeric, 0) * 100) = v_cents
         ORDER BY (COALESCE(x->>'date', '') = COALESCE(c->>'date', '')) DESC, o
         LIMIT 1;
        IF v_idx IS NULL THEN CONTINUE; END IF;
        v_entries := jsonb_set(v_entries, ARRAY[v_idx::text, 'source'],
            (CASE WHEN jsonb_typeof(v_entries->v_idx->'source') = 'object'
                  THEN v_entries->v_idx->'source' ELSE '{}'::jsonb END)
            || jsonb_build_object('chargeId', c->>'id'), true);
        v_linked := v_linked || (c->>'id');
        v_changed := true;
        v_idx := NULL;
    END LOOP;

    IF NOT v_changed THEN RETURN p_fam; END IF;
    RETURN jsonb_set(p_fam, '{entries}', v_entries, true);
END;
$$;
REVOKE ALL ON FUNCTION public._link_converted_charges(jsonb) FROM public, anon, authenticated;


-- 263's sync reads now(): STABLE (TED-087).
ALTER FUNCTION public._sync_charge_to_ledger(jsonb, text) STABLE;


-- The conversion writes the link itself from now on.
DO $$
DECLARE
    d     text := pg_get_functiondef('public.convert_family_ledgers(uuid,boolean)'::regprocedure);
    empty text := '''source'', ''{}''::jsonb';
    at    integer;
    rel   integer;
BEGIN
    IF position('chargeId'', e->>''id''' IN d) > 0 THEN
        RAISE NOTICE '267: convert_family_ledgers already links its charges';
        RETURN;
    END IF;
    at := position('''reason'', ''fee'',' IN d);
    rel := CASE WHEN at > 0 THEN position(empty IN substr(d, at)) ELSE 0 END;
    IF rel = 0 THEN
        RAISE EXCEPTION '267: convert_family_ledgers does not look the way this file expects — send this message to the builder';
    END IF;
    d := overlay(d PLACING '''source'', jsonb_strip_nulls(jsonb_build_object(''chargeId'', e->>''id''))'
                 FROM at + rel - 1 FOR length(empty));
    at := position('''reason'', ''goodwill'',' IN d);
    rel := CASE WHEN at > 0 THEN position(empty IN substr(d, at)) ELSE 0 END;
    IF rel > 0 THEN
        d := overlay(d PLACING '''source'', jsonb_strip_nulls(jsonb_build_object(''creditId'', e->>''id''))'
                     FROM at + rel - 1 FOR length(empty));
    END IF;
    EXECUTE d;
END $$;


-- A save from a tab that loaded before the link keeps the link: an entry the
-- page and the server both hold is the page's, except that the server's
-- source.chargeId (which only this repair and the database ever add) stays.
CREATE OR REPLACE FUNCTION public._keep_charge_links(p_server jsonb, p_merged jsonb)
RETURNS jsonb
LANGUAGE plpgsql
IMMUTABLE
SET search_path = public, pg_catalog
AS $$
DECLARE
    v_out jsonb := '[]'::jsonb;
    v_cid text;
    e     jsonb;
BEGIN
    IF p_server IS NULL OR p_merged IS NULL
       OR COALESCE(jsonb_typeof(p_server->'entries'), '') <> 'array'
       OR COALESCE(jsonb_typeof(p_merged->'entries'), '') <> 'array' THEN
        RETURN p_merged;
    END IF;
    FOR e IN SELECT * FROM jsonb_array_elements(p_merged->'entries') LOOP
        IF COALESCE(e->'source'->>'chargeId', '') = '' AND COALESCE(e->>'id', '') <> '' THEN
            SELECT x->'source'->>'chargeId' INTO v_cid
              FROM jsonb_array_elements(p_server->'entries') x
             WHERE x->>'id' = e->>'id' AND COALESCE(x->'source'->>'chargeId', '') <> ''
             LIMIT 1;
            IF v_cid IS NOT NULL THEN
                e := jsonb_set(e, '{source}',
                    (CASE WHEN jsonb_typeof(e->'source') = 'object' THEN e->'source' ELSE '{}'::jsonb END)
                    || jsonb_build_object('chargeId', v_cid), true);
            END IF;
            v_cid := NULL;
        END IF;
        v_out := v_out || jsonb_build_array(e);
    END LOOP;
    RETURN jsonb_set(p_merged, '{entries}', v_out, true);
END;
$$;
REVOKE ALL ON FUNCTION public._keep_charge_links(jsonb, jsonb) FROM public, anon, authenticated;

DO $$
DECLARE
    d   text := pg_get_functiondef('public._merge_family_from_page(jsonb,jsonb)'::regprocedure);
    old text := '    RETURN v_out;' || chr(10) || 'END;';
BEGIN
    IF position('_keep_charge_links' IN d) > 0 THEN
        RAISE NOTICE '267: _merge_family_from_page already keeps charge links';
        RETURN;
    END IF;
    IF position(old IN d) = 0 THEN
        RAISE EXCEPTION '267: _merge_family_from_page does not look the way this file expects (run 266 first) — send this message to the builder';
    END IF;
    EXECUTE replace(d, old, '    RETURN public._keep_charge_links(p_server, v_out);' || chr(10) || 'END;');
END $$;


-- Every family, once.
DO $$
DECLARE
    r     record;
    v_new jsonb;
BEGIN
    FOR r IN SELECT camp_id, family_key, payload FROM public.camp_families
              WHERE deleted_at IS NULL
                AND jsonb_typeof(payload->'entries') = 'array'
                AND jsonb_typeof(payload->'charges') = 'array' LOOP
        v_new := public._link_converted_charges(r.payload);
        IF v_new IS DISTINCT FROM r.payload THEN
            v_new := public._link_converted_charges(public.camp_family_for_update(r.camp_id, r.family_key));
            PERFORM public.camp_family_save(r.camp_id, r.family_key, v_new);
        END IF;
    END LOOP;
END $$;


-- ▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼
-- 268_a_cut_off_charge_can_be_tried_again.sql
-- ▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲

-- ============================================================================
-- Migration 268: a card charge that was cut off can be tried again — safely.
--
-- Standalone. Paste into the Supabase SQL Editor and click Run. Safe to run
-- more than once. Run it BEFORE redeploying registration-deposit-checkout.
--
-- ── THE PROBLEM (TED-083, TED-085, TED-086) ────────────────────────────────
-- 1. The registration deposit takes a claim (198's refund_intents) before it
--    charges, so an office click and a parent's retry cannot both charge. If
--    the connection to the processor dropped mid-charge, the claim was never
--    given back and never expired, and a claim somebody else held was answered
--    "already paid". The parent was told "This deposit is already paid" for
--    ever while nothing had been charged.
-- 2. After a decline, a retry sent Stripe the same Idempotency-Key, and Stripe
--    replays a key's first answer — the decline — for 24 hours.
-- 3. processor_transactions only accepted kind 'charge' / 'refund', so the
--    card-charged registration deposits (and card checks) were never recorded.
--
-- ── THE CHANGE ─────────────────────────────────────────────────────────────
-- Charge claims (same table, new columns) know three more things:
--   * called_at — when the processor was actually asked. A claim abandoned
--     BEFORE that (the function died first) surely moved no money, so after
--     10 minutes the next try simply takes it over.
--   * released_at — a claim given back after a decline (or an error before
--     the processor was reached) is reopened, not deleted, so it keeps…
--   * attempt — bumped on every decline. It goes into the Stripe
--     Idempotency-Key, so a retry after a decline is a new request, while a
--     retry after a dropped connection is the SAME request (Stripe then tells
--     us what really happened instead of charging again).
-- claim_charge_intent answers one of: claimed (go ahead, with the attempt
-- number) · settled (really paid) · in_progress (someone is charging right
-- now) · stale (the processor was asked, never answered, 10+ minutes ago —
-- whether money moved is unknown; the caller decides: Stripe re-asks with the
-- same key, the office may confirm nothing went through).
-- 198's refund functions are untouched.
-- ============================================================================

ALTER TABLE public.refund_intents ADD COLUMN IF NOT EXISTS attempt     integer NOT NULL DEFAULT 0;
ALTER TABLE public.refund_intents ADD COLUMN IF NOT EXISTS called_at   timestamptz;
ALTER TABLE public.refund_intents ADD COLUMN IF NOT EXISTS released_at timestamptz;

CREATE OR REPLACE FUNCTION public.claim_charge_intent(
    p_camp_id      uuid,
    p_key          text,
    p_amount       numeric DEFAULT NULL,
    p_payment_ref  text    DEFAULT NULL,
    p_take_stale   boolean DEFAULT false
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
DECLARE
    v_key text := NULLIF(btrim(COALESCE(p_key, '')), '');
    r     record;
BEGIN
    IF p_camp_id IS NULL OR v_key IS NULL THEN
        RETURN jsonb_build_object('claimed', false, 'state', 'no_key');
    END IF;

    INSERT INTO refund_intents (camp_id, key, amount, payment_ref)
    VALUES (p_camp_id, v_key, p_amount, NULLIF(btrim(COALESCE(p_payment_ref, '')), ''))
    ON CONFLICT (camp_id, key) DO NOTHING;
    IF FOUND THEN
        RETURN jsonb_build_object('claimed', true, 'state', 'new', 'attempt', 0);
    END IF;

    SELECT * INTO r FROM refund_intents WHERE camp_id = p_camp_id AND key = v_key FOR UPDATE;

    IF r.settled_at IS NOT NULL THEN
        RETURN jsonb_build_object('claimed', false, 'state', 'settled',
                                  'previous', COALESCE(r.result, '{}'::jsonb));
    END IF;

    IF r.released_at IS NOT NULL                                               -- given back
       OR (r.called_at IS NULL AND r.created_at < now() - interval '10 minutes')  -- died before asking
       OR (p_take_stale AND r.called_at IS NOT NULL
           AND r.called_at < now() - interval '10 minutes') THEN               -- caller will re-ask
        -- A stale claim that is taken over counts as asked NOW (TED-092): a
        -- second caller in the next 10 minutes sees "in progress" and charges
        -- nothing, instead of taking it over as well.
        UPDATE refund_intents
           SET released_at = NULL, created_at = now(),
               called_at = CASE WHEN r.released_at IS NULL AND r.called_at IS NOT NULL THEN now() END,
               amount = COALESCE(p_amount, amount)
         WHERE camp_id = p_camp_id AND key = v_key;
        RETURN jsonb_build_object('claimed', true, 'state', 'retaken', 'attempt', r.attempt,
                                  'wasCalled', r.released_at IS NULL AND r.called_at IS NOT NULL);
    END IF;

    IF r.called_at IS NOT NULL AND r.called_at < now() - interval '10 minutes' THEN
        -- Tell the office, once per stuck charge (TED-092): the parent has been
        -- told the office will confirm it, so the office has to know.
        IF to_regclass('public.notifications') IS NOT NULL THEN
            INSERT INTO notifications (camp_id, source, source_id, title, body, link_target)
            VALUES (p_camp_id, 'charge_unconfirmed', v_key || ':' || to_char(r.called_at, 'YYYYMMDDHH24MISS'),
                    'A card charge needs checking',
                    'A charge (' || COALESCE(r.payment_ref, v_key) || ', $' || COALESCE(r.amount::text, '?')
                      || ') was sent to the card company and never answered. Check the processor''s dashboard, then use "Charge deposit now" in Me → Registration to confirm.',
                    'campistry_me.html')
            ON CONFLICT (camp_id, source, source_id) DO NOTHING;
        END IF;
        RETURN jsonb_build_object('claimed', false, 'state', 'stale', 'attempt', r.attempt,
                                  'since', r.called_at);
    END IF;

    RETURN jsonb_build_object('claimed', false, 'state', 'in_progress', 'attempt', r.attempt);
END $$;

/** The processor is about to be asked: from here on, an abandoned claim may have moved money. */
CREATE OR REPLACE FUNCTION public.mark_charge_intent_called(p_camp_id uuid, p_key text)
RETURNS boolean
LANGUAGE sql
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
    UPDATE refund_intents SET called_at = now()
     WHERE camp_id = p_camp_id AND key = NULLIF(btrim(COALESCE(p_key, '')), '') AND settled_at IS NULL
    RETURNING true;
$$;

/**
 * Give a charge claim back. p_declined: the processor said no, so the next try
 * is a new attempt (a new Idempotency-Key). Otherwise (nothing was sent, or
 * Stripe's answer was lost) the next try repeats this attempt. Never touches a
 * settled claim.
 */
CREATE OR REPLACE FUNCTION public.release_charge_intent(p_camp_id uuid, p_key text, p_declined boolean DEFAULT false)
RETURNS boolean
LANGUAGE sql
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
    UPDATE refund_intents
       SET released_at = now(), called_at = NULL,
           attempt = attempt + CASE WHEN p_declined THEN 1 ELSE 0 END
     WHERE camp_id = p_camp_id AND key = NULLIF(btrim(COALESCE(p_key, '')), '') AND settled_at IS NULL
    RETURNING true;
$$;

REVOKE ALL ON FUNCTION public.claim_charge_intent(uuid, text, numeric, text, boolean) FROM public, anon, authenticated;
REVOKE ALL ON FUNCTION public.mark_charge_intent_called(uuid, text) FROM public, anon, authenticated;
REVOKE ALL ON FUNCTION public.release_charge_intent(uuid, text, boolean) FROM public, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.claim_charge_intent(uuid, text, numeric, text, boolean) TO service_role;
GRANT EXECUTE ON FUNCTION public.mark_charge_intent_called(uuid, text) TO service_role;
GRANT EXECUTE ON FUNCTION public.release_charge_intent(uuid, text, boolean) TO service_role;


-- TED-086: every kind the functions record is accepted. (The reconciliation
-- report still counts kind 'charge' only; the others are now on record.)
DO $$
DECLARE c text;
BEGIN
    FOR c IN SELECT conname FROM pg_constraint
              WHERE conrelid = 'public.processor_transactions'::regclass AND contype = 'c'
                AND pg_get_constraintdef(oid) ~ 'kind' LOOP
        EXECUTE format('ALTER TABLE public.processor_transactions DROP CONSTRAINT %I', c);
    END LOOP;
    ALTER TABLE public.processor_transactions DROP CONSTRAINT IF EXISTS processor_transactions_kind_check;
    ALTER TABLE public.processor_transactions
        ADD CONSTRAINT processor_transactions_kind_check CHECK (kind ~ '^[a-z][a-z_]{0,39}$');
END $$;


-- ▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼
-- 269_every_plan_can_hold_a_bank_debit.sql
-- ▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲

-- ============================================================================
-- Migration 269: every kind of payment plan can hold a bank debit (and be
-- flagged), not only plans with an id.
--
-- Standalone. Paste into the Supabase SQL Editor and click Run. Safe to run
-- more than once. Run it BEFORE redeploying charge-due-installments.
--
-- ── THE PROBLEM (TED-084) ──────────────────────────────────────────────────
-- 262 holds a bank debit that is still clearing ON THE PLAN, so the nightly
-- runner asks Stripe about it instead of debiting again. It found the plan by
-- id, in plans[] only. A plan from before plans had ids, or a family still on
-- the single old-style `plan`, was never found: nothing was held, the runner
-- reported "processing_held" anyway, and the family was debited $500 again
-- every night. The decline/no-card flag (flag_plan_collection) had the same
-- blind spot, and so did the protection 266 gives the hold against an office
-- tab that loaded before it.
--
-- ── THE CHANGE ─────────────────────────────────────────────────────────────
-- A plan is named by its id, or — when it has none — by '#<position>', the
-- position the runner already uses for record_autopay_installment ('#0' is the
-- old single `plan`). _plan_path(family, ref) finds it; a position is only
-- accepted for a plan that has no id, so a list that changed underneath cannot
-- send a hold to the wrong plan. hold_autopay_charge and flag_plan_collection
-- use it, and the page-save merge keeps the running state (hold, block,
-- counter, history, paid instalments) on those plans too.
-- ============================================================================

CREATE OR REPLACE FUNCTION public._plan_path(p_fam jsonb, p_ref text)
RETURNS text[]
LANGUAGE plpgsql
IMMUTABLE
SET search_path = public, pg_catalog
AS $$
DECLARE
    v_plans jsonb;
    v_i     integer;
    i       integer;
BEGIN
    IF p_fam IS NULL OR COALESCE(p_ref, '') = '' THEN RETURN NULL; END IF;
    IF jsonb_typeof(p_fam->'plans') = 'array' THEN
        v_plans := p_fam->'plans';
        IF p_ref ~ '^#[0-9]{1,6}$' THEN
            v_i := substr(p_ref, 2)::integer;
            IF v_i < jsonb_array_length(v_plans)
               AND jsonb_typeof(v_plans->v_i) = 'object'
               AND COALESCE(v_plans->v_i->>'id', '') = '' THEN
                RETURN ARRAY['plans', v_i::text];
            END IF;
            RETURN NULL;
        END IF;
        FOR i IN 0 .. jsonb_array_length(v_plans) - 1 LOOP
            IF v_plans->i->>'id' = p_ref THEN RETURN ARRAY['plans', i::text]; END IF;
        END LOOP;
        RETURN NULL;
    END IF;
    -- the old single plan
    IF jsonb_typeof(p_fam->'plan') = 'object'
       AND (p_ref = '#0' OR p_fam->'plan'->>'id' = p_ref) THEN
        RETURN ARRAY['plan'];
    END IF;
    RETURN NULL;
END;
$$;
REVOKE ALL ON FUNCTION public._plan_path(jsonb, text) FROM public, anon, authenticated;


-- 262's hold, on any plan.
CREATE OR REPLACE FUNCTION public.hold_autopay_charge(
    p_camp_id    uuid,
    p_family_key text,
    p_plan_id    text,
    p_hold       jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
DECLARE
    v_fam  jsonb;
    v_path text[];
    v_plan jsonb;
BEGIN
    IF p_camp_id IS NULL OR COALESCE(p_family_key, '') = '' OR COALESCE(p_plan_id, '') = '' THEN
        RETURN jsonb_build_object('success', false, 'error', 'bad_arguments');
    END IF;
    v_fam := public.camp_family_for_update(p_camp_id, p_family_key);
    IF v_fam IS NULL OR jsonb_typeof(v_fam) <> 'object' THEN
        RETURN jsonb_build_object('success', false, 'error', 'family_not_found');
    END IF;
    v_path := public._plan_path(v_fam, p_plan_id);
    IF v_path IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'plan_not_found');
    END IF;
    v_plan := v_fam #> v_path;
    IF p_hold IS NULL OR jsonb_typeof(p_hold) <> 'object' THEN
        v_plan := v_plan - 'pendingCharge';
    ELSE
        v_plan := jsonb_set(v_plan, '{pendingCharge}', p_hold, true);
    END IF;
    PERFORM public.camp_family_save(p_camp_id, p_family_key, jsonb_set(v_fam, v_path, v_plan, true));
    RETURN jsonb_build_object('success', true);
END;
$$;
REVOKE ALL ON FUNCTION public.hold_autopay_charge(uuid, text, text, jsonb) FROM public, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.hold_autopay_charge(uuid, text, text, jsonb) TO service_role;


-- flag_plan_collection (214), on any plan: the lookup and the write-back.
DO $$
DECLARE
    d  text := pg_get_functiondef('public.flag_plan_collection(uuid,text,text,text,text)'::regprocedure);
    o1 text := $o$    v_plans := CASE WHEN jsonb_typeof(v_fam->'plans') = 'array'
                    THEN v_fam->'plans' ELSE '[]'::jsonb END;
    FOR i IN 0 .. GREATEST(jsonb_array_length(v_plans) - 1, -1) LOOP
        IF v_plans->i->>'id' = p_plan_id THEN v_pi := i; EXIT; END IF;
    END LOOP;
    IF v_pi IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'plan_not_found');
    END IF;
    v_plan := v_plans->v_pi;$o$;
    n1 text := $n$    IF public._plan_path(v_fam, p_plan_id) IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'plan_not_found');
    END IF;
    v_plan := v_fam #> public._plan_path(v_fam, p_plan_id);$n$;
    o2 text := $o$    v_plans := jsonb_set(v_plans, ARRAY[v_pi::text], v_plan, true);
    v_fam := jsonb_set(v_fam, '{plans}', v_plans, true);$o$;
    n2 text := $n$    v_fam := jsonb_set(v_fam, public._plan_path(v_fam, p_plan_id), v_plan, true);$n$;
    o3 text := $o$                       WHEN 'no_processor' THEN 'the camp''s payment processor is not connected'$o$;
    n3 text := $n$                       WHEN 'no_processor' THEN 'the camp''s payment processor is not connected'
                       WHEN 'bank_debit_unheld' THEN 'a bank debit is clearing but could not be recorded on their plan, so it may be debited again'
                       WHEN 'bank_debit_stuck' THEN 'a bank debit has not cleared for over ten days'
                       WHEN 'bank_debit_unverified' THEN 'a bank debit from an earlier night cannot be checked with Stripe'
                       WHEN 'deposit_review' THEN 'autopay is waiting for you to answer a question about their card deposit'$n$;
BEGIN
    IF position('_plan_path' IN d) > 0 THEN
        RAISE NOTICE '269: flag_plan_collection already finds every plan';
        RETURN;
    END IF;
    IF position(o1 IN d) = 0 OR position(o2 IN d) = 0 OR position(o3 IN d) = 0 THEN
        RAISE EXCEPTION '269: flag_plan_collection does not look the way this file expects — send this message to the builder';
    END IF;
    EXECUTE replace(replace(replace(d, o1, n1), o2, n2), o3, n3);
END $$;


-- The running state the server writes on a plan, kept over a page's copy of it.
CREATE OR REPLACE FUNCTION public._merge_plan_state(p_sp jsonb, p_pp jsonb)
RETURNS jsonb
LANGUAGE plpgsql
IMMUTABLE
SET search_path = public, pg_catalog
AS $$
DECLARE
    v_pp    jsonb := p_pp;
    v_insts jsonb;
    v_si    jsonb;
    i       jsonb;
BEGIN
    IF p_sp IS NULL OR jsonb_typeof(p_sp) <> 'object' OR p_pp IS NULL OR jsonb_typeof(p_pp) <> 'object' THEN
        RETURN p_pp;
    END IF;
    v_pp := v_pp - 'pendingCharge' - 'collectionBlocked';
    IF p_sp ? 'pendingCharge' THEN v_pp := v_pp || jsonb_build_object('pendingCharge', p_sp->'pendingCharge'); END IF;
    IF p_sp ? 'collectionBlocked' THEN v_pp := v_pp || jsonb_build_object('collectionBlocked', p_sp->'collectionBlocked'); END IF;
    IF COALESCE((p_sp->>'nextIndex')::int, 0) > COALESCE((v_pp->>'nextIndex')::int, 0) THEN
        v_pp := jsonb_set(v_pp, '{nextIndex}', p_sp->'nextIndex', true);
    END IF;
    IF jsonb_typeof(p_sp->'history') = 'array'
       AND jsonb_array_length(p_sp->'history') >
           (CASE WHEN jsonb_typeof(v_pp->'history') = 'array' THEN jsonb_array_length(v_pp->'history') ELSE 0 END) THEN
        v_pp := jsonb_set(v_pp, '{history}', p_sp->'history', true);
    END IF;
    IF jsonb_typeof(v_pp->'installments') = 'array' AND jsonb_typeof(p_sp->'installments') = 'array' THEN
        v_insts := '[]'::jsonb;
        FOR i IN SELECT * FROM jsonb_array_elements(v_pp->'installments') LOOP
            SELECT x INTO v_si FROM jsonb_array_elements(p_sp->'installments') x
             WHERE x->>'dueDate' = i->>'dueDate' LIMIT 1;
            IF v_si IS NOT NULL AND v_si->>'status' = 'paid' AND COALESCE(i->>'status', 'pending') <> 'paid' THEN
                i := v_si;
            ELSIF v_si IS NOT NULL AND COALESCE((v_si->>'attempts')::int, 0) > COALESCE((i->>'attempts')::int, 0) THEN
                i := i || jsonb_strip_nulls(jsonb_build_object('attempts', v_si->'attempts',
                         'failReason', v_si->'failReason', 'lastFailedAt', v_si->'lastFailedAt'));
            END IF;
            v_insts := v_insts || jsonb_build_array(i);
            v_si := NULL;
        END LOOP;
        v_pp := jsonb_set(v_pp, '{installments}', v_insts, true);
    END IF;
    RETURN v_pp;
END;
$$;
REVOKE ALL ON FUNCTION public._merge_plan_state(jsonb, jsonb) FROM public, anon, authenticated;


-- 266's merge, with plans matched by id OR (both without one) by position, and
-- the old single plan kept too. Entries and charge links as 266/267 had them.
-- Only when nothing newer is in place: re-running this file on its own must
-- not put back an older merge over a later migration's (TED-094).
DO $guard$
BEGIN
    IF to_regprocedure('public._merge_family_from_page(jsonb,jsonb)') IS NULL
       OR pg_get_functiondef(to_regprocedure('public._merge_family_from_page(jsonb,jsonb)')) !~ 'LIKE ''shop' THEN
        EXECUTE $fn$
CREATE OR REPLACE FUNCTION public._merge_family_from_page(p_server jsonb, p_page jsonb)
RETURNS jsonb
LANGUAGE plpgsql
IMMUTABLE
SET search_path = public, pg_catalog
AS $$
DECLARE
    v_out     jsonb := p_page;
    v_pe      jsonb;
    v_se      jsonb;
    v_ids     text[];
    v_plans   jsonb := '[]'::jsonb;
    v_sp      jsonb;
    p         jsonb;
    e         jsonb;
    n         integer := 0;
BEGIN
    IF p_server IS NULL OR jsonb_typeof(p_server) <> 'object'
       OR p_page IS NULL OR jsonb_typeof(p_page) <> 'object' THEN
        RETURN p_page;
    END IF;

    -- ── ledger entries: never lose one ───────────────────────────────────────
    v_pe := CASE WHEN jsonb_typeof(p_page->'entries') = 'array' THEN p_page->'entries' ELSE '[]'::jsonb END;
    v_se := CASE WHEN jsonb_typeof(p_server->'entries') = 'array' THEN p_server->'entries' ELSE '[]'::jsonb END;
    IF jsonb_array_length(v_se) > 0 THEN
        SELECT COALESCE(array_agg(x->>'id'), '{}') INTO v_ids FROM jsonb_array_elements(v_pe) x;
        FOR e IN SELECT * FROM jsonb_array_elements(v_se) LOOP
            IF COALESCE(e->>'id', '') <> '' AND NOT (e->>'id' = ANY (v_ids)) THEN
                v_pe := v_pe || jsonb_build_array(e);
            END IF;
        END LOOP;
        v_out := jsonb_set(v_out, '{entries}', v_pe, true);
    END IF;

    -- ── plans: the server's running state on every plan the page kept ───────
    IF jsonb_typeof(p_page->'plans') = 'array' AND jsonb_typeof(p_server->'plans') = 'array' THEN
        FOR p IN SELECT * FROM jsonb_array_elements(p_page->'plans') LOOP
            v_sp := NULL;
            IF COALESCE(p->>'id', '') <> '' THEN
                SELECT x INTO v_sp FROM jsonb_array_elements(p_server->'plans') x WHERE x->>'id' = p->>'id' LIMIT 1;
            ELSIF jsonb_typeof(p_server->'plans'->n) = 'object'
                  AND COALESCE(p_server->'plans'->n->>'id', '') = '' THEN
                v_sp := p_server->'plans'->n;                     -- no id on either: same position
            END IF;
            v_plans := v_plans || jsonb_build_array(public._merge_plan_state(v_sp, p));
            n := n + 1;
        END LOOP;
        v_out := jsonb_set(v_out, '{plans}', v_plans, true);
    END IF;

    -- ── the old single plan ──────────────────────────────────────────────────
    IF jsonb_typeof(p_page->'plan') = 'object' AND jsonb_typeof(p_server->'plan') = 'object' THEN
        v_out := jsonb_set(v_out, '{plan}', public._merge_plan_state(p_server->'plan', p_page->'plan'), true);
    END IF;

    RETURN public._keep_charge_links(p_server, v_out);
END;
$$;
$fn$;
    ELSE
        RAISE NOTICE '269: a newer _merge_family_from_page is in place — left as it is';
    END IF;
END $guard$;
REVOKE ALL ON FUNCTION public._merge_family_from_page(jsonb, jsonb) FROM public, anon, authenticated;


-- ▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼
-- 270_money_notices_for_billing_only.sql
-- ▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲

-- ============================================================================
-- Migration 270: money notices go only to people who can see Billing; a
-- retried tip knows the parent's payment.
--
-- Standalone. Paste into the Supabase SQL Editor and click Run. Safe to run
-- more than once.
--
-- ── THE PROBLEM (TED-087) ──────────────────────────────────────────────────
-- 1. The Dashboard shows the camp's notifications to every staff member who
--    can read them — schedulers included. "A card payment needs matching"
--    carries the amount and the masked card; "Autopay cannot collect", "card
--    expiring", chargebacks and payout failures name families and money. A
--    counselor with no Billing access saw all of it.
-- 2. The nightly retry of a failed tip transfer recorded the tip with no
--    parent payment id, so a dispute or refund looked up by payment missed
--    it — and the webhook's own duplicate check (by payment) could not see it.
--
-- ── THE CHANGE ─────────────────────────────────────────────────────────────
-- 1. The notifications read rule (098) is unchanged for everything else; the
--    money notices additionally need Billing (me.billing) at view or better,
--    decided by the same user_section_level the rest of the app's access uses.
-- 2. link_tip_cart_items.stripe_payment_intent_id: the webhook writes it on
--    every line of a paid cart, and the retry copies it onto the tip.
-- ============================================================================

-- ── 1. money notices ────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.is_money_notice(p_source text)
RETURNS boolean
LANGUAGE sql
IMMUTABLE
SET search_path = public, pg_catalog
AS $$
    SELECT COALESCE(p_source, '') IN (
        'payment_unmatched', 'autopay_blocked', 'chargeback', 'card_expiry',
        'parent_payment_plan_created', 'payout_failed', 'charge_unconfirmed',
        'canteen_autoreload_off', 'tip_transfer_failed', 'telnyx_fee_failed', 'autopay_setup');
$$;
GRANT EXECUTE ON FUNCTION public.is_money_notice(text) TO authenticated, service_role;

DROP POLICY IF EXISTS notifications_select ON notifications;
CREATE POLICY notifications_select ON notifications
    FOR SELECT
    USING (
        camp_id = get_user_camp_id()
        AND get_user_role() = ANY (ARRAY['owner'::text, 'admin'::text, 'manager'::text, 'scheduler'::text])
        AND (NOT public.is_money_notice(source)
             OR public.user_section_level(camp_id, 'me.billing') <> 'none')
    );

-- ── 2. a retried tip knows the parent's payment ─────────────────────────────
-- (Only where tip carts exist — migration 059.)
DO $$
BEGIN
    IF to_regclass('public.link_tip_cart_items') IS NOT NULL THEN
        ALTER TABLE public.link_tip_cart_items ADD COLUMN IF NOT EXISTS stripe_payment_intent_id text;
    END IF;
END $$;


-- ▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼
-- 271_parents_see_what_the_server_records.sql
-- ▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲

-- ============================================================================
-- Migration 271: parents see what the server records; money that arrived
-- early reaches the ledger; a deposit can be paid straight after applying.
--
-- Standalone. Paste into the Supabase SQL Editor and click Run. Safe to run
-- more than once. Run it BEFORE redeploying registration-deposit-checkout.
--
-- ── THE PROBLEMS ───────────────────────────────────────────────────────────
-- TED-088  A parent's balance in Link read the ledger from a copy
--          (family_ledger_projection) that only the office's save of the
--          settings document refreshes. Autopay, the payment webhooks, the shop
--          and bank deposits write the family's ROW (camp_families, 211/213) —
--          so after a $400 Zelle payment the office saw $600 and the parent
--          still saw $1,000, and "Pay now" offered the old figure.
-- TED-077  A family's ledger starts the first time Billing posts to it. A
--          Zelle payment or a recorded payment that arrived before then was
--          never added, so the ledger was short for good. And the parent-side
--          "is every payment on the ledger?" check read a list that has been
--          empty since payments moved out of the document (158), so it always
--          said yes.
-- TED-089  New applications live in camp_applications (200) until the office
--          opens Me. The deposit functions only looked in the settings
--          document, so paying the deposit on the form straight after applying
--          failed "We could not find that application".
-- TED-090  (with the Me page) A deposit charged by card is recorded on the
--          application; this also records which processor took it, so Billing
--          can turn it into a refundable payment on the family.
--
-- ── THE CHANGES ────────────────────────────────────────────────────────────
-- 1. projected_family_ledger reads the family's live row (the copy only when
--    there is no row); projected_family_payments reads the payment rows.
-- 2. When a family's ledger starts (its entries go from none to some), every
--    earlier payment and posted bank deposit for it is posted, once — by the
--    same sync_family_ledger_payments the office can run, which never posts
--    anything twice.
-- 3. The deposit functions find an application in the document OR in
--    camp_applications, and record on whichever holds it (both, when both do).
-- ============================================================================

-- ── 1. the parent reads the rows ───────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.projected_family_ledger(p_camp_id uuid, p_family_key text)
RETURNS jsonb
LANGUAGE sql
STABLE
SET search_path = public, pg_catalog
AS $$
    SELECT jsonb_build_object('entries', COALESCE(
        (SELECT CASE WHEN jsonb_typeof(f.payload->'entries') = 'array' THEN f.payload->'entries' ELSE '[]'::jsonb END
           FROM public.camp_families f
          WHERE f.camp_id = p_camp_id AND f.family_key = p_family_key AND f.deleted_at IS NULL),
        (SELECT entries FROM public.family_ledger_projection
          WHERE camp_id = p_camp_id AND family_key = p_family_key),
        '[]'::jsonb));
$$;
REVOKE ALL ON FUNCTION public.projected_family_ledger(uuid, text) FROM public, anon;
GRANT EXECUTE ON FUNCTION public.projected_family_ledger(uuid, text) TO authenticated, service_role;

CREATE OR REPLACE FUNCTION public.projected_family_payments(p_camp_id uuid, p_family_key text)
RETURNS jsonb
LANGUAGE sql
STABLE
SET search_path = public, pg_catalog
AS $$
    SELECT COALESCE(jsonb_agg(p.payload ORDER BY p.ordinal), '[]'::jsonb)
      FROM public.camp_payments p
     WHERE p.camp_id = p_camp_id AND p.deleted_at IS NULL
       AND COALESCE(p.payload->>'familyKey', '') = p_family_key;
$$;
REVOKE ALL ON FUNCTION public.projected_family_payments(uuid, text) FROM public, anon;
GRANT EXECUTE ON FUNCTION public.projected_family_payments(uuid, text) TO authenticated, service_role;


-- ── 2. a ledger that starts takes in the money that came before it ─────────
-- One family's catch-up, reading only that family (TED-099): the camp-wide
-- sync_family_ledger_payments rebuilt every family and every payment of the
-- camp for each family, so a first Billing save of 1,000 families took ~7.6 s.
-- Same entries, same ids, same "already on the ledger?" tests.
CREATE OR REPLACE FUNCTION public._catch_up_family_ledger(p_camp_id uuid, p_family_key text)
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
DECLARE
    now_ts    timestamptz := now();
    v_fam     jsonb;
    v_entries jsonb;
    v_entry   jsonb;
    v_n       integer := 0;
    e         jsonb;
    d         record;
BEGIN
    v_fam := public.camp_family_for_update(p_camp_id, p_family_key);
    IF v_fam IS NULL OR jsonb_typeof(v_fam) <> 'object' THEN RETURN 0; END IF;
    v_entries := CASE WHEN jsonb_typeof(v_fam->'entries') = 'array' THEN v_fam->'entries' ELSE '[]'::jsonb END;

    FOR e IN SELECT p.payload FROM public.camp_payments p
              WHERE p.camp_id = p_camp_id AND p.deleted_at IS NULL
                AND (p.family_key = p_family_key OR p.payload->>'familyKey' = p_family_key)
              ORDER BY p.ordinal LOOP
        IF COALESCE(e->>'familyKey', '') <> p_family_key THEN CONTINUE; END IF;
        IF public.family_covers_payment(jsonb_build_object('entries', v_entries), e) THEN CONTINUE; END IF;
        v_entry := public.payment_ledger_entry(e);
        IF v_entry IS NULL THEN CONTINUE; END IF;
        v_entries := v_entries || jsonb_build_array(v_entry);
        v_n := v_n + 1;
    END LOOP;

    FOR d IN SELECT id, amount_cents, is_reversal, to_char(created_at, 'YYYY-MM-DD') AS on_date
               FROM bank_deposits
              WHERE camp_id = p_camp_id AND status = 'posted' AND family_key = p_family_key LOOP
        IF public.family_covers_deposit(jsonb_build_object('entries', v_entries), d.id,
               ABS(d.amount_cents::numeric / 100), d.on_date) THEN
            CONTINUE;
        END IF;
        v_entries := v_entries || jsonb_build_array(jsonb_build_object(
            'id', 'le_dep_' || d.id::text,
            'kind', CASE WHEN d.is_reversal THEN 'refund' ELSE 'payment' END,
            'amount', ROUND(ABS(d.amount_cents::numeric / 100), 2),
            'reason', 'zelle', 'date', d.on_date,
            'postedAt', to_char(now_ts, 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
            'note', CASE WHEN d.is_reversal THEN 'Bank deposit reversed' ELSE 'Bank deposit' END,
            'by', 'system', 'source', jsonb_build_object('depositId', d.id::text)));
        v_n := v_n + 1;
    END LOOP;

    IF v_n > 0 THEN
        PERFORM public.camp_family_save(p_camp_id, p_family_key, jsonb_set(v_fam, '{entries}', v_entries, true));
    END IF;
    RETURN v_n;
END;
$$;
REVOKE ALL ON FUNCTION public._catch_up_family_ledger(uuid, text) FROM public, anon, authenticated;

CREATE OR REPLACE FUNCTION public._ledger_started_catch_up()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
BEGIN
    IF NEW.deleted_at IS NULL
       AND jsonb_typeof(NEW.payload->'entries') = 'array'
       AND jsonb_array_length(NEW.payload->'entries') > 0
       AND (TG_OP = 'INSERT'
            OR COALESCE(jsonb_typeof(OLD.payload->'entries'), '') <> 'array'
            OR jsonb_array_length(OLD.payload->'entries') = 0
            OR OLD.deleted_at IS NOT NULL)
       THEN
        PERFORM public._catch_up_family_ledger(NEW.camp_id, NEW.family_key);
    END IF;
    RETURN NULL;
END;
$$;
REVOKE ALL ON FUNCTION public._ledger_started_catch_up() FROM public, anon, authenticated;

DROP TRIGGER IF EXISTS trg_ledger_started_catch_up ON public.camp_families;
CREATE TRIGGER trg_ledger_started_catch_up
AFTER INSERT OR UPDATE OF payload, deleted_at ON public.camp_families
FOR EACH ROW EXECUTE FUNCTION public._ledger_started_catch_up();

-- Families whose ledger already started short: once, now.
DO $$
DECLARE r record;
BEGIN
    FOR r IN SELECT DISTINCT f.camp_id FROM public.camp_families f
              WHERE f.deleted_at IS NULL AND jsonb_typeof(f.payload->'entries') = 'array'
                AND jsonb_array_length(f.payload->'entries') > 0
                AND EXISTS (SELECT 1 FROM camp_state_kv k WHERE k.camp_id = f.camp_id AND k.key = 'campistryMe') LOOP
        PERFORM public.sync_family_ledger_payments(r.camp_id, NULL, false);
    END LOOP;
END $$;


-- ── 3. an application is wherever it is ────────────────────────────────────
-- How many card deposit charges an application copy records (NULL-safe).
CREATE OR REPLACE FUNCTION public._deposit_charge_count(p_enr jsonb)
RETURNS integer
LANGUAGE sql
IMMUTABLE
SET search_path = public, pg_catalog
AS $$
    SELECT CASE WHEN jsonb_typeof(p_enr->'depositCharges') = 'array' THEN jsonb_array_length(p_enr->'depositCharges')
                WHEN COALESCE(p_enr->>'depositReference', '') <> '' THEN 1 ELSE 0 END;
$$;

CREATE OR REPLACE FUNCTION public._application_entry(p_camp_id uuid, p_enroll_id text)
RETURNS jsonb
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
    -- Both copies can exist. The one holding MORE card deposit charges wins
    -- (TED-098): an office tab that absorbed the application before the parent
    -- paid saves the document copy without the payment, and must not make the
    -- deposit read unpaid again. Otherwise the office's copy, as before.
    WITH d AS (SELECT value #> ARRAY['enrollments', p_enroll_id] AS e FROM camp_state_kv
                WHERE camp_id = p_camp_id AND key = 'campistryMe'),
         a AS (SELECT payload AS e FROM camp_applications
                WHERE camp_id = p_camp_id AND kind = 'enrollments' AND entry_id = p_enroll_id)
    SELECT CASE
        WHEN (SELECT e FROM a) IS NOT NULL
             AND public._deposit_charge_count((SELECT e FROM a)) > public._deposit_charge_count((SELECT e FROM d))
            THEN (SELECT e FROM a)
        ELSE COALESCE((SELECT e FROM d), (SELECT e FROM a)) END;
$$;
REVOKE ALL ON FUNCTION public._application_entry(uuid, text) FROM public, anon, authenticated;

-- Sets the given fields on the application, in place, wherever it is held.
CREATE OR REPLACE FUNCTION public._application_patch(p_camp_id uuid, p_enroll_id text, p_patch jsonb)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
DECLARE
    v_any boolean := false;
BEGIN
    UPDATE camp_state_kv
       SET value = jsonb_set(value, ARRAY['enrollments', p_enroll_id],
                             (value #> ARRAY['enrollments', p_enroll_id]) || p_patch, false),
           updated_at = now()
     WHERE camp_id = p_camp_id AND key = 'campistryMe'
       AND jsonb_typeof(value #> ARRAY['enrollments', p_enroll_id]) = 'object';
    v_any := FOUND;
    UPDATE camp_applications
       SET payload = payload || p_patch, updated_at = now()
     WHERE camp_id = p_camp_id AND kind = 'enrollments' AND entry_id = p_enroll_id;
    RETURN v_any OR FOUND;
END;
$$;
REVOKE ALL ON FUNCTION public._application_patch(uuid, text, jsonb) FROM public, anon, authenticated;

-- Every card deposit charge the document copy and the camp_applications copy
-- record, once each (by reference).
CREATE OR REPLACE FUNCTION public._deposit_charges_union(p_camp_id uuid, p_enroll_id text)
RETURNS jsonb
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
    SELECT COALESCE(jsonb_agg(c ORDER BY first_seen), '[]'::jsonb) FROM (
        SELECT DISTINCT ON (c->>'ref') c, ord AS first_seen
          FROM (
            SELECT x.c, x.o AS ord FROM camp_state_kv k,
                   jsonb_array_elements(CASE WHEN jsonb_typeof(k.value #> ARRAY['enrollments', p_enroll_id, 'depositCharges']) = 'array'
                                             THEN k.value #> ARRAY['enrollments', p_enroll_id, 'depositCharges'] ELSE '[]'::jsonb END)
                   WITH ORDINALITY AS x(c, o)
             WHERE k.camp_id = p_camp_id AND k.key = 'campistryMe'
            UNION ALL
            SELECT x.c, 1000 + x.o FROM camp_applications ap,
                   jsonb_array_elements(CASE WHEN jsonb_typeof(ap.payload->'depositCharges') = 'array'
                                             THEN ap.payload->'depositCharges' ELSE '[]'::jsonb END)
                   WITH ORDINALITY AS x(c, o)
             WHERE ap.camp_id = p_camp_id AND ap.kind = 'enrollments' AND ap.entry_id = p_enroll_id
          ) u
         WHERE COALESCE(c->>'ref', '') <> ''
         ORDER BY c->>'ref', ord
    ) q;
$$;
REVOKE ALL ON FUNCTION public._deposit_charges_union(uuid, text) FROM public, anon, authenticated;

-- 190's, reading either place.
CREATE OR REPLACE FUNCTION public._registration_deposit_owed(
    p_camp_id   uuid,
    p_enroll_id text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
DECLARE
    v_enr    jsonb;
    v_req    numeric;
    v_paid   numeric;
BEGIN
    v_enr := public._application_entry(p_camp_id, p_enroll_id);
    IF v_enr IS NULL OR jsonb_typeof(v_enr) <> 'object' THEN
        RETURN jsonb_build_object('success', false, 'error', 'application_not_found');
    END IF;
    -- On the waitlist: there is no place to hold, so there is nothing to pay for.
    IF COALESCE(v_enr->>'status', '') = 'waitlisted' THEN
        RETURN jsonb_build_object('success', true, 'owed', 0, 'required', 0, 'paid', 0,
                                  'reason', 'waitlisted');
    END IF;
    v_req  := COALESCE(NULLIF(v_enr->>'depositRequired', '')::numeric, 0);
    v_paid := COALESCE(NULLIF(v_enr->>'depositPaid', '')::numeric, 0);
    RETURN jsonb_build_object('success', true, 'required', v_req, 'paid', v_paid,
                              'owed', greatest(0, v_req - v_paid),
                              'camperName', v_enr->>'camperName');
END;
$$;
REVOKE ALL ON FUNCTION public._registration_deposit_owed(uuid, text) FROM public, anon, authenticated;
GRANT EXECUTE ON FUNCTION public._registration_deposit_owed(uuid, text) TO service_role;

-- 185's, recording on either place, and which processor took it (TED-090).
CREATE OR REPLACE FUNCTION public._record_registration_deposit(
    p_camp_id   uuid,
    p_enroll_id text,
    p_amount    numeric,
    p_reference text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
DECLARE
    v_enr  jsonb;
    v_paid numeric;
    v_proc text;
BEGIN
    v_enr := public._application_entry(p_camp_id, p_enroll_id);
    IF v_enr IS NULL OR jsonb_typeof(v_enr) <> 'object' THEN
        RETURN jsonb_build_object('success', false, 'error', 'application_not_found');
    END IF;
    IF p_reference <> '' AND (COALESCE(v_enr->>'depositReference', '') = p_reference
       OR EXISTS (SELECT 1 FROM jsonb_array_elements(CASE WHEN jsonb_typeof(v_enr->'depositCharges') = 'array'
                                                          THEN v_enr->'depositCharges' ELSE '[]'::jsonb END) x
                   WHERE x->>'ref' = p_reference)) THEN
        RETURN jsonb_build_object('success', true, 'duplicate', true);
    END IF;
    v_paid := GREATEST(COALESCE(NULLIF(v_enr->>'depositPaid', '')::numeric, 0),
                       (SELECT COALESCE(sum((c->>'amount')::numeric), 0)
                          FROM jsonb_array_elements(public._deposit_charges_union(p_camp_id, p_enroll_id)) c))
              + GREATEST(p_amount, 0);
    SELECT CASE WHEN p_reference LIKE 'pi\_%' THEN 'stripe'
                ELSE COALESCE(NULLIF(c.payment_processor_key, ''), 'stripe') END
      INTO v_proc FROM camps c WHERE c.id = p_camp_id;
    PERFORM public._application_patch(p_camp_id, p_enroll_id, jsonb_build_object(
        'depositPaid', v_paid,
        'depositPaidDate', to_char(now(), 'YYYY-MM-DD'),
        'depositReference', p_reference,
        'depositProcessor', COALESCE(v_proc, ''),
        'depositStatus', 'paid',
        -- Each card charge, so Billing can make each one a refundable payment
        -- on the family, once (TED-090).
        -- every charge either copy knows of, never a shorter list (TED-098)
        'depositCharges', public._deposit_charges_union(p_camp_id, p_enroll_id)
                          || jsonb_build_array(jsonb_build_object(
                               'ref', p_reference, 'amount', ROUND(GREATEST(p_amount, 0), 2),
                               'date', to_char(now(), 'YYYY-MM-DD'), 'processor', COALESCE(v_proc, '')))));
    RETURN jsonb_build_object('success', true, 'paid', v_paid);
END;
$$;
REVOKE ALL ON FUNCTION public._record_registration_deposit(uuid, text, numeric, text) FROM public, anon, authenticated;
GRANT EXECUTE ON FUNCTION public._record_registration_deposit(uuid, text, numeric, text) TO service_role;

-- 186's, recording on either place.
CREATE OR REPLACE FUNCTION public._record_registration_card(
    p_camp_id    uuid,
    p_enroll_id  text,
    p_processor  text,
    p_customer   text,
    p_method     text,
    p_last4      text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
BEGIN
    IF NOT public._application_patch(p_camp_id, p_enroll_id, jsonb_build_object(
        'savedCardProcessor', COALESCE(p_processor, ''),
        'savedCardCustomer',  COALESCE(p_customer, ''),
        'savedCardMethod',    COALESCE(p_method, ''),
        'savedCardLast4',     COALESCE(p_last4, ''))) THEN
        RETURN jsonb_build_object('success', false, 'error', 'application_not_found');
    END IF;
    RETURN jsonb_build_object('success', true);
END;
$$;
REVOKE ALL ON FUNCTION public._record_registration_card(uuid, text, text, text, text, text)
    FROM public, anon, authenticated;
GRANT EXECUTE ON FUNCTION public._record_registration_card(uuid, text, text, text, text, text)
    TO service_role;

NOTIFY pgrst, 'reload schema';


-- ▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼
-- 272_an_old_tab_keeps_the_shops_charges.sql
-- ▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲

-- ============================================================================
-- Migration 272: a Billing tab left open keeps the shop's charges.
--
-- Standalone. Paste into the Supabase SQL Editor and click Run. Safe to run
-- more than once. Requires 266, 267 and 269.
--
-- ── THE PROBLEM (TED-091) ──────────────────────────────────────────────────
-- The shop bills a $40 sweatshirt to a family at lunch. An office tab opened
-- that morning adds a $10 charge and saves the family as it knew it — without
-- the sweatshirt. 266's merge kept the ledger lines and the plans but took the
-- page's list of charges as it was, so the $40 charge vanished; the next
-- Billing load then saw a posted charge with nothing behind it and took it off
-- the ledger ("Cancelled — charge"). The family owed $1,010, not $1,050.
--
-- ── THE CHANGE ─────────────────────────────────────────────────────────────
-- _merge_family_from_page (as 269 left it) also merges the charges: the page's
-- own, plus every charge the server holds that the page never saw; and the
-- shop's charges (shop_<order>) always exactly as the server has them, since
-- only the server bills, re-prices and cancels them. (The Me page, for its
-- part, no longer takes a shop charge off the ledger itself.)
-- ============================================================================

-- What an id-less plan is: when it was made and its schedule.
CREATE OR REPLACE FUNCTION public._plan_fingerprint(p jsonb)
RETURNS text
LANGUAGE sql
IMMUTABLE
SET search_path = public, pg_catalog
AS $$
    SELECT COALESCE(p->>'createdAt', '') || '|' ||
           COALESCE(CASE WHEN jsonb_typeof(p->'dueDates') = 'array' THEN (p->'dueDates')::text END, '') || '|' ||
           COALESCE((SELECT string_agg(COALESCE(i->>'dueDate', '') || ':' || COALESCE(i->>'amount', ''), ',' ORDER BY o)
                       FROM jsonb_array_elements(CASE WHEN jsonb_typeof(p->'installments') = 'array'
                                                      THEN p->'installments' ELSE '[]'::jsonb END)
                            WITH ORDINALITY AS t(i, o)), '');
$$;
REVOKE ALL ON FUNCTION public._plan_fingerprint(jsonb) FROM public, anon, authenticated;


CREATE OR REPLACE FUNCTION public._merge_family_from_page(p_server jsonb, p_page jsonb)
RETURNS jsonb
LANGUAGE plpgsql
IMMUTABLE
SET search_path = public, pg_catalog
AS $$
DECLARE
    v_out     jsonb := p_page;
    v_pe      jsonb;
    v_se      jsonb;
    v_ids     text[];
    v_plans   jsonb := '[]'::jsonb;
    v_sp      jsonb;
    p         jsonb;
    e         jsonb;
    n         integer := 0;
    v_ch      jsonb;
    v_pids    text[];
BEGIN
    IF p_server IS NULL OR jsonb_typeof(p_server) <> 'object'
       OR p_page IS NULL OR jsonb_typeof(p_page) <> 'object' THEN
        RETURN p_page;
    END IF;

    -- ── ledger entries: never lose one ───────────────────────────────────────
    v_pe := CASE WHEN jsonb_typeof(p_page->'entries') = 'array' THEN p_page->'entries' ELSE '[]'::jsonb END;
    v_se := CASE WHEN jsonb_typeof(p_server->'entries') = 'array' THEN p_server->'entries' ELSE '[]'::jsonb END;
    IF jsonb_array_length(v_se) > 0 THEN
        SELECT COALESCE(array_agg(x->>'id'), '{}') INTO v_ids FROM jsonb_array_elements(v_pe) x;
        FOR e IN SELECT * FROM jsonb_array_elements(v_se) LOOP
            IF COALESCE(e->>'id', '') <> '' AND NOT (e->>'id' = ANY (v_ids)) THEN
                v_pe := v_pe || jsonb_build_array(e);
            END IF;
        END LOOP;
        v_out := jsonb_set(v_out, '{entries}', v_pe, true);
    END IF;

    -- ── plans: the server's running state on every plan the page kept ───────
    IF jsonb_typeof(p_page->'plans') = 'array' AND jsonb_typeof(p_server->'plans') = 'array' THEN
        FOR p IN SELECT * FROM jsonb_array_elements(p_page->'plans') LOOP
            v_sp := NULL;
            IF COALESCE(p->>'id', '') <> '' THEN
                SELECT x INTO v_sp FROM jsonb_array_elements(p_server->'plans') x WHERE x->>'id' = p->>'id' LIMIT 1;
            ELSIF public._plan_fingerprint(p) <> '||' THEN
                -- No id on either: the same schedule, not the same position — a
                -- plan the office deleted must not hand its bank-debit hold to
                -- the plan that moved up into its place (TED-094).
                SELECT x INTO v_sp FROM jsonb_array_elements(p_server->'plans') x
                 WHERE COALESCE(x->>'id', '') = '' AND public._plan_fingerprint(x) = public._plan_fingerprint(p)
                 LIMIT 1;
            ELSIF jsonb_typeof(p_server->'plans'->n) = 'object'
                  AND COALESCE(p_server->'plans'->n->>'id', '') = '' THEN
                v_sp := p_server->'plans'->n;                     -- nothing else to go on: same position
            END IF;
            v_plans := v_plans || jsonb_build_array(public._merge_plan_state(v_sp, p));
            n := n + 1;
        END LOOP;
        v_out := jsonb_set(v_out, '{plans}', v_plans, true);
    END IF;

    -- ── the old single plan ──────────────────────────────────────────────────
    IF jsonb_typeof(p_page->'plan') = 'object' AND jsonb_typeof(p_server->'plan') = 'object' THEN
        v_out := jsonb_set(v_out, '{plan}', public._merge_plan_state(p_server->'plan', p_page->'plan'), true);
    END IF;

    -- ── extra charges (TED-091) ──────────────────────────────────────────────
    -- The office adds and edits its own charges; it never deletes one. The
    -- shop's (shop_<order>) belong to the server — settle_shop_order bills,
    -- re-prices and cancels them — so those are always the server's, and any
    -- other charge the server holds that this page never saw is kept.
    IF jsonb_typeof(p_server->'charges') = 'array' THEN
        v_ch := '[]'::jsonb;
        FOR e IN SELECT * FROM jsonb_array_elements(
                     CASE WHEN jsonb_typeof(p_page->'charges') = 'array' THEN p_page->'charges' ELSE '[]'::jsonb END) LOOP
            IF COALESCE(e->>'id', '') LIKE 'shop\_%' THEN CONTINUE; END IF;
            v_ch := v_ch || jsonb_build_array(e);
        END LOOP;
        SELECT COALESCE(array_agg(x->>'id'), '{}') INTO v_pids FROM jsonb_array_elements(v_ch) x;
        FOR e IN SELECT * FROM jsonb_array_elements(p_server->'charges') LOOP
            IF COALESCE(e->>'id', '') LIKE 'shop\_%'
               OR (COALESCE(e->>'id', '') <> '' AND NOT (e->>'id' = ANY (v_pids))) THEN
                v_ch := v_ch || jsonb_build_array(e);
            END IF;
        END LOOP;
        v_out := jsonb_set(v_out, '{charges}', v_ch, true);
    END IF;

    RETURN public._keep_charge_links(p_server, v_out);
END;
$$;
REVOKE ALL ON FUNCTION public._merge_family_from_page(jsonb, jsonb) FROM public, anon, authenticated;


-- ▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼
-- 273_a_refund_is_released_only_when_it_is_old.sql
-- ▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲

-- ============================================================================
-- Migration 273: "nothing went through" can only release a refund that has
-- been waiting a few minutes.
--
-- Standalone. Paste into the Supabase SQL Editor and click Run. Safe to run
-- more than once. Run it BEFORE redeploying payments-refund and
-- payments-canteen-refund.
--
-- ── THE PROBLEM (TED-093) ──────────────────────────────────────────────────
-- When the card company never answered a refund, the office is asked to check
-- the processor and confirm "nothing went through" before it is sent again. A
-- refund still RUNNING looks the same from outside: a double-click answered
-- the second click with that question, and confirming within those seconds
-- released the first click's claim and sent a second refund.
--
-- ── THE CHANGE ─────────────────────────────────────────────────────────────
-- release_stale_refund_intent gives a claim back only if it was never settled
-- AND was taken at least three minutes ago — longer than any refund call runs.
-- A younger one answers false, and the office is told to wait and look again.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.release_stale_refund_intent(
    p_camp_id uuid,
    p_key     text,
    p_min_age interval DEFAULT interval '3 minutes'
)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
DECLARE
    v_key text := NULLIF(btrim(COALESCE(p_key, '')), '');
BEGIN
    IF p_camp_id IS NULL OR v_key IS NULL THEN RETURN false; END IF;
    DELETE FROM refund_intents
     WHERE camp_id = p_camp_id AND key = v_key AND settled_at IS NULL
       AND created_at <= now() - GREATEST(COALESCE(p_min_age, interval '3 minutes'), interval '1 minute');
    RETURN FOUND;
END $$;
REVOKE ALL ON FUNCTION public.release_stale_refund_intent(uuid, text, interval) FROM public, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.release_stale_refund_intent(uuid, text, interval) TO service_role;


-- ▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼
-- 274_scope_any_role_to_divisions_grades_or_bunks.sql
-- ▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲

-- ============================================================================
-- Migration 274: scope ANY team member to specific divisions, grades, or
-- bunks — not just schedulers, and not only whole named division groups.
--
-- WHY. Division scoping already existed, but only two ways:
--   1. camp_users.assigned_divisions (a flat text[] of division names), and
--   2. camp_users.subdivision_ids pointing at named `subdivisions` rows,
--      whose own `divisions` column supplied the actual names.
-- Both are DIVISION-granularity only, and both required first creating a
-- named, reusable "division group" before assigning anyone to it — real
-- overhead for the common case of "this one manager, just for Junior
-- division." Neither goes finer than a whole division: a grade or a single
-- bunk was never expressible.
--
-- WHAT THIS ADDS. camp_users.data_scope (jsonb), written directly by the
-- Invite/Edit Team Member forms (team_subdivisions_ui.js) — no RPC, matching
-- how assigned_divisions/product_access are already written today (plain
-- client .insert()/.update() on camp_users, gated by the existing RLS
-- policies on that table, which are row-level and don't need to know about
-- this new column). Shape:
--   {"type": "all"}
--   {"type": "divisions", "divisions": ["Seniors", ...]}
--   {"type": "grades",    "grades":    [{"division": "Seniors", "grade": "Grade 8"}, ...]}
--   {"type": "bunks",     "bunks":     [{"division": "Seniors", "grade": "Grade 8", "bunk": "Bunk 1"}, ...]}
-- NULL/{"type":"all"} = unrestricted, matching how an unconfigured member
-- works everywhere else in the access system (fail-open to "no limit" is
-- the existing convention, not a new one introduced here).
--
-- BACKWARD COMPATIBILITY. assigned_divisions is NOT replaced or migrated —
-- it's still written alongside data_scope (as the flattened list of parent
-- divisions for a grades/bunks scope) so every existing consumer that only
-- knows how to read assigned_divisions (getUserAssignedDivisions() in
-- permissions_guard.js, and everything downstream of it) keeps working
-- unchanged. data_scope is additive: new, finer-grained consumers read it
-- directly; old ones keep reading assigned_divisions exactly as before.
--
-- NO RLS CHANGE NEEDED. This mirrors assigned_divisions/product_access,
-- neither of which has ever had a dedicated RLS policy (confirmed: no
-- migration references assigned_divisions in an RLS clause) — division/
-- grade/bunk scoping in this app has always been a CLIENT-SIDE filtering
-- concern (what's shown/generated), not a database security boundary, and
-- this column follows that exact same, already-shipped model.
-- ============================================================================

ALTER TABLE public.camp_users
    ADD COLUMN IF NOT EXISTS data_scope jsonb;

COMMENT ON COLUMN public.camp_users.data_scope IS
    'Which part of the camp this person''s access applies to: {"type":"all"} (default/unrestricted), {"type":"divisions","divisions":[...]}, {"type":"grades","grades":[{"division","grade"},...]}, or {"type":"bunks","bunks":[{"division","grade","bunk"},...]}. Written directly by team_subdivisions_ui.js alongside assigned_divisions (kept in sync as the flattened parent-division list for backward compatibility with existing consumers). No RLS references this column — like assigned_divisions before it, this is client-side scoping, not a database security boundary.';


-- ▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼
-- 275_a_canteen_refund_takes_its_money_first.sql
-- ▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲

-- ============================================================================
-- Migration 275: a canteen refund takes its money out of the wallet FIRST.
--
-- Standalone. Paste into the Supabase SQL Editor and click Run. Safe to run
-- more than once. Run it BEFORE redeploying payments-canteen-refund,
-- payments-canteen-refund-all, stripe-canteen-refund and
-- stripe-canteen-refund-all — the redeployed functions call it.
--
-- ── THE PROBLEM (TED-110) ──────────────────────────────────────────────────
-- Every canteen refund read the child's balance, asked the card company, and
-- only then took the money off the wallet. Two refunds for the same child at
-- once — "Refund All" running while someone refunds that child, or two office
-- computers — both read the same $20, both sent $20 to the parent, and the
-- wallet ended at -$20. Refund All reads every balance once at the start and
-- runs for minutes at a big camp, so the window was wide; a canteen sale
-- during the run was over-refunded the same way.
--
-- ── THE CHANGE ─────────────────────────────────────────────────────────────
-- A refund now RESERVES its money in one locked step before the card company
-- is asked: the child's wallet row is locked, what is left above the floor is
-- checked, and the amount comes off the balance there and then. A second
-- refund (or a sale) waits for the lock and sees the lower balance. The
-- reservation is a row in canteen_refund_holds:
--
--   open      the money is off the wallet; the card company has been (or is
--             being) asked
--   posted    the card company said yes: the refund line is on the ledger
--   released  the card company said a definite no: the money went back on
--             the wallet
--
-- An answer that never came back leaves the hold OPEN — the money stays off
-- the wallet, because it may have gone to the parent. Stripe holds are
-- re-asked with the same Idempotency-Key and settle themselves; a
-- Cardknox/Banquest one waits for the office to check the processor.
--
-- The hold key is the refund claim's key (refund_intents, 198), so a retry of
-- the same refund meets its own hold and never takes the money twice.
-- ============================================================================

DO $$
BEGIN
    IF to_regprocedure('public.canteen_account_lock(uuid,text)') IS NULL
       OR to_regprocedure('public.canteen_account_save(uuid,text,jsonb)') IS NULL
       OR to_regprocedure('public.canteen_post(uuid,text,jsonb,text)') IS NULL
       OR to_regprocedure('public.canteen_account_key_for(uuid,text)') IS NULL
       OR to_regprocedure('public.camp_person_name_for(uuid,bigint)') IS NULL THEN
        RAISE EXCEPTION '275 needs the canteen row writers (219, 227) and camp_person_name_for (257) — apply those first';
    END IF;
END $$;

SET LOCAL lock_timeout = '15s';

CREATE TABLE IF NOT EXISTS public.canteen_refund_holds (
    camp_id     uuid          NOT NULL,
    hold_key    text          NOT NULL,     -- the refund claim's key
    account_key text          NOT NULL,     -- the wallet the money came off
    amount      numeric(12,2) NOT NULL CHECK (amount > 0),
    method      text          NOT NULL,     -- 'stripe', 'cardknox', 'banquest'
    payment_ref text          NOT NULL,     -- the top-up it is refunded from
    stripe_key  text,                       -- the Idempotency-Key Stripe was sent
    state       text          NOT NULL DEFAULT 'open'
                              CHECK (state IN ('open', 'posted', 'released')),
    refund_id   text,                       -- the card company's refund reference
    created_at  timestamptz   NOT NULL DEFAULT now(),
    settled_at  timestamptz,
    PRIMARY KEY (camp_id, hold_key)
);
CREATE INDEX IF NOT EXISTS idx_canteen_refund_holds_open
    ON public.canteen_refund_holds (camp_id, account_key) WHERE state = 'open';

ALTER TABLE public.canteen_refund_holds ENABLE ROW LEVEL SECURITY;
-- No policies: only the refund functions (service role) read or write it.
REVOKE ALL ON TABLE public.canteen_refund_holds FROM anon, authenticated;


-- ─── reserve: take the money off the wallet, under the wallet's lock ───────
CREATE OR REPLACE FUNCTION public.reserve_canteen_refund(
    p_camp_id     uuid,
    p_camper_name text,
    p_hold_key    text,
    p_amount      numeric,
    p_method      text,
    p_payment_ref text,
    p_stripe_key  text   DEFAULT NULL,
    p_camper_id   bigint DEFAULT NULL)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
DECLARE
    v_name  text := NULLIF(btrim(COALESCE(p_camper_name, '')), '');
    v_key   text := NULLIF(btrim(COALESCE(p_hold_key, '')), '');
    v_amt   numeric := round(COALESCE(p_amount, 0), 2);
    v_acct  jsonb;
    v_hold  canteen_refund_holds;
    v_have  boolean;
    v_avail numeric;
    v_bal   numeric;
BEGIN
    IF p_camper_id IS NOT NULL THEN
        -- The number decides, and is pinned for this call (257), so the name it
        -- resolves to reaches this child's wallet even when another child
        -- shares the name.
        v_name := public.camp_person_name_for(p_camp_id, p_camper_id);
        IF v_name IS NULL THEN
            RETURN jsonb_build_object('success', false, 'error', 'unknown_camper');
        END IF;
    END IF;
    IF p_camp_id IS NULL OR v_name IS NULL OR v_key IS NULL
       OR NULLIF(btrim(COALESCE(p_payment_ref, '')), '') IS NULL
       OR NULLIF(btrim(COALESCE(p_method, '')), '') IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'missing_params');
    END IF;
    IF v_amt <= 0 THEN
        RETURN jsonb_build_object('success', false, 'error', 'invalid_amount');
    END IF;

    -- The wallet's lock first: every reserve, settle and release for this
    -- child queues here, and so does every sale (they take the same lock).
    v_acct := public.canteen_account_lock(p_camp_id, v_name);
    IF v_acct IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'no_canteen_data');
    END IF;

    SELECT * INTO v_hold FROM canteen_refund_holds
     WHERE camp_id = p_camp_id AND hold_key = v_key FOR UPDATE;
    v_have := FOUND;
    -- The same refund again (a retry, or its second press): its money is
    -- already off the wallet, or already refunded. Never take it twice.
    IF v_have AND v_hold.state IN ('open', 'posted') THEN
        RETURN jsonb_build_object('success', true, 'existing', true, 'state', v_hold.state,
                                  'amount', v_hold.amount, 'refundId', v_hold.refund_id,
                                  'balance', COALESCE((v_acct ->> 'balance')::numeric, 0));
    END IF;

    -- The whole balance, never more: a balance floor keeps a child from
    -- SPENDING below it, but a refund goes to the parent, floor and all
    -- (TED-142) — up to $20 a child was otherwise never returnable.
    v_avail := round(COALESCE(NULLIF(v_acct ->> 'balance', '')::numeric, 0), 2);
    IF v_amt > v_avail THEN
        RETURN jsonb_build_object('success', false, 'error', 'insufficient',
                                  'available', GREATEST(v_avail, 0));
    END IF;

    v_bal := round(COALESCE(NULLIF(v_acct ->> 'balance', '')::numeric, 0) - v_amt, 2);
    PERFORM public.canteen_account_save(p_camp_id, v_name, v_acct || jsonb_build_object('balance', v_bal));

    IF v_have THEN
        -- Given back after a "no" and now sent again: reserved afresh.
        UPDATE canteen_refund_holds
           SET amount = v_amt, method = p_method, payment_ref = p_payment_ref,
               stripe_key = p_stripe_key, state = 'open', refund_id = NULL,
               created_at = now(), settled_at = NULL
         WHERE camp_id = p_camp_id AND hold_key = v_key;
    ELSE
        INSERT INTO canteen_refund_holds
            (camp_id, hold_key, account_key, amount, method, payment_ref, stripe_key)
        VALUES (p_camp_id, v_key, public.canteen_account_key_for(p_camp_id, v_name),
                v_amt, p_method, p_payment_ref, p_stripe_key);
    END IF;

    RETURN jsonb_build_object('success', true, 'balance', v_bal);
END $$;
REVOKE ALL ON FUNCTION public.reserve_canteen_refund(uuid, text, text, numeric, text, text, text, bigint)
    FROM public, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.reserve_canteen_refund(uuid, text, text, numeric, text, text, text, bigint)
    TO service_role;


-- ─── settle: the card company said yes — the refund goes on the ledger ─────
-- The money is already off the wallet, so the balance does not move again.
-- A hold that had been given back (the office said "nothing went through",
-- and the card company later turned out to have refunded after all) takes the
-- money off now: it did go to the parent.
CREATE OR REPLACE FUNCTION public.settle_canteen_refund_hold(
    p_camp_id   uuid,
    p_hold_key  text,
    p_refund_id text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
DECLARE
    v_hold   canteen_refund_holds;
    v_acct   jsonb;
    v_bal    numeric;
    v_ref    text := NULLIF(btrim(COALESCE(p_refund_id, '')), '');
    v_posted boolean;
    now_ts   timestamptz := now();
BEGIN
    SELECT * INTO v_hold FROM canteen_refund_holds WHERE camp_id = p_camp_id AND hold_key = p_hold_key;
    IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'no_hold'); END IF;
    IF v_ref IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'missing_refund_id'); END IF;

    v_acct := public.canteen_account_lock(p_camp_id, v_hold.account_key);
    SELECT * INTO v_hold FROM canteen_refund_holds
     WHERE camp_id = p_camp_id AND hold_key = p_hold_key FOR UPDATE;
    IF v_hold.state = 'posted' THEN
        RETURN jsonb_build_object('success', true, 'alreadyProcessed', true,
                                  'balance', COALESCE((v_acct ->> 'balance')::numeric, 0));
    END IF;
    v_bal := COALESCE(NULLIF(v_acct ->> 'balance', '')::numeric, 0);

    -- Already on the ledger under this refund reference (an older function
    -- posted it, and took the money off itself): nothing more comes off.
    SELECT EXISTS (
        SELECT 1 FROM canteen_transactions t
         WHERE t.camp_id = p_camp_id
           AND (t.payload ->> 'stripeRefundId' = v_ref OR t.payload ->> 'byopRefundId' = v_ref)
    ) INTO v_posted;

    IF v_posted AND v_hold.state = 'open' THEN
        v_bal := round(v_bal + v_hold.amount, 2);       -- that post already took it
        PERFORM public.canteen_account_save(p_camp_id, v_hold.account_key, v_acct || jsonb_build_object('balance', v_bal));
    ELSIF NOT v_posted THEN
        IF v_hold.state = 'released' THEN
            v_bal := round(v_bal - v_hold.amount, 2);
            PERFORM public.canteen_account_save(p_camp_id, v_hold.account_key, v_acct || jsonb_build_object('balance', v_bal));
        END IF;
        PERFORM public.canteen_post(p_camp_id, v_hold.account_key,
            jsonb_build_object(
                'time',   to_char(now_ts, 'HH12:MI AM'),
                'camper', v_hold.account_key,
                'items',  'Refund — deposit reversed',
                'amount', v_hold.amount,
                'type',   'debit',
                'kind',   'refund',
                'method', v_hold.method,
                'date',   to_char(now_ts, 'YYYY-MM-DD'),
                'refundHold', v_hold.hold_key,
                'timestamp', (extract(epoch from now_ts) * 1000)::bigint)
            || CASE WHEN v_hold.method = 'stripe'
                    THEN jsonb_build_object('stripePaymentIntentId', v_hold.payment_ref, 'stripeRefundId', v_ref)
                    ELSE jsonb_build_object('byopTransactionId', v_hold.payment_ref, 'byopRefundId', v_ref) END);
    END IF;

    UPDATE canteen_refund_holds SET state = 'posted', refund_id = v_ref, settled_at = now_ts
     WHERE camp_id = p_camp_id AND hold_key = p_hold_key;
    RETURN jsonb_build_object('success', true, 'balance', v_bal);
END $$;
REVOKE ALL ON FUNCTION public.settle_canteen_refund_hold(uuid, text, text) FROM public, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.settle_canteen_refund_hold(uuid, text, text) TO service_role;


-- ─── release: a definite "no" — the money goes back on the wallet ──────────
-- p_min_age is for "the office checked and nothing went through": only a hold
-- that has waited that long (longer than any refund call runs) is given back,
-- never one still on its way.
CREATE OR REPLACE FUNCTION public.release_canteen_refund_hold(
    p_camp_id  uuid,
    p_hold_key text,
    p_min_age  interval DEFAULT NULL)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
DECLARE
    v_hold canteen_refund_holds;
    v_acct jsonb;
    v_bal  numeric;
BEGIN
    SELECT * INTO v_hold FROM canteen_refund_holds WHERE camp_id = p_camp_id AND hold_key = p_hold_key;
    IF NOT FOUND THEN RETURN jsonb_build_object('released', false, 'error', 'no_hold'); END IF;

    v_acct := public.canteen_account_lock(p_camp_id, v_hold.account_key);
    SELECT * INTO v_hold FROM canteen_refund_holds
     WHERE camp_id = p_camp_id AND hold_key = p_hold_key FOR UPDATE;
    IF v_hold.state <> 'open' THEN
        RETURN jsonb_build_object('released', false, 'state', v_hold.state);
    END IF;
    IF p_min_age IS NOT NULL
       AND v_hold.created_at > now() - GREATEST(p_min_age, interval '1 minute') THEN
        RETURN jsonb_build_object('released', false, 'error', 'too_new');
    END IF;

    v_bal := round(COALESCE(NULLIF(v_acct ->> 'balance', '')::numeric, 0) + v_hold.amount, 2);
    PERFORM public.canteen_account_save(p_camp_id, v_hold.account_key, v_acct || jsonb_build_object('balance', v_bal));
    UPDATE canteen_refund_holds SET state = 'released', settled_at = now()
     WHERE camp_id = p_camp_id AND hold_key = p_hold_key;
    RETURN jsonb_build_object('released', true, 'balance', v_bal, 'amount', v_hold.amount);
END $$;
REVOKE ALL ON FUNCTION public.release_canteen_refund_hold(uuid, text, interval) FROM public, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.release_canteen_refund_hold(uuid, text, interval) TO service_role;


-- ─── the refund screens see what is on its way ─────────────────────────────
-- canteen_refund_view (250) also lists the open holds, so a refund counts
-- money already on its way to a parent against the top-up it came from, and
-- can tell the office about one the card company never confirmed.
CREATE OR REPLACE FUNCTION public.canteen_refund_view(p_camp_id uuid)
RETURNS jsonb
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
    SELECT jsonb_build_object(
        'success', true,
        'accounts', COALESCE((
            SELECT jsonb_object_agg(a.account_key, public._canteen_account_json(a)
                       || CASE WHEN a.person_id IS NULL THEN '{}'::jsonb
                               ELSE jsonb_build_object('camperId', a.person_id) END)
              FROM camp_canteen_accounts a
             WHERE a.camp_id = p_camp_id AND a.deleted_at IS NULL), '{}'::jsonb),
        'transactions', COALESCE((
            SELECT jsonb_agg(public._canteen_tx_json(t) ORDER BY t.tx_date, t.first_seen)
              FROM canteen_transactions t
             WHERE t.camp_id = p_camp_id
               AND (t.tx_type = 'credit' OR t.payload ->> 'kind' = 'refund')), '[]'::jsonb),
        'holds', COALESCE((
            SELECT jsonb_agg(jsonb_build_object(
                       'key', h.hold_key, 'accountKey', h.account_key,
                       'camperId', a.person_id, 'amount', h.amount, 'method', h.method,
                       'paymentRef', h.payment_ref, 'stripeKey', h.stripe_key,
                       'createdAt', h.created_at,
                       'ageSeconds', floor(extract(epoch FROM now() - h.created_at)))
                     ORDER BY h.created_at)
              FROM canteen_refund_holds h
              LEFT JOIN camp_canteen_accounts a
                     ON a.camp_id = h.camp_id AND a.account_key = h.account_key
             WHERE h.camp_id = p_camp_id AND h.state = 'open'), '[]'::jsonb))
$$;
REVOKE ALL ON FUNCTION public.canteen_refund_view(uuid) FROM public, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.canteen_refund_view(uuid) TO service_role;


-- ▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼
-- 276_an_unanswered_autopay_charge_waits_for_the_office.sql
-- ▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲

-- ============================================================================
-- Migration 276: an autopay charge the card company never answered waits for
-- the office.
--
-- Standalone. Paste into the Supabase SQL Editor and click Run. Safe to run
-- more than once. Run it BEFORE redeploying charge-due-installments.
--
-- ── THE PROBLEM (TED-113) ──────────────────────────────────────────────────
-- One card-company call that dropped during the nightly autopay run stopped the
-- whole run: every family after it, at every camp, was charged a night late.
-- The dropped family's charge was never recorded, so on Cardknox/Banquest the
-- next night charged them again; a Banquest gateway timeout was booked as a
-- decline.
--
-- ── THE CHANGE ─────────────────────────────────────────────────────────────
-- The runner (redeployed) now holds such a charge ON THE PLAN — the same
-- pendingCharge slot a clearing bank debit uses (269), marked `unconfirmed` —
-- and tells the office in Billing. Nothing more is charged on that plan until
-- the office answers, which is this function:
--
--   went through      the instalment is recorded as paid, with the processor's
--                     reference, exactly as the runner would have recorded it;
--   did not go through the hold is cleared, and autopay tries again on its
--                     next run.
--
-- Only a member of the camp who can edit Billing can answer (the same rule as
-- recording a payment by hand, with 277's membership check).
-- ============================================================================

DO $$
BEGIN
    IF to_regprocedure('public.hold_autopay_charge(uuid,text,text,jsonb)') IS NULL
       OR to_regprocedure('public._plan_path(jsonb,text)') IS NULL
       OR to_regprocedure('public.record_autopay_charge(uuid,text,text,integer,text,numeric,text,jsonb,text,text)') IS NULL
       OR to_regprocedure('public.record_autopay_installment(uuid,text,text,integer,text,jsonb,jsonb,text)') IS NULL
       OR to_regprocedure('public.user_section_level(uuid,text)') IS NULL
       OR to_regprocedure('public.camp_staff_member(uuid)') IS NULL THEN
        RAISE EXCEPTION '276 needs migrations 183, 215, 233 and 269 (and the access resolver) — apply those first';
    END IF;
END $$;

CREATE OR REPLACE FUNCTION public.resolve_unconfirmed_autopay(
    p_camp_id      uuid,
    p_family_key   text,
    p_plan_ref     text,          -- the plan's id, or '#<position>' (269)
    p_went_through boolean,
    p_reference    text DEFAULT NULL)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
DECLARE
    v_fam   jsonb;
    v_path  text[];
    v_plan  jsonb;
    v_hold  jsonb;
    v_ref   text := NULLIF(btrim(COALESCE(p_reference, '')), '');
    v_proc  text;
    v_amt   numeric;
    v_pay   jsonb;
    v_note  text := 'Autopay instalment — confirmed by the office (the card company never answered)';
    r       jsonb;
BEGIN
    IF auth.uid() IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_authenticated');
    END IF;
    IF p_camp_id IS NULL OR COALESCE(p_family_key, '') = '' OR COALESCE(p_plan_ref, '') = '' OR p_went_through IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'bad_arguments');
    END IF;
    -- A member of THIS camp first: the section resolver answers "edit" for a
    -- caller it cannot place at all (it leaves membership to its callers).
    IF NOT public.camp_staff_member(p_camp_id)
       OR COALESCE(public.user_section_level(p_camp_id, 'me.billing'), 'none') <> 'edit' THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_authorized');
    END IF;

    v_fam := public.camp_family_for_update(p_camp_id, p_family_key);
    IF v_fam IS NULL OR jsonb_typeof(v_fam) <> 'object' THEN
        RETURN jsonb_build_object('success', false, 'error', 'family_not_found');
    END IF;
    v_path := public._plan_path(v_fam, p_plan_ref);
    IF v_path IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'plan_not_found');
    END IF;
    v_plan := v_fam #> v_path;
    v_hold := v_plan -> 'pendingCharge';
    IF v_hold IS NULL OR jsonb_typeof(v_hold) <> 'object' OR COALESCE((v_hold->>'unconfirmed')::boolean, false) IS NOT TRUE THEN
        RETURN jsonb_build_object('success', false, 'error', 'nothing_to_answer');
    END IF;

    IF p_went_through THEN
        IF v_ref IS NULL THEN
            RETURN jsonb_build_object('success', false, 'error', 'reference_required');
        END IF;
        v_proc := COALESCE(v_hold->>'processor', '');
        v_amt  := round(COALESCE((v_hold->>'amount')::numeric, 0), 2);
        IF v_amt <= 0 THEN
            RETURN jsonb_build_object('success', false, 'error', 'no_amount');
        END IF;
        -- Stripe: the payment's own id, and nothing else (TED-120). It is what
        -- the webhook books the same money under, so the two meet as one
        -- payment; a charge id (ch_…) or anything else would be counted twice.
        IF v_proc = 'stripe' AND v_ref !~ '^pi_[A-Za-z0-9]+$' THEN
            RETURN jsonb_build_object('success', false, 'error', 'stripe_needs_payment_id');
        END IF;
        -- A reference already booked for a DIFFERENT amount is another payment.
        IF EXISTS (SELECT 1 FROM camp_payments p
                    WHERE p.camp_id = p_camp_id AND p.deleted_at IS NULL
                      AND (p.payload->>'stripePaymentIntentId' = v_ref OR p.payload->>'byopTransactionId' = v_ref
                           OR p.payload->>'reference' = v_ref)
                      AND round(COALESCE((p.payload->>'amount')::numeric, 0), 2) <> v_amt) THEN
            RETURN jsonb_build_object('success', false, 'error', 'reference_is_another_payment');
        END IF;
        v_pay := jsonb_build_object(
            'id', CASE WHEN v_proc = 'stripe' THEN 'auto_' ELSE 'auto_byop_' END || v_ref,
            'familyKey', p_family_key, 'amount', v_amt,
            'date', COALESCE(v_hold->>'since', to_char(now(), 'YYYY-MM-DD')),
            'method', 'Autopay (card)', 'reference', v_ref, 'notes', v_note,
            'status', 'succeeded', 'timestamp', (extract(epoch FROM now()) * 1000)::bigint)
          || CASE WHEN v_proc = 'stripe'
                  THEN jsonb_build_object('stripePaymentIntentId', v_ref)
                  ELSE jsonb_build_object('byopTransactionId', v_ref, 'byopProcessor', v_proc) END;

        IF jsonb_typeof(v_plan->'dueDates') = 'array' AND (v_hold->>'index') IS NOT NULL THEN
            r := public.record_autopay_charge(p_camp_id, p_family_key,
                    COALESCE(NULLIF(v_hold->>'planId', ''), v_plan->>'id'),
                    (v_hold->>'index')::integer, v_hold->>'dueDate', v_amt,
                    NULL, v_pay, v_ref, v_note);
        ELSIF jsonb_typeof(v_plan->'installments') = 'array' THEN
            r := public.record_autopay_installment(p_camp_id, p_family_key,
                    NULLIF(COALESCE(NULLIF(v_hold->>'planId', ''), v_plan->>'id'), ''),
                    (v_hold->>'planIndex')::integer, v_hold->>'dueDate',
                    jsonb_build_object('status', 'paid', 'paidDate', COALESCE(v_hold->>'since', to_char(now(), 'YYYY-MM-DD')))
                      || CASE WHEN v_proc = 'stripe' THEN jsonb_build_object('stripePaymentIntentId', v_ref)
                              ELSE jsonb_build_object('byopTransactionId', v_ref) END,
                    v_pay, v_ref);
        ELSE
            RETURN jsonb_build_object('success', false, 'error', 'plan_shape_unknown');
        END IF;
        IF r IS NULL OR COALESCE((r->>'success')::boolean, false) IS NOT TRUE THEN
            RETURN jsonb_build_object('success', false, 'error', COALESCE(r->>'error', 'not_recorded'));
        END IF;
    END IF;

    -- Either way the question is answered: the hold goes.
    r := public.hold_autopay_charge(p_camp_id, p_family_key, p_plan_ref, NULL);
    IF COALESCE((r->>'success')::boolean, false) IS NOT TRUE THEN
        RETURN jsonb_build_object('success', false, 'error', COALESCE(r->>'error', 'hold_not_cleared'));
    END IF;
    RETURN jsonb_build_object('success', true, 'recorded', p_went_through);
END $$;
REVOKE ALL ON FUNCTION public.resolve_unconfirmed_autopay(uuid, text, text, boolean, text) FROM public, anon;
GRANT EXECUTE ON FUNCTION public.resolve_unconfirmed_autopay(uuid, text, text, boolean, text) TO authenticated, service_role;


-- ▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼
-- 277_billing_answers_only_its_own_camp.sql
-- ▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲

-- ============================================================================
-- Migration 277: a camp's billing answers only that camp's own office.
--
-- Standalone. Paste into the Supabase SQL Editor and click Run. Safe to run
-- more than once. Nothing to redeploy: the page and the edge functions call
-- the same functions as before.
--
-- ── THE PROBLEM ────────────────────────────────────────────────────────────
-- Anyone with a Campistry login — a parent from Link, anyone who signed up —
-- could read and change ANY camp's billing, given that camp's id:
--
--   * get_camp_families / get_camp_payments (every family, every payment) and
--     sync_camp_billing (the page's Billing save: add, change or delete
--     families and payments) asked only the access-section resolver. That
--     resolver answers "edit" for a caller who is not in the camp at all — on
--     purpose, because every RLS policy that uses it also checks the camp
--     (migration 160's note). These three functions did not.
--   * append_camp_payment (add a payment, posted to the family's ledger),
--     record_autopay_installment (mark an instalment paid, with a payment),
--     sync_family_ledger_payments (post payments; its report lists families
--     and amounts) and parent_billing_slice (a family's billing, by camper
--     names the CALLER supplies) could be called by any signed-in user with
--     no check at all. Only the server ever calls them: the payment webhooks,
--     the nightly autopay run, get_my_balance.
--
-- ── THE CHANGE ─────────────────────────────────────────────────────────────
--   1. The three office functions also require a member of THAT camp — its
--      owner or an accepted staff member (camp_staff_member, 183) — before
--      the section check. A NULL from the resolver is "no", never "yes".
--   2. The four server-only functions can no longer be called from a browser.
--      The server (service role) and the functions that call them are
--      unaffected.
-- ============================================================================

DO $$
BEGIN
    IF to_regprocedure('public.camp_staff_member(uuid)') IS NULL THEN
        RAISE EXCEPTION '277 needs camp_staff_member (migration 183) — apply it first';
    END IF;
END $$;

SET LOCAL lock_timeout = '15s';

-- 1. the office's own billing functions: a member of this camp first
DO $$
DECLARE
    f     text;
    d     text;
    o     text;
    n     text;
    fixes text[][] := ARRAY[
        ARRAY['public.sync_camp_billing(uuid,jsonb,jsonb,jsonb,jsonb)',
              $o$IF public.user_section_level(p_camp_id, 'me.billing') <> 'edit' THEN$o$,
              $n$IF NOT public.camp_staff_member(p_camp_id)
       OR COALESCE(public.user_section_level(p_camp_id, 'me.billing'), 'none') <> 'edit' THEN$n$],
        ARRAY['public.get_camp_payments(uuid)',
              $o$IF public.user_section_level(p_camp_id, 'me.billing') = 'none' THEN$o$,
              $n$IF NOT public.camp_staff_member(p_camp_id)
       OR COALESCE(public.user_section_level(p_camp_id, 'me.billing'), 'none') = 'none' THEN$n$],
        ARRAY['public.get_camp_families(uuid)',
              $o$IF public.user_section_level(p_camp_id, 'me.billing') = 'none' THEN$o$,
              $n$IF NOT public.camp_staff_member(p_camp_id)
       OR COALESCE(public.user_section_level(p_camp_id, 'me.billing'), 'none') = 'none' THEN$n$]];
    i int;
BEGIN
    FOR i IN 1 .. array_length(fixes, 1) LOOP
        f := fixes[i][1]; o := fixes[i][2]; n := fixes[i][3];
        IF to_regprocedure(f) IS NULL THEN
            RAISE NOTICE '277: % is not on this database — skipped', f;
            CONTINUE;
        END IF;
        d := pg_get_functiondef(to_regprocedure(f));
        IF position('camp_staff_member(p_camp_id)' IN d) > 0 THEN
            RAISE NOTICE '277: % already checks the camp', f;
            CONTINUE;
        END IF;
        IF position(o IN d) = 0 THEN
            RAISE EXCEPTION '277: % does not look the way this file expects — send this message to the builder', f;
        END IF;
        EXECUTE replace(d, o, n);
    END LOOP;
END $$;

-- 2. the server's own writers and readers: not for browsers
DO $$
DECLARE
    f text;
BEGIN
    FOREACH f IN ARRAY ARRAY[
        'public.append_camp_payment(uuid,jsonb,text,jsonb)',
        'public.record_autopay_installment(uuid,text,text,integer,text,jsonb,jsonb,text)',
        'public.sync_family_ledger_payments(uuid,text,boolean)',
        'public.parent_billing_slice(uuid,jsonb,jsonb)'] LOOP
        IF to_regprocedure(f) IS NULL THEN CONTINUE; END IF;
        EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC, anon, authenticated', f);
        EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO service_role', f);
    END LOOP;
END $$;


-- ▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼
-- 278_a_refund_that_fails_later_puts_the_money_back.sql
-- ▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲

-- ============================================================================
-- Migration 278: a Stripe refund that fails after Stripe accepted it puts the
-- money back, and tells the office.
--
-- Standalone. Paste into the Supabase SQL Editor and click Run. Safe to run
-- more than once. Run it BEFORE redeploying stripe-webhook.
--
-- ── THE PROBLEM (TED-126) ──────────────────────────────────────────────────
-- Stripe can accept a refund and fail it days later — the parent's card
-- account was closed, say. Campistry booked the refund when Stripe accepted it
-- and never heard about the failure: the family's bill (or the child's canteen
-- wallet) kept saying "refunded" while the parent got nothing. With a
-- destination charge the money lands back in Campistry's platform balance, so
-- the camp's own Stripe account never shows it either.
--
-- ── THE CHANGE ─────────────────────────────────────────────────────────────
-- stripe-webhook (redeployed) now listens for Stripe's refund.failed (and a
-- refund.updated / charge.refund.updated whose status is failed) and calls
-- this function, once per failed refund:
--
--   a canteen refund   the money goes back on the child's wallet, with a
--                      "refund failed" line on its history (its top-up can be
--                      refunded again: the refund screens subtract the line);
--   a family refund    the family's ledger gets the money back as a payment
--                      entry (the way a won chargeback is posted, 175), and
--                      the payments list gets the matching row;
--   either             a Billing notice (only people who can see Billing).
--   neither            (not on these books — made in the Stripe dashboard, or
--                      its answer was lost) still a Billing notice, and the
--                      webhook still alerts the platform (TED-131): the money
--                      is back in Campistry's Stripe balance either way.
--
-- A canteen refund put back reopens its reservation (TED-129), so the next
-- Refund All refunds that money again rather than finding it "already done".
--
-- The same failure again (Stripe re-sends events) changes nothing, and says
-- so (firstNotice false), so the platform is alerted once.
-- ============================================================================

DO $$
BEGIN
    IF to_regprocedure('public.canteen_account_lock(uuid,text)') IS NULL
       OR to_regprocedure('public.canteen_account_save(uuid,text,jsonb)') IS NULL
       OR to_regprocedure('public.canteen_post(uuid,text,jsonb,text)') IS NULL
       OR to_regprocedure('public.camp_families_object(uuid)') IS NULL
       OR to_regprocedure('public.camp_family_for_update(uuid,text)') IS NULL
       OR to_regprocedure('public.camp_payment_add(uuid,jsonb)') IS NULL
       OR to_regprocedure('public.payment_ledger_entry(jsonb)') IS NULL
       OR to_regprocedure('public.is_money_notice(text)') IS NULL THEN
        RAISE EXCEPTION '278 needs migrations 178, 215, 219, 227 and 270 — apply those first';
    END IF;
END $$;

-- ── the notice is a money notice (270): only people who can see Billing ──────
CREATE OR REPLACE FUNCTION public.is_money_notice(p_source text)
RETURNS boolean
LANGUAGE sql
IMMUTABLE
SET search_path = public, pg_catalog
AS $$
    SELECT COALESCE(p_source, '') IN (
        'payment_unmatched', 'autopay_blocked', 'chargeback', 'card_expiry',
        'parent_payment_plan_created', 'payout_failed', 'charge_unconfirmed',
        'canteen_autoreload_off', 'tip_transfer_failed', 'telnyx_fee_failed', 'autopay_setup',
        'refund_failed');
$$;
GRANT EXECUTE ON FUNCTION public.is_money_notice(text) TO authenticated, service_role;


-- A failed refund that is not on these books: the office is told, once.
-- Returns whether this was the first time (so the platform is alerted once).
DROP FUNCTION IF EXISTS public._notice_unbooked_refund_failure(uuid, text, text, numeric, text);
CREATE OR REPLACE FUNCTION public._notice_unbooked_refund_failure(
    p_camp_id     uuid,
    p_refund_id   text,
    p_reason      text,
    p_amount      numeric,
    p_payment_ref text,
    p_hold_key    text)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
DECLARE
    v_n       integer := 0;
    v_waiting canteen_refund_holds;
    v_what    text := 'Stripe could not send a ' || COALESCE('$' || to_char(round(p_amount, 2), 'FM999999990.00') || ' ', '')
                      || 'refund (' || p_refund_id || COALESCE(', on payment ' || NULLIF(p_payment_ref, ''), '') || ')'
                      || COALESCE(' — ' || NULLIF(p_reason, ''), '') || '. The parent did not get it. ';
BEGIN
    IF to_regclass('public.notifications') IS NULL THEN RETURN true; END IF;
    -- Campistry's own canteen refund whose answer was lost (TED-138): its money
    -- is still held off the child's wallet, and the next look-up (Refund All,
    -- or that child's Refund) puts it back and sends it again. Refunding it by
    -- hand as well would pay the parent twice.
    IF NULLIF(p_hold_key, '') IS NOT NULL THEN
        SELECT * INTO v_waiting FROM canteen_refund_holds
         WHERE camp_id = p_camp_id AND hold_key = p_hold_key AND state = 'open';
    END IF;
    INSERT INTO notifications (camp_id, source, source_id, title, body, link_target)
    VALUES (p_camp_id, 'refund_failed', p_refund_id,
            CASE WHEN v_waiting.hold_key IS NOT NULL THEN 'A canteen refund failed' ELSE 'A refund failed' END,
            v_what
              || CASE WHEN v_waiting.hold_key IS NOT NULL
                      THEN 'It was a canteen refund of ' || regexp_replace(v_waiting.account_key, '\s#\d+$', '')
                           || '''s money that Campistry was still waiting to hear about. Its money is held off the wallet: '
                           || 'the next Refund All in Snacks (or that child''s Refund) looks it up, puts it back on the wallet and sends it again. '
                           || 'Do NOT refund it by hand as well — the parent would be paid twice. '
                      ELSE 'It is not on Campistry''s books (it may have been made in the Stripe dashboard), so nothing was changed here: '
                           || 'find the payment in Stripe, then refund it again or record it by hand. ' END
              || 'Stripe returned the money to Campistry''s platform account; Campistry has been alerted to pass it back to yours.',
            CASE WHEN v_waiting.hold_key IS NOT NULL THEN 'campistry_snacks.html' ELSE 'campistry_me.html' END)
    ON CONFLICT (camp_id, source, source_id) DO NOTHING;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    RETURN v_n > 0;
END $$;
REVOKE ALL ON FUNCTION public._notice_unbooked_refund_failure(uuid, text, text, numeric, text, text) FROM public, anon, authenticated;

-- A failed refund no camp could be found for: the platform is alerted once
-- (TED-137) — Stripe sends the failure several times (refund.failed,
-- refund.updated, charge.refund.updated, and retries).
CREATE TABLE IF NOT EXISTS public.refund_failure_alerts (
    refund_id  text        PRIMARY KEY,
    first_seen timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.refund_failure_alerts ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.refund_failure_alerts FROM public, anon, authenticated;
CREATE OR REPLACE FUNCTION public.claim_refund_failure_alert(p_refund_id text)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
DECLARE v_n integer := 0;
BEGIN
    IF NULLIF(btrim(COALESCE(p_refund_id, '')), '') IS NULL THEN RETURN true; END IF;
    INSERT INTO refund_failure_alerts (refund_id) VALUES (p_refund_id) ON CONFLICT (refund_id) DO NOTHING;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    RETURN v_n > 0;
END $$;
REVOKE ALL ON FUNCTION public.claim_refund_failure_alert(text) FROM public, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.claim_refund_failure_alert(text) TO service_role;

DROP FUNCTION IF EXISTS public.reverse_failed_stripe_refund(uuid, text, text);
DROP FUNCTION IF EXISTS public.reverse_failed_stripe_refund(uuid, text, text, numeric, text);
CREATE OR REPLACE FUNCTION public.reverse_failed_stripe_refund(
    p_camp_id     uuid,
    p_refund_id   text,
    p_reason      text    DEFAULT NULL,
    p_amount      numeric DEFAULT NULL,    -- Stripe's, for a refund not on these books
    p_payment_ref text    DEFAULT NULL,    -- the payment it was refunding, likewise
    p_hold_key    text    DEFAULT NULL)    -- its metadata.campistryHold, when Campistry sent it
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
DECLARE
    now_ts   timestamptz := now();
    v_ref    text := NULLIF(btrim(COALESCE(p_refund_id, '')), '');
    v_why    text := NULLIF(btrim(COALESCE(p_reason, '')), '');
    v_tx     record;
    v_key    text;
    v_acct   jsonb;
    v_bal    numeric;
    v_amt    numeric;
    famRec   record;
    v_famKey text;
    v_entry  jsonb;
    v_fam    jsonb;
    v_row    jsonb;
    v_rev    jsonb;
    v_who    text;
    v_first  boolean := false;
    v_n      integer;
BEGIN
    IF p_camp_id IS NULL OR v_ref IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'bad_arguments');
    END IF;

    -- ── a canteen refund: the money goes back on the child's wallet ─────────
    SELECT camper, amount, payload INTO v_tx
      FROM canteen_transactions
     WHERE camp_id = p_camp_id AND payload ->> 'stripeRefundId' = v_ref
       AND payload ->> 'kind' = 'refund'
     LIMIT 1;
    IF FOUND THEN
        v_key  := public.canteen_account_key_for(p_camp_id, v_tx.camper);
        v_acct := public.canteen_account_lock(p_camp_id, v_key);
        IF v_acct IS NULL THEN
            v_first := public._notice_unbooked_refund_failure(p_camp_id, v_ref, v_why, COALESCE(p_amount, v_tx.amount), p_payment_ref, p_hold_key);
            RETURN jsonb_build_object('success', false, 'error', 'account_not_found', 'firstNotice', v_first);
        END IF;
        -- once, under the wallet's lock
        IF EXISTS (SELECT 1 FROM canteen_transactions
                    WHERE camp_id = p_camp_id AND sig = 'refail:' || v_ref) THEN
            RETURN jsonb_build_object('success', true, 'alreadyRecorded', true, 'canteen', true);
        END IF;
        v_amt := round(COALESCE(v_tx.amount, NULLIF(v_tx.payload ->> 'amount', '')::numeric, 0), 2);
        IF v_amt <= 0 THEN
            RETURN jsonb_build_object('success', false, 'error', 'no_amount');
        END IF;
        v_bal := round(COALESCE(NULLIF(v_acct ->> 'balance', '')::numeric, 0) + v_amt, 2);
        PERFORM public.canteen_account_save(p_camp_id, v_key, v_acct || jsonb_build_object('balance', v_bal));
        PERFORM public.canteen_post(p_camp_id, v_key,
            jsonb_build_object(
                'time',   to_char(now_ts, 'HH12:MI AM'),
                'camper', v_key,
                'items',  'Refund failed at the card company — the money is back on the wallet',
                'amount', v_amt,
                'type',   'credit',
                'kind',   'refund_failed',
                'method', 'stripe',
                'date',   to_char(now_ts, 'YYYY-MM-DD'),
                'stripePaymentIntentId', v_tx.payload ->> 'stripePaymentIntentId',
                'failedRefundId', v_ref,
                'timestamp', (extract(epoch FROM now_ts) * 1000)::bigint)
            || CASE WHEN v_tx.payload ? 'camperId'
                    THEN jsonb_build_object('camperId', v_tx.payload -> 'camperId') ELSE '{}'::jsonb END,
            'refail:' || v_ref);
        -- The reservation this refund settled is open for a new refund again
        -- (TED-129): "posted" told the next Refund All the money was already
        -- sent, and it skipped the child. Released is the truth — the money is
        -- back on the wallet — and a reserve under the same key takes it afresh.
        UPDATE canteen_refund_holds SET state = 'released', settled_at = now_ts
         WHERE camp_id = p_camp_id AND refund_id = v_ref AND state = 'posted';
        v_who := COALESCE(NULLIF(v_acct ->> 'camperName', ''), regexp_replace(v_key, '\s#\d+$', ''));
        IF to_regclass('public.notifications') IS NOT NULL THEN
            INSERT INTO notifications (camp_id, source, source_id, title, body, link_target)
            VALUES (p_camp_id, 'refund_failed', v_ref,
                    'A canteen refund failed',
                    'Stripe could not send the $' || to_char(v_amt, 'FM999999990.00') || ' canteen refund for ' || v_who
                      || ' (' || v_ref || ')' || COALESCE(' — ' || v_why, '') || '. The parent did not get it. '
                      || 'The money is back on the child''s canteen wallet: refund it again (Snacks → Refund) or pay it out. '
                      || 'Stripe returned it to Campistry''s platform account; Campistry has been alerted to pass it back to yours.',
                    'campistry_snacks.html')
            ON CONFLICT (camp_id, source, source_id) DO NOTHING;
            GET DIAGNOSTICS v_n = ROW_COUNT;
            v_first := v_n > 0;
        END IF;
        RETURN jsonb_build_object('success', true, 'canteen', true, 'account', v_key,
                                  'amount', v_amt, 'balance', v_bal, 'firstNotice', v_first);
    END IF;

    -- ── a family refund: the ledger gets the money back ─────────────────────
    FOR famRec IN SELECT key, value FROM jsonb_each(public.camp_families_object(p_camp_id)) LOOP
        IF jsonb_typeof(famRec.value) <> 'object' OR jsonb_typeof(famRec.value -> 'entries') <> 'array' THEN CONTINUE; END IF;
        SELECT e INTO v_entry
          FROM jsonb_array_elements(famRec.value -> 'entries') e
         WHERE e ->> 'kind' = 'refund'
           AND (e ->> 'id' = 'le_pay_' || v_ref OR e -> 'source' ->> 'paymentId' = v_ref)
         LIMIT 1;
        IF v_entry IS NOT NULL THEN v_famKey := famRec.key; EXIT; END IF;
    END LOOP;

    IF v_famKey IS NULL THEN
        -- Not on these books: made in the Stripe dashboard, or its answer was
        -- lost (a canteen refund still waiting is settled by its look-up).
        -- Nothing to put back here — but the parent did not get it and the
        -- money is in Campistry's Stripe balance, so the office is told
        -- (TED-131), once.
        v_first := public._notice_unbooked_refund_failure(p_camp_id, v_ref, v_why, p_amount, p_payment_ref, p_hold_key);
        RETURN jsonb_build_object('success', false, 'error', 'refund_not_found', 'firstNotice', v_first);
    END IF;

    v_fam := public.camp_family_for_update(p_camp_id, v_famKey);
    IF EXISTS (SELECT 1 FROM jsonb_array_elements(COALESCE(v_fam -> 'entries', '[]'::jsonb)) e
                WHERE e ->> 'id' = 'le_pay_refail_' || v_ref OR e -> 'source' ->> 'paymentId' = 'refail_' || v_ref) THEN
        RETURN jsonb_build_object('success', true, 'alreadyRecorded', true, 'familyKey', v_famKey);
    END IF;
    v_amt := round(COALESCE((v_entry ->> 'amount')::numeric, 0), 2);
    IF v_amt <= 0 THEN
        RETURN jsonb_build_object('success', false, 'error', 'no_amount');
    END IF;

    -- the payments list's row, and the ledger entry made from it — the same
    -- pair every payment writer posts, so sync_family_ledger_payments sees it
    -- as covered and never posts it twice
    v_row := jsonb_build_object(
        'id',        'refail_' || v_ref,
        'family',    COALESCE(v_fam ->> 'name', v_famKey),
        'familyKey', v_famKey,
        'amount',    v_amt,
        'date',      to_char(now_ts, 'YYYY-MM-DD'),
        'method',    'Refund failed',
        'reference', 'refail_' || v_ref,
        'failedRefundId', v_ref,
        'status',    'succeeded',
        'notes',     'Refund ' || v_ref || ' failed at Stripe' || COALESCE(' (' || v_why || ')', '')
                     || ' — the parent did not get it; the money is back on the account',
        'offline',   false,
        'timestamp', (extract(epoch FROM now_ts) * 1000)::bigint);
    v_rev := public.payment_ledger_entry(v_row)
             || jsonb_build_object('reason', 'refund_failed',
                                   'source', jsonb_build_object('paymentId', 'refail_' || v_ref, 'reverses', v_entry ->> 'id'));
    v_fam := jsonb_set(v_fam, '{entries}', COALESCE(v_fam -> 'entries', '[]'::jsonb) || jsonb_build_array(v_rev), true);
    PERFORM public.camp_family_save(p_camp_id, v_famKey, v_fam);
    PERFORM public.camp_payment_add(p_camp_id, v_row);

    IF to_regclass('public.notifications') IS NOT NULL THEN
        INSERT INTO notifications (camp_id, source, source_id, title, body, link_target)
        VALUES (p_camp_id, 'refund_failed', v_ref,
                'A refund failed',
                'Stripe could not send the $' || to_char(v_amt, 'FM999999990.00') || ' refund to '
                  || COALESCE(v_fam ->> 'name', v_famKey) || ' (' || v_ref || ')' || COALESCE(' — ' || v_why, '')
                  || '. The parent did not get it. It is back on the family''s account as a credit: refund it again from Billing, '
                  || 'or ask the family for other bank details. Stripe returned it to Campistry''s platform account; '
                  || 'Campistry has been alerted to pass it back to yours.',
                'campistry_me.html')
        ON CONFLICT (camp_id, source, source_id) DO NOTHING;
        GET DIAGNOSTICS v_n = ROW_COUNT;
        v_first := v_n > 0;
    END IF;
    RETURN jsonb_build_object('success', true, 'family', true, 'familyKey', v_famKey, 'amount', v_amt,
                              'balance', public.family_ledger_balance(v_fam), 'firstNotice', v_first);
END $$;
REVOKE ALL ON FUNCTION public.reverse_failed_stripe_refund(uuid, text, text, numeric, text, text) FROM public, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.reverse_failed_stripe_refund(uuid, text, text, numeric, text, text) TO service_role;


-- ▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼
-- 279_a_stripe_autopay_answer_is_checked_with_stripe.sql
-- ▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲

-- ============================================================================
-- Migration 279: "the autopay charge went through" is checked before it is
-- recorded.
--
-- Standalone. Paste into the Supabase SQL Editor and click Run. Safe to run
-- more than once. Run it BEFORE redeploying stripe-charge, and reload Me after.
--
-- ── THE PROBLEM (TED-120, what was left) ───────────────────────────────────
-- When an autopay charge was never answered (276), the office records it with
-- the processor's reference. 276 refused a Stripe charge id (ch_) and a
-- reference booked for a DIFFERENT AMOUNT — but on an autopay night many
-- families pay the same $500, so the Stripe payments list is full of rows that
-- look alike. Pasting Silver's pi_ for Gold credited Gold twice (the next
-- instalment said "nothing owed") and showed Silver's $500 twice in the
-- exports; a mistyped pi_ did the same once Gold's real payment arrived; and
-- if Gold's charge had really failed, Gold was marked paid for money never
-- collected.
--
-- ── THE CHANGE ─────────────────────────────────────────────────────────────
--   1. Any processor: a reference already booked for ANOTHER family — on the
--      payments list or on another family's ledger — is refused, whatever the
--      amount.
--   2. Stripe: "it went through" is no longer taken from the browser at all.
--      Billing sends it to stripe-charge (redeployed), which asks Stripe for
--      that payment and records it only if it succeeded, is this family's
--      customer, is for this instalment's amount, was made on or after the day
--      autopay tried, and (when it carries Campistry's stamp) is this camp's
--      and this family's. Only then does it call
--      resolve_unconfirmed_autopay_checked, which the server alone can call.
--   "Nothing went through" is unchanged, on every processor.
-- ============================================================================

DO $$
BEGIN
    IF to_regprocedure('public.resolve_unconfirmed_autopay(uuid,text,text,boolean,text)') IS NULL THEN
        RAISE EXCEPTION '279 needs migration 276 — apply it first';
    END IF;
END $$;

-- ── the work, behind both doors (no gate of its own: never granted) ──────────
CREATE OR REPLACE FUNCTION public._record_autopay_answer(
    p_camp_id      uuid,
    p_family_key   text,
    p_plan_ref     text,
    p_went_through boolean,
    p_reference    text,
    p_from_server  boolean)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
DECLARE
    v_fam   jsonb;
    v_path  text[];
    v_plan  jsonb;
    v_hold  jsonb;
    v_ref   text := NULLIF(btrim(COALESCE(p_reference, '')), '');
    v_proc  text;
    v_amt   numeric;
    v_pay   jsonb;
    v_note  text := 'Autopay instalment — confirmed by the office (the card company never answered)';
    r       jsonb;
BEGIN
    IF p_camp_id IS NULL OR COALESCE(p_family_key, '') = '' OR COALESCE(p_plan_ref, '') = '' OR p_went_through IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'bad_arguments');
    END IF;

    v_fam := public.camp_family_for_update(p_camp_id, p_family_key);
    IF v_fam IS NULL OR jsonb_typeof(v_fam) <> 'object' THEN
        RETURN jsonb_build_object('success', false, 'error', 'family_not_found');
    END IF;
    v_path := public._plan_path(v_fam, p_plan_ref);
    IF v_path IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'plan_not_found');
    END IF;
    v_plan := v_fam #> v_path;
    v_hold := v_plan -> 'pendingCharge';
    IF v_hold IS NULL OR jsonb_typeof(v_hold) <> 'object' OR COALESCE((v_hold->>'unconfirmed')::boolean, false) IS NOT TRUE THEN
        RETURN jsonb_build_object('success', false, 'error', 'nothing_to_answer');
    END IF;

    IF p_went_through THEN
        IF v_ref IS NULL THEN
            RETURN jsonb_build_object('success', false, 'error', 'reference_required');
        END IF;
        v_proc := COALESCE(v_hold->>'processor', '');
        v_amt  := round(COALESCE((v_hold->>'amount')::numeric, 0), 2);
        IF v_amt <= 0 THEN
            RETURN jsonb_build_object('success', false, 'error', 'no_amount');
        END IF;
        -- Stripe: the payment's own id, and nothing else (TED-120).
        IF v_proc = 'stripe' AND v_ref !~ '^pi_[A-Za-z0-9]+$' THEN
            RETURN jsonb_build_object('success', false, 'error', 'stripe_needs_payment_id');
        END IF;
        -- Booked already for another family — any amount — or for this family
        -- at another amount: it is another payment.
        IF EXISTS (SELECT 1 FROM camp_payments p
                    WHERE p.camp_id = p_camp_id AND p.deleted_at IS NULL
                      AND (p.payload->>'stripePaymentIntentId' = v_ref OR p.payload->>'byopTransactionId' = v_ref
                           OR p.payload->>'reference' = v_ref)
                      AND (COALESCE(p.payload->>'familyKey', p.family_key, '') <> p_family_key
                           OR round(COALESCE((p.payload->>'amount')::numeric, 0), 2) <> v_amt))
           OR EXISTS (SELECT 1 FROM jsonb_each(public.camp_families_object(p_camp_id)) f,
                             jsonb_array_elements(CASE WHEN jsonb_typeof(f.value->'entries') = 'array'
                                                       THEN f.value->'entries' ELSE '[]'::jsonb END) e
                       WHERE f.key <> p_family_key
                         AND (e->>'id' = 'le_pay_' || v_ref OR e->'source'->>'paymentId' = v_ref)) THEN
            RETURN jsonb_build_object('success', false, 'error', 'reference_is_another_payment');
        END IF;
        -- Stripe's answer is checked with Stripe, by the server (stripe-charge).
        IF v_proc = 'stripe' AND NOT p_from_server THEN
            RETURN jsonb_build_object('success', false, 'error', 'stripe_check_needed');
        END IF;

        v_pay := jsonb_build_object(
            'id', CASE WHEN v_proc = 'stripe' THEN 'auto_' ELSE 'auto_byop_' END || v_ref,
            'familyKey', p_family_key, 'amount', v_amt,
            'date', COALESCE(v_hold->>'since', to_char(now(), 'YYYY-MM-DD')),
            'method', 'Autopay (card)', 'reference', v_ref, 'notes', v_note,
            'status', 'succeeded', 'timestamp', (extract(epoch FROM now()) * 1000)::bigint)
          || CASE WHEN v_proc = 'stripe'
                  THEN jsonb_build_object('stripePaymentIntentId', v_ref)
                  ELSE jsonb_build_object('byopTransactionId', v_ref, 'byopProcessor', v_proc) END;

        IF jsonb_typeof(v_plan->'dueDates') = 'array' AND (v_hold->>'index') IS NOT NULL THEN
            r := public.record_autopay_charge(p_camp_id, p_family_key,
                    COALESCE(NULLIF(v_hold->>'planId', ''), v_plan->>'id'),
                    (v_hold->>'index')::integer, v_hold->>'dueDate', v_amt,
                    NULL, v_pay, v_ref, v_note);
        ELSIF jsonb_typeof(v_plan->'installments') = 'array' THEN
            r := public.record_autopay_installment(p_camp_id, p_family_key,
                    NULLIF(COALESCE(NULLIF(v_hold->>'planId', ''), v_plan->>'id'), ''),
                    (v_hold->>'planIndex')::integer, v_hold->>'dueDate',
                    jsonb_build_object('status', 'paid', 'paidDate', COALESCE(v_hold->>'since', to_char(now(), 'YYYY-MM-DD')))
                      || CASE WHEN v_proc = 'stripe' THEN jsonb_build_object('stripePaymentIntentId', v_ref)
                              ELSE jsonb_build_object('byopTransactionId', v_ref) END,
                    v_pay, v_ref);
        ELSE
            RETURN jsonb_build_object('success', false, 'error', 'plan_shape_unknown');
        END IF;
        IF r IS NULL OR COALESCE((r->>'success')::boolean, false) IS NOT TRUE THEN
            RETURN jsonb_build_object('success', false, 'error', COALESCE(r->>'error', 'not_recorded'));
        END IF;
    END IF;

    -- Either way the question is answered: the hold goes.
    r := public.hold_autopay_charge(p_camp_id, p_family_key, p_plan_ref, NULL);
    IF COALESCE((r->>'success')::boolean, false) IS NOT TRUE THEN
        RETURN jsonb_build_object('success', false, 'error', COALESCE(r->>'error', 'hold_not_cleared'));
    END IF;
    RETURN jsonb_build_object('success', true, 'recorded', p_went_through);
END $$;
REVOKE ALL ON FUNCTION public._record_autopay_answer(uuid, text, text, boolean, text, boolean) FROM public, anon, authenticated;


-- ── the office's door (Billing) ─────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.resolve_unconfirmed_autopay(
    p_camp_id      uuid,
    p_family_key   text,
    p_plan_ref     text,
    p_went_through boolean,
    p_reference    text DEFAULT NULL)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
BEGIN
    IF auth.uid() IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_authenticated');
    END IF;
    -- A member of THIS camp first: the section resolver answers "edit" for a
    -- caller it cannot place at all (it leaves membership to its callers).
    IF NOT public.camp_staff_member(p_camp_id)
       OR COALESCE(public.user_section_level(p_camp_id, 'me.billing'), 'none') <> 'edit' THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_authorized');
    END IF;
    RETURN public._record_autopay_answer(p_camp_id, p_family_key, p_plan_ref, p_went_through, p_reference, false);
END $$;
REVOKE ALL ON FUNCTION public.resolve_unconfirmed_autopay(uuid, text, text, boolean, text) FROM public, anon;
GRANT EXECUTE ON FUNCTION public.resolve_unconfirmed_autopay(uuid, text, text, boolean, text) TO authenticated, service_role;


-- ── the server's door: a Stripe payment stripe-charge has checked ───────────
CREATE OR REPLACE FUNCTION public.resolve_unconfirmed_autopay_checked(
    p_camp_id    uuid,
    p_family_key text,
    p_plan_ref   text,
    p_reference  text)
RETURNS jsonb
LANGUAGE sql
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
    SELECT public._record_autopay_answer(p_camp_id, p_family_key, p_plan_ref, true, p_reference, true);
$$;
REVOKE ALL ON FUNCTION public.resolve_unconfirmed_autopay_checked(uuid, text, text, text) FROM public, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.resolve_unconfirmed_autopay_checked(uuid, text, text, text) TO service_role;


-- ▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼
-- 280_the_season_closeout_takes_the_whole_wallet.sql
-- ▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲

-- ============================================================================
-- Migration 280: the season close-out takes a child's canteen money off in
-- full, with its own write — not the till's cash-out.
--
-- Standalone. Paste into the Supabase SQL Editor and click Run. Safe to run
-- more than once. Run it BEFORE reloading Me.
--
-- ── THE PROBLEM (TED-142, TED-145, TED-143) ─────────────────────────────────
-- Me's "Close out…" took a child's canteen money off through
-- canteen_office_cash_out — the register's cash-out, with the register's
-- rules: the Snacks default of $20 cash a day per child, and the parent's
-- balance floor. So a close-out of more than $20 took nothing ("over_available")
-- and a child with a $10 floor could never be closed out in full. And a child
-- closed out kept auto-reload on, so the parent's card topped the emptied
-- wallet straight back up.
--
-- ── THE CHANGE ─────────────────────────────────────────────────────────────
-- canteen_season_closeout takes up to the WHOLE balance (never more), under the
-- wallet's lock, whatever the till's daily cash limit or the parent's floor —
-- the floor limits what a child may SPEND; at the end of the season the money
-- goes back to the family. It posts one 'closeout' line on the child's
-- history, switches the child's auto-reload off (saying why, for the parent's
-- Link page), and answers in words.
--
-- Only a member of the camp who can edit Billing can call it (the same rule as
-- the rest of Me's billing actions).
-- ============================================================================

DO $$
BEGIN
    IF to_regprocedure('public.canteen_account_lock(uuid,text)') IS NULL
       OR to_regprocedure('public.canteen_post(uuid,text,jsonb,text)') IS NULL
       OR to_regprocedure('public.camp_person_name_for(uuid,bigint)') IS NULL
       OR to_regprocedure('public.camp_staff_member(uuid)') IS NULL
       OR to_regprocedure('public.user_section_level(uuid,text)') IS NULL THEN
        RAISE EXCEPTION '280 needs migrations 219, 227, 257 and the access resolver — apply those first';
    END IF;
END $$;

CREATE OR REPLACE FUNCTION public.canteen_season_closeout(
    p_camp_id     uuid,
    p_camper_id   bigint,
    p_camper_name text,
    p_amount      numeric,
    p_note        text DEFAULT NULL)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
DECLARE
    v_name  text := NULLIF(btrim(COALESCE(p_camper_name, '')), '');
    v_amt   numeric := round(COALESCE(p_amount, 0), 2);
    v_acct  jsonb;
    v_bal   numeric;
    v_ar    jsonb;
    v_note  text := COALESCE(NULLIF(btrim(COALESCE(p_note, '')), ''), 'Season close-out');
    now_ts  timestamptz := now();
BEGIN
    IF auth.uid() IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_authenticated',
                                  'message', 'Not signed in.');
    END IF;
    IF NOT public.camp_staff_member(p_camp_id)
       OR COALESCE(public.user_section_level(p_camp_id, 'me.billing'), 'none') <> 'edit' THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_authorized',
                                  'message', 'Only someone who can edit Billing can close out canteen money.');
    END IF;
    IF p_camper_id IS NOT NULL THEN
        -- The number decides, pinned for this call (257).
        v_name := public.camp_person_name_for(p_camp_id, p_camper_id);
        IF v_name IS NULL THEN
            RETURN jsonb_build_object('success', false, 'error', 'unknown_camper',
                                      'message', 'That child is not on this camp''s roster.');
        END IF;
    END IF;
    IF v_name IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'missing_camper', 'message', 'Which child?');
    END IF;
    IF v_amt <= 0 THEN
        RETURN jsonb_build_object('success', false, 'error', 'invalid_amount', 'message', 'Nothing to close out.');
    END IF;

    v_acct := public.canteen_account_lock(p_camp_id, v_name);
    IF v_acct IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'no_canteen_account',
                                  'message', 'This child has no canteen account.');
    END IF;
    v_bal := round(COALESCE(NULLIF(v_acct ->> 'balance', '')::numeric, 0), 2);
    -- The whole balance, never more — no till limit, no floor (TED-142/145).
    IF v_amt > v_bal THEN
        RETURN jsonb_build_object('success', false, 'error', 'over_balance', 'balance', v_bal,
            'message', 'Only $' || to_char(GREATEST(v_bal, 0), 'FM999999990.00') || ' is on the canteen account now — reopen the close-out to see the current figure.');
    END IF;

    v_bal := round(v_bal - v_amt, 2);
    v_acct := v_acct || jsonb_build_object('balance', v_bal);
    -- Auto-reload off (TED-143): the wallet is being emptied for the season.
    v_ar := v_acct -> 'autoReload';
    IF jsonb_typeof(v_ar) = 'object' AND COALESCE((v_ar ->> 'enabled')::boolean, false) THEN
        v_acct := jsonb_set(v_acct, '{autoReload}', v_ar || jsonb_build_object(
            'enabled', false,
            'disabledAt', to_char(now_ts, 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
            'disabledReason', 'switched off when the camp closed out the canteen balance for the season — switch it back on if you still want it'), true);
    END IF;
    PERFORM public.canteen_account_save(p_camp_id, v_name, v_acct);
    PERFORM public.canteen_post(p_camp_id, v_name,
        jsonb_build_object(
            'time',   to_char(now_ts, 'HH12:MI AM'),
            'camper', v_name,
            'items',  v_note,
            'amount', v_amt,
            'type',   'debit',
            'kind',   'closeout',
            'note',   v_note,
            'by',     'office (close-out)',
            'date',   to_char(now_ts, 'YYYY-MM-DD'),
            'timestamp', (extract(epoch FROM now_ts) * 1000)::bigint)
        || CASE WHEN p_camper_id IS NOT NULL THEN jsonb_build_object('camperId', p_camper_id) ELSE '{}'::jsonb END);
    RETURN jsonb_build_object('success', true, 'balance', v_bal, 'amount', v_amt, 'camper', v_name);
END $$;
REVOKE ALL ON FUNCTION public.canteen_season_closeout(uuid, bigint, text, numeric, text) FROM public, anon;
GRANT EXECUTE ON FUNCTION public.canteen_season_closeout(uuid, bigint, text, numeric, text) TO authenticated, service_role;


-- ▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼
-- 281_a_failed_refund_takes_its_surcharge_share_back.sql
-- ▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲

-- ============================================================================
-- Migration 281: a refund that fails later takes its card-surcharge share back
-- off the family's bill; and the platform's failed-refund email is sent again
-- when it did not go.
--
-- Standalone. Paste into the Supabase SQL Editor and click Run. Safe to run
-- more than once. Run it BEFORE deploying stripe-webhook and reloading Me.
--
-- ── THE PROBLEMS ───────────────────────────────────────────────────────────
-- TED-148. Slate paid $1,030 ($1,000 + a $30 card surcharge). The office
-- refunded $1,000, and Billing took $29.13 of the surcharge off Slate's bill
-- (the card brands' rule: the fee goes back in proportion). Three days later
-- Stripe failed the refund and 278 put the $1,000 back — but the $29.13 stayed
-- credited, so Slate showed $29.13 in credit for a refund that never reached
-- the card.
--
-- TED-150. The platform is emailed once per failed refund (TED-137), and the
-- "once" was claimed BEFORE the email was sent. One email-service hiccup and
-- the alert was never sent: every later delivery of the same failure found it
-- already claimed.
--
-- ── THE CHANGES ────────────────────────────────────────────────────────────
-- undo_card_fee_return(camp, family, refund): Billing now tags each surcharge
-- credit with the refund it went with (refundId). When that refund fails, this
-- puts a charge of the same amount back on the bill ("Card surcharge back on
-- the bill — the refund it went with failed"), on the family's charges and its
-- ledger, once per credit. stripe-webhook calls it right after 278's put-back.
-- Likewise the "not paying by card" discount Billing took back with a refund
-- (TED-160) is given back to the family as a credit when that refund fails.
--
-- release_refund_failure_alert(refund): gives back the once-only claim when
-- the email did not send, so the next delivery of the failure sends it.
--
-- Both are for the webhook only (service role).
-- ============================================================================

DO $$
BEGIN
    IF to_regprocedure('public.camp_family_for_update(uuid,text)') IS NULL
       OR to_regprocedure('public.camp_family_save(uuid,text,jsonb)') IS NULL
       OR to_regprocedure('public._sync_charge_to_ledger(jsonb,text)') IS NULL
       OR to_regclass('public.refund_failure_alerts') IS NULL THEN
        RAISE EXCEPTION '281 needs migrations 213, 263 and 278 — apply those first';
    END IF;
END $$;

CREATE OR REPLACE FUNCTION public.undo_card_fee_return(
    p_camp_id    uuid,
    p_family_key text,
    p_refund_id  text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
DECLARE
    v_ref    text := NULLIF(btrim(COALESCE(p_refund_id, '')), '');
    v_fam    jsonb;
    v_chg    jsonb;
    c        jsonb;
    v_id     text;
    v_amt    numeric;
    v_total  numeric := 0;
    v_back   numeric := 0;
    v_cr     jsonb;
    v_n      integer := 0;
    now_ts   timestamptz := now();
BEGIN
    IF p_camp_id IS NULL OR NULLIF(btrim(COALESCE(p_family_key, '')), '') IS NULL OR v_ref IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'missing_argument');
    END IF;
    v_fam := public.camp_family_for_update(p_camp_id, p_family_key);
    IF v_fam IS NULL OR jsonb_typeof(v_fam) <> 'object' THEN
        RETURN jsonb_build_object('success', false, 'error', 'family_not_found');
    END IF;
    FOR c IN SELECT * FROM jsonb_array_elements(CASE WHEN jsonb_typeof(v_fam -> 'credits') = 'array'
                                                     THEN v_fam -> 'credits' ELSE '[]'::jsonb END) LOOP
        IF jsonb_typeof(c) <> 'object'
           OR COALESCE(c ->> 'cardFeeReturn', '') <> 'true'
           OR c ->> 'refundId' IS DISTINCT FROM v_ref THEN
            CONTINUE;
        END IF;
        v_id := 'cfr_undo_' || COALESCE(c ->> 'id', v_ref);
        v_chg := CASE WHEN jsonb_typeof(v_fam -> 'charges') = 'array' THEN v_fam -> 'charges' ELSE '[]'::jsonb END;
        -- once per credit, however many times Stripe sends the failure
        IF EXISTS (SELECT 1 FROM jsonb_array_elements(v_chg) x WHERE x ->> 'id' = v_id) THEN CONTINUE; END IF;
        v_amt := round(COALESCE(NULLIF(c ->> 'amount', '')::numeric, 0), 2);
        IF v_amt <= 0 THEN CONTINUE; END IF;
        v_fam := jsonb_set(v_fam, '{charges}', v_chg || jsonb_build_array(jsonb_build_object(
            'id',          v_id,
            'category',    'Card Fee',
            'description', 'Card surcharge back on the bill — the refund it went with (' || v_ref || ') failed, so the family kept the payment',
            'amount',      v_amt,
            'date',        to_char(now_ts, 'YYYY-MM-DD'),
            'timestamp',   (extract(epoch FROM now_ts) * 1000)::bigint,
            'cardFeeUndo', true,
            'refundId',    v_ref,
            'creditId',    c ->> 'id')), true);
        -- the ledger, the way Billing posts any charge (263): le_chg_<id>
        v_fam := public._sync_charge_to_ledger(v_fam, v_id);
        v_total := v_total + v_amt;
        v_n := v_n + 1;
    END LOOP;

    -- The "not paying by card" discount Billing took back with this refund
    -- (TED-160) goes back to the family too: the refund never happened. A
    -- credit, on the family's credits and its ledger, once per charge.
    FOR c IN SELECT * FROM jsonb_array_elements(CASE WHEN jsonb_typeof(v_fam -> 'charges') = 'array'
                                                     THEN v_fam -> 'charges' ELSE '[]'::jsonb END) LOOP
        IF jsonb_typeof(c) <> 'object'
           OR COALESCE(c ->> 'cashDiscountBack', '') <> 'true'
           OR c ->> 'refundId' IS DISTINCT FROM v_ref THEN
            CONTINUE;
        END IF;
        v_id := 'cdback_undo_' || COALESCE(c ->> 'id', v_ref);
        v_cr := CASE WHEN jsonb_typeof(v_fam -> 'credits') = 'array' THEN v_fam -> 'credits' ELSE '[]'::jsonb END;
        IF EXISTS (SELECT 1 FROM jsonb_array_elements(v_cr) x WHERE x ->> 'id' = v_id) THEN CONTINUE; END IF;
        v_amt := round(COALESCE(NULLIF(c ->> 'amount', '')::numeric, 0), 2);
        IF v_amt <= 0 THEN CONTINUE; END IF;
        v_fam := jsonb_set(v_fam, '{credits}', v_cr || jsonb_build_array(jsonb_build_object(
            'id',       v_id,
            'amount',   v_amt,
            'reason',   'reversal',
            'note',     'Discount for not paying by card given back — the refund it went with (' || v_ref || ') failed',
            'date',     to_char(now_ts, 'YYYY-MM-DD'),
            'timestamp', (extract(epoch FROM now_ts) * 1000)::bigint,
            'cashDiscountUndo', true,
            'refundId', v_ref,
            'chargeId', c ->> 'id')), true);
        -- on the ledger the way Billing posts a credit (le_<credit id>), when
        -- the family has one
        IF jsonb_typeof(v_fam -> 'entries') = 'array' AND jsonb_array_length(v_fam -> 'entries') > 0
           AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(v_fam -> 'entries') e WHERE e ->> 'id' = 'le_' || v_id) THEN
            v_fam := jsonb_set(v_fam, '{entries}', (v_fam -> 'entries') || jsonb_build_array(jsonb_build_object(
                'id',       'le_' || v_id,
                'kind',     'credit',
                'amount',   v_amt,
                'reason',   'reversal',
                'date',     to_char(now_ts, 'YYYY-MM-DD'),
                'postedAt', to_char(now_ts AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
                'note',     'Discount given back — the refund it went with failed',
                'by',       'system',
                'source',   jsonb_build_object('creditId', v_id))), true);
        END IF;
        v_back := v_back + v_amt;
        v_n := v_n + 1;
    END LOOP;

    IF v_n > 0 THEN
        PERFORM public.camp_family_save(p_camp_id, p_family_key, v_fam);
    END IF;
    RETURN jsonb_build_object('success', true, 'undone', v_n, 'amount', v_total, 'discountBack', v_back);
END $$;
REVOKE ALL ON FUNCTION public.undo_card_fee_return(uuid, text, text) FROM public, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.undo_card_fee_return(uuid, text, text) TO service_role;

CREATE OR REPLACE FUNCTION public.release_refund_failure_alert(p_refund_id text)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
DECLARE v_n integer := 0;
BEGIN
    DELETE FROM refund_failure_alerts WHERE refund_id = p_refund_id;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    RETURN v_n > 0;
END $$;
REVOKE ALL ON FUNCTION public.release_refund_failure_alert(text) FROM public, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.release_refund_failure_alert(text) TO service_role;


-- ▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼
-- 282_a_parent_save_clears_the_camps_pause_note.sql
-- ▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲

-- ============================================================================
-- Migration 282: when a parent saves their child's auto-reload in Link, the
-- note "switched off when the camp refunded the canteen balance" goes.
--
-- Standalone. Paste into the Supabase SQL Editor and click Run. Safe to run
-- more than once. Run it before reloading Link.
--
-- ── THE PROBLEM (TED-156) ──────────────────────────────────────────────────
-- A refund that empties a child's wallet (or the season close-out) switches
-- that child's auto-reload off and leaves a note saying why, which Link shows
-- the parent (TED-143). The note was never taken away: after the parent
-- switched auto-reload back on, and later turned it off themselves, Link still
-- said "the camp switched it off".
--
-- ── THE CHANGE ─────────────────────────────────────────────────────────────
-- Any save the parent makes (set_canteen_auto_reload, migration 231) drops
-- the camp's note (disabledReason, disabledAt): from then on the setting is
-- the parent's own.
-- ============================================================================

DO $$
DECLARE
    d   text;
    old text := $o$    v_acct  := jsonb_set(v_acct, '{autoReload}', v_ar, true);$o$;
    new text := $n$    -- A parent's save: the camp's "why it was switched off" note goes (282).
    v_ar := (v_ar - 'disabledReason') - 'disabledAt';
    v_acct  := jsonb_set(v_acct, '{autoReload}', v_ar, true);$n$;
BEGIN
    IF to_regprocedure('public.set_canteen_auto_reload(uuid,text,jsonb,bigint)') IS NULL THEN
        RAISE EXCEPTION '282 needs migration 231 — apply it first';
    END IF;
    d := pg_get_functiondef('public.set_canteen_auto_reload(uuid,text,jsonb,bigint)'::regprocedure);
    IF position('disabledReason' IN d) > 0 THEN
        RAISE NOTICE '282: set_canteen_auto_reload already clears the note';
        RETURN;
    END IF;
    IF position(old IN d) = 0 THEN
        RAISE EXCEPTION '282: set_canteen_auto_reload does not look the way this file expects — send this message to the builder';
    END IF;
    EXECUTE replace(d, old, new);
END $$;


-- ▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼
-- 283_a_register_sale_is_charged_once.sql
-- ▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲

-- ============================================================================
-- Migration 283: a canteen register sale is charged once, however often the
-- Charge button's request arrives.
--
-- Standalone. Paste into the Supabase SQL Editor and click Run. Safe to run
-- more than once. Run it BEFORE reloading the Snacks register (POS).
--
-- ── THE PROBLEM (TED-159) ──────────────────────────────────────────────────
-- Every call to submit_canteen_purchase is a new debit. On slow camp wifi a
-- counselor tapped "Charge $2.50" twice and the child was charged twice; or
-- the answer was lost after the server had charged, the register said "Charge
-- failed", the counselor tapped again — charged twice.
--
-- ── THE CHANGE ─────────────────────────────────────────────────────────────
-- The register sends a key for each sale it means to make (the same key on a
-- retry of that sale). submit_canteen_purchase_once remembers the answer of a
-- sale that went through under its key, for this camp, and answers a repeat
-- with that first answer (replayed: true) instead of charging again. Two
-- requests with the same key at the same moment: the second waits for the
-- first and gets its answer. A sale that was refused (over the daily limit,
-- not enough balance) is not remembered, so it can be tried again. A key sent
-- again for a DIFFERENT child or amount is refused.
--
-- submit_canteen_purchase itself is unchanged (247); this calls it.
-- ============================================================================

DO $$
BEGIN
    IF to_regprocedure('public.submit_canteen_purchase(uuid,text,numeric,text,date,bigint)') IS NULL
       OR to_regprocedure('public.camp_staff_member(uuid)') IS NULL THEN
        RAISE EXCEPTION '283 needs migration 247 — apply it first';
    END IF;
END $$;

CREATE TABLE IF NOT EXISTS public.canteen_sale_keys (
    camp_id     uuid        NOT NULL,
    sale_key    text        NOT NULL,
    fingerprint text        NOT NULL,
    result      jsonb,
    created_at  timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (camp_id, sale_key)
);
ALTER TABLE public.canteen_sale_keys ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.canteen_sale_keys FROM public, anon, authenticated;

CREATE OR REPLACE FUNCTION public.submit_canteen_purchase_once(
    p_camp_id     uuid,
    p_sale_key    text,
    p_camper_name text,
    p_amount      numeric,
    p_items       text   DEFAULT '',
    p_date        date   DEFAULT NULL,
    p_camper_id   bigint DEFAULT NULL)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
DECLARE
    v_key  text := NULLIF(btrim(COALESCE(p_sale_key, '')), '');
    v_fp   text := COALESCE(p_camper_id::text, 'n:' || btrim(COALESCE(p_camper_name, ''))) || '|' || round(COALESCE(p_amount, 0), 2)::text;
    v_n    integer := 0;
    v_prev public.canteen_sale_keys%ROWTYPE;
    r      jsonb;
BEGIN
    IF auth.uid() IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'not_authenticated'); END IF;
    IF p_camp_id IS NULL OR NOT public.camp_staff_member(p_camp_id) THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_authorized');
    END IF;
    IF v_key IS NULL THEN
        RETURN public.submit_canteen_purchase(p_camp_id, p_camper_name, p_amount, p_items, p_date, p_camper_id);
    END IF;

    -- A few days is all a retry ever needs.
    DELETE FROM canteen_sale_keys WHERE camp_id = p_camp_id AND created_at < now() - interval '3 days';

    -- Claim the key. A second request with the same key waits here until the
    -- first has finished, then finds its row.
    INSERT INTO canteen_sale_keys (camp_id, sale_key, fingerprint) VALUES (p_camp_id, v_key, v_fp)
        ON CONFLICT (camp_id, sale_key) DO NOTHING;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    IF v_n = 0 THEN
        SELECT * INTO v_prev FROM canteen_sale_keys WHERE camp_id = p_camp_id AND sale_key = v_key;
        IF v_prev.fingerprint IS DISTINCT FROM v_fp THEN
            RETURN jsonb_build_object('success', false, 'error', 'sale_key_reused');
        END IF;
        IF v_prev.result IS NOT NULL THEN
            RETURN v_prev.result || jsonb_build_object('replayed', true);
        END IF;
        -- Not reachable once the first request has finished (it either kept
        -- its answer or gave the key back) — never charge on a guess.
        RETURN jsonb_build_object('success', false, 'error', 'sale_in_progress');
    END IF;

    r := public.submit_canteen_purchase(p_camp_id, p_camper_name, p_amount, p_items, p_date, p_camper_id);
    IF COALESCE((r ->> 'success')::boolean, false) THEN
        UPDATE canteen_sale_keys SET result = r WHERE camp_id = p_camp_id AND sale_key = v_key;
    ELSE
        -- Nothing was charged: the same sale may be tried again.
        DELETE FROM canteen_sale_keys WHERE camp_id = p_camp_id AND sale_key = v_key;
    END IF;
    RETURN r;
END $$;
REVOKE ALL ON FUNCTION public.submit_canteen_purchase_once(uuid, text, text, numeric, text, date, bigint) FROM public, anon;
GRANT EXECUTE ON FUNCTION public.submit_canteen_purchase_once(uuid, text, text, numeric, text, date, bigint) TO authenticated;

-- Pasted again after 289 (which added the sold items and replaced this
-- signature): keep only 289's, or the API cannot choose between the two.
DO $$
BEGIN
    IF to_regprocedure('public.submit_canteen_purchase_once(uuid,text,text,numeric,text,date,bigint,jsonb)') IS NOT NULL THEN
        DROP FUNCTION IF EXISTS public.submit_canteen_purchase_once(uuid, text, text, numeric, text, date, bigint);
        RAISE NOTICE '283: 289''s version is in place — kept it';
    END IF;
END $$;


-- ▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼
-- 284_a_register_sale_can_be_voided.sql
-- ▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲

-- ============================================================================
-- Migration 284: a register sale made by mistake can be voided — the money
-- goes back on the child's canteen balance as the reversal of THAT sale, and
-- the items go back in stock. Not as a deposit.
--
-- Standalone. Paste into the Supabase SQL Editor and click Run. Safe to run
-- more than once. Run it BEFORE reloading Snacks.
--
-- ── THE PROBLEM (TED-175) ──────────────────────────────────────────────────
-- A child charged by mistake — the wrong child, the wrong item, a double tap —
-- could only be given the money back with Add Deposit, which records "$2.50
-- paid in by cash" (or card). The cash drawer, the day's takings and the
-- deposit reports then showed money that never came in, and the mistaken sale
-- still counted as a sale.
--
-- ── THE CHANGE ─────────────────────────────────────────────────────────────
-- canteen_void_sale(camp, sale, items to restock, note): for staff who can edit
-- Snacks accounts (the same rule as the desk's other writes, 240). It finds the
-- sale by its row (every ledger row the page reads carries its `sig`), under
-- the child's wallet lock:
--   • only a register sale (in person or imported from the offline register)
--     — not a deposit, a refund, a cash-out, a close-out or a Shop order (the
--     Shop refunds its own orders);
--   • once: a second void of the same sale is refused ("already voided");
--   • puts the amount back on the balance, and back on today's spending if the
--     sale was today, so the child's daily limit is freed too;
--   • posts one line, kind 'void', a credit that names the sale it reverses
--     (voidOf) — with no payment method, so it is never cash or card taken in;
--   • puts the items the office ticked back in stock (and off "sold") — never
--     more of an item than the sale had (TED-184): by item id where the
--     register recorded them (289, TED-192), by the sale's item line otherwise.
-- The page leaves a voided sale out of sales and revenue.
--
-- get_canteen_history now carries each row's `sig` too, so a sale from the
-- archive, or one re-read after a desk write, can be voided as well.
-- ============================================================================

DO $$
BEGIN
    IF to_regprocedure('public.canteen_account_lock(uuid,text)') IS NULL
       OR to_regprocedure('public.canteen_account_save(uuid,text,jsonb)') IS NULL
       OR to_regprocedure('public.canteen_post(uuid,text,jsonb,text)') IS NULL
       OR to_regprocedure('public._canteen_office_may_edit(uuid)') IS NULL
       OR COALESCE(to_regprocedure('public._get_canteen_history__by_name(uuid,text,text,integer)'),
                   to_regprocedure('public.get_canteen_history(uuid,text,text,integer)')) IS NULL THEN
        RAISE EXCEPTION '284 needs migrations 227 and 240 — apply those first';
    END IF;
END $$;

CREATE OR REPLACE FUNCTION public.canteen_void_sale(
    p_camp_id uuid,
    p_sig     text,
    p_restock jsonb DEFAULT '[]'::jsonb,   -- [{"id": <inventory id>, "qty": n}]
    p_note    text  DEFAULT NULL)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
DECLARE
    v_sig    text := NULLIF(btrim(COALESCE(p_sig, '')), '');
    t        canteen_transactions%ROWTYPE;
    v_kind   text;
    v_acct   jsonb;
    v_bal    numeric;
    v_spent  numeric;
    v_amt    numeric;
    v_today  text := (now() AT TIME ZONE 'utc')::date::text;
    v_note   text := NULLIF(btrim(COALESCE(p_note, '')), '');
    v_back   integer := 0;
    v_sold_today boolean;
    now_ts   timestamptz := now();
BEGIN
    IF auth.uid() IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_authenticated', 'message', 'Not signed in.');
    END IF;
    IF NOT public._canteen_office_may_edit(p_camp_id) THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_authorized',
                                  'message', 'Only someone who can edit Snacks accounts can void a sale.');
    END IF;
    IF v_sig IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'sale_not_found', 'message', 'Which sale?');
    END IF;

    SELECT * INTO t FROM canteen_transactions WHERE camp_id = p_camp_id AND sig = v_sig;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'sale_not_found',
                                  'message', 'That sale is not on this camp''s ledger.');
    END IF;
    v_kind := COALESCE(t.payload ->> 'kind', '');
    IF t.tx_type <> 'debit' OR v_kind NOT IN ('', 'sale', 'offline_sale') THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_a_sale',
            'message', CASE WHEN v_kind = 'shop' THEN 'That is a Shop order — refund it from the Shop.'
                            ELSE 'Only a register sale can be voided.' END);
    END IF;
    v_amt := round(COALESCE(t.amount, 0), 2);
    IF v_amt <= 0 THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_a_sale', 'message', 'Only a register sale can be voided.');
    END IF;

    -- The child's wallet lock: two voids of the same sale wait here, and the
    -- second finds the first one's line.
    v_acct := public.canteen_account_lock(p_camp_id, t.camper);
    IF v_acct IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'no_canteen_account',
                                  'message', 'This child has no canteen account.');
    END IF;
    IF EXISTS (SELECT 1 FROM canteen_transactions WHERE camp_id = p_camp_id AND sig = 'void:' || v_sig) THEN
        RETURN jsonb_build_object('success', false, 'error', 'already_voided',
                                  'message', 'That sale was already voided — the money is back on the balance.');
    END IF;

    v_bal := round(COALESCE(NULLIF(v_acct ->> 'balance', '')::numeric, 0) + v_amt, 2);
    v_acct := v_acct || jsonb_build_object('balance', v_bal);
    -- A sale from today also comes off today's spending, so the daily limit it
    -- used is free again.
    IF t.tx_date = COALESCE(v_acct ->> 'lastSpendDate', '') THEN
        v_spent := GREATEST(0, round(COALESCE(NULLIF(v_acct ->> 'spentToday', '')::numeric, 0) - v_amt, 2));
        v_acct := v_acct || jsonb_build_object('spentToday', v_spent);
    END IF;
    PERFORM public.canteen_account_save(p_camp_id, t.camper, v_acct);

    PERFORM public.canteen_post(p_camp_id, t.camper,
        jsonb_build_object(
            'time',    to_char(now_ts, 'HH12:MI AM'),
            'camper',  COALESCE(NULLIF(t.payload ->> 'camper', ''), t.camper),
            'items',   'Sale voided: ' || COALESCE(NULLIF(t.items, ''), 'purchase') || ' (' || t.tx_date || ')',
            'amount',  v_amt,
            'type',    'credit',
            'kind',    'void',
            'voidOf',  v_sig,
            'saleDate', t.tx_date,
            'note',    COALESCE(v_note, 'Charged by mistake'),
            'by',      'office (void)',
            'date',    v_today,
            'timestamp', (extract(epoch FROM now_ts) * 1000)::bigint)
        || CASE WHEN t.camper_id IS NOT NULL AND t.camper_id ~ '^[0-9]+$'
                THEN jsonb_build_object('camperId', t.camper_id::bigint) ELSE '{}'::jsonb END,
        'void:' || v_sig);

    -- The items back in stock, and off "sold" (off "sold today" only for a
    -- sale made today). One UPDATE computed from the row it writes — no lock
    -- held on the camp's whole Snacks document (219's rule: every register
    -- would queue behind it).
    IF jsonb_typeof(p_restock) = 'array' AND jsonb_array_length(p_restock) > 0 THEN
        v_sold_today := t.tx_date = v_today;
        -- Never more than the sale had (TED-184): what was sold, from the
        -- sale's own line ("Ices ×2, Chips"), by item name; what the page asks
        -- to restock is capped at that, item by item.
        WITH sale_items AS (
            SELECT lower(btrim(COALESCE(m[1], part))) AS name,
                   sum(COALESCE(m[2]::numeric, 1)) AS qty
              FROM (SELECT btrim(p) AS part FROM regexp_split_to_table(COALESCE(t.items, ''), ',') AS p) parts
              LEFT JOIN LATERAL (SELECT regexp_match(parts.part, '^(.*?)\s*[×x]\s*([0-9]+)$') AS m) mm ON true
             WHERE parts.part <> ''
             GROUP BY 1),
        asked AS (
            SELECT it ->> 'id' AS id, sum(floor((it ->> 'qty')::numeric)) AS qty
              FROM jsonb_array_elements(p_restock) it
             WHERE jsonb_typeof(it) = 'object' AND it ->> 'id' IS NOT NULL
               AND jsonb_typeof(it -> 'qty') = 'number'
               AND floor((it ->> 'qty')::numeric) BETWEEN 1 AND 100
             GROUP BY 1),
        -- What the register recorded it sold, by item id (289, TED-192): that
        -- when the sale has it; the item line by name for older sales.
        sold_by_id AS (
            SELECT x ->> 'id' AS id, sum(COALESCE(NULLIF(x ->> 'qty', '')::numeric, 0)) AS qty
              FROM jsonb_array_elements(CASE WHEN jsonb_typeof(t.payload -> 'soldItems') = 'array'
                                             THEN t.payload -> 'soldItems' ELSE '[]'::jsonb END) x
             WHERE jsonb_typeof(x) = 'object'
             GROUP BY 1),
        back AS (
            SELECT a.id, LEAST(a.qty, COALESCE(
                       CASE WHEN jsonb_typeof(t.payload -> 'soldItems') = 'array'
                            THEN (SELECT sb.qty FROM sold_by_id sb WHERE sb.id = a.id)
                            ELSE (SELECT si.qty
                                    FROM camp_state_kv kv0
                                    JOIN LATERAL (SELECT e FROM jsonb_array_elements(CASE WHEN jsonb_typeof(kv0.value -> 'inventory') = 'array'
                                                                                          THEN kv0.value -> 'inventory' ELSE '[]'::jsonb END) e
                                                   WHERE e ->> 'id' = a.id LIMIT 1) inv ON true
                                    JOIN sale_items si ON si.name = lower(btrim(COALESCE(inv.e ->> 'name', '')))
                                   WHERE kv0.camp_id = p_camp_id AND kv0.key = 'campistrySnacks') END, 0)) AS qty
              FROM asked a)
        UPDATE camp_state_kv kv
           SET value = jsonb_set(kv.value, '{inventory}', (
                   SELECT COALESCE(jsonb_agg(
                       CASE WHEN b.qty IS NOT NULL THEN
                           e || jsonb_build_object(
                               'stock', CASE WHEN jsonb_typeof(e -> 'stock') = 'number'
                                             THEN to_jsonb((e ->> 'stock')::numeric + b.qty)
                                             ELSE e -> 'stock' END,
                               'soldToday', CASE WHEN v_sold_today
                                                 THEN to_jsonb(GREATEST(0, COALESCE(NULLIF(e ->> 'soldToday', '')::numeric, 0) - b.qty))
                                                 ELSE COALESCE(e -> 'soldToday', '0'::jsonb) END,
                               'totalSold', to_jsonb(GREATEST(0, COALESCE(NULLIF(e ->> 'totalSold', '')::numeric, 0) - b.qty)))
                       ELSE e END ORDER BY x.ord), '[]'::jsonb)
                     FROM jsonb_array_elements(kv.value -> 'inventory') WITH ORDINALITY AS x(e, ord)
                     LEFT JOIN back b ON b.id = x.e ->> 'id'), true),
               updated_at = now_ts
         WHERE kv.camp_id = p_camp_id AND kv.key = 'campistrySnacks'
           AND jsonb_typeof(kv.value -> 'inventory') = 'array'
        RETURNING (SELECT COALESCE(sum(b.qty), 0)::integer
                     FROM back b
                    WHERE EXISTS (SELECT 1 FROM jsonb_array_elements(kv.value -> 'inventory') e WHERE e ->> 'id' = b.id))
          INTO v_back;
        v_back := COALESCE(v_back, 0);
    END IF;

    RETURN jsonb_build_object('success', true, 'balance', v_bal, 'amount', v_amt,
        'camper', COALESCE(NULLIF(t.payload ->> 'camper', ''), t.camper),
        'camperId', t.camper_id, 'restocked', v_back,
        'spentToday', v_acct -> 'spentToday', 'dailyLimit', v_acct -> 'dailyLimit');
END $$;
REVOKE ALL ON FUNCTION public.canteen_void_sale(uuid, text, jsonb, text) FROM public, anon;
GRANT EXECUTE ON FUNCTION public.canteen_void_sale(uuid, text, jsonb, text) TO authenticated;

-- get_canteen_history: each row with its sig, as get_canteen_accounts (245)
-- already gives it, so any row the page shows can be named to the server.
-- Since 248 its body lives in _get_canteen_history__by_name (the public name
-- is the wrapper that also takes a camper id); a camp that unwrapped 248 has
-- it under the public name.
DO $$
DECLARE
    f   regprocedure := COALESCE(to_regprocedure('public._get_canteen_history__by_name(uuid,text,text,integer)'),
                                 to_regprocedure('public.get_canteen_history(uuid,text,text,integer)'));
    d   text;
    a1  text := 'jsonb_agg(x.payload ORDER BY x.tx_date DESC, x.first_seen DESC)';
    b1  text := 'jsonb_agg(x.payload || jsonb_build_object(''sig'', x.sig) ORDER BY x.tx_date DESC, x.first_seen DESC)';
    a2  text := 'SELECT ct.payload, ct.tx_date, ct.first_seen';
    b2  text := 'SELECT ct.payload, ct.sig, ct.tx_date, ct.first_seen';
BEGIN
    d := pg_get_functiondef(f);
    IF position('''sig'', x.sig' IN d) > 0 THEN
        RAISE NOTICE '284: get_canteen_history already carries sig';
        RETURN;
    END IF;
    IF position(a1 IN d) = 0 OR position(a2 IN d) = 0 THEN
        RAISE EXCEPTION '284: get_canteen_history does not look the way this file expects — send this message to the builder';
    END IF;
    EXECUTE replace(replace(d, a1, b1), a2, b2);
END $$;


-- ▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼
-- 285_a_refunded_or_disputed_tip.sql
-- ▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲

-- ============================================================================
-- Migration 285: a staff tip the parent got back — refunded in Stripe, or
-- disputed with their bank — is marked on the tip, comes off the staff
-- member's total, and the platform is told once what to do next.
--
-- Standalone. Paste into the Supabase SQL Editor and click Run. Safe to run
-- more than once. Run it BEFORE deploying stripe-connect-webhook.
--
-- ── THE PROBLEM (TED-176) ──────────────────────────────────────────────────
-- A tip is charged on Campistry's own Stripe account and the tip part is sent
-- on to the staff member's Stripe account (a destination charge, or one
-- transfer per staff member for a cart of tips). When a tip was refunded, or a
-- parent disputed it, nothing in Campistry noticed: the tip stayed on the staff
-- member's record and total, and Stripe took the refund or the chargeback (and
-- its dispute fee) from Campistry's balance, with no one asking for the tip back.
--
-- ── THE CHANGE ─────────────────────────────────────────────────────────────
-- link_tips gains:
--   refunded_amount     this tip's share of what Stripe refunded to the parent
--   dispute_status      open | won | lost (null: never disputed)
--   clawed_back_amount  how much of the transfer to the staff member has been
--                       reversed (taken back from their Stripe account)
--   reversal_note       what could not be done automatically, in words
--   reversal_alerted    the state the platform was last emailed about
--
-- record_tip_reversal(tip, refunded, dispute status, clawed back, note): for
-- stripe-connect-webhook only (service role). Under the tip's row lock it
-- records the new state — refunds and clawbacks only ever go up — and takes
-- the change in what the staff member lost off their total_earned (the whole
-- tip while a dispute is open or lost; the refunded share otherwise), so a
-- repeated delivery of the same event changes nothing. It answers with the
-- state the platform should be told about, and whether it already was.
--
-- mark_tip_reversal_alerted(tip, state): the webhook marks the state once the
-- email went, so an email that failed is sent again on Stripe's retry.
-- ============================================================================

DO $$
BEGIN
    IF to_regclass('public.link_tips') IS NULL OR to_regclass('public.link_staff_accounts') IS NULL THEN
        RAISE EXCEPTION '285 needs migrations 016 and 057 (tips and staff accounts) — apply those first';
    END IF;
END $$;

ALTER TABLE public.link_tips ADD COLUMN IF NOT EXISTS refunded_amount    numeric(8,2) NOT NULL DEFAULT 0;
ALTER TABLE public.link_tips ADD COLUMN IF NOT EXISTS dispute_status     text;
ALTER TABLE public.link_tips ADD COLUMN IF NOT EXISTS clawed_back_amount numeric(8,2) NOT NULL DEFAULT 0;
ALTER TABLE public.link_tips ADD COLUMN IF NOT EXISTS reversal_note      text;
ALTER TABLE public.link_tips ADD COLUMN IF NOT EXISTS reversal_alerted   text;
ALTER TABLE public.link_tips ADD COLUMN IF NOT EXISTS reversal_at        timestamptz;

CREATE OR REPLACE FUNCTION public.record_tip_reversal(
    p_tip_id         uuid,
    p_refunded       numeric,
    p_dispute_status text    DEFAULT NULL,
    p_clawed_back    numeric DEFAULT NULL,
    p_note           text    DEFAULT NULL)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
DECLARE
    t        link_tips%ROWTYPE;
    v_ref    numeric;
    v_disp   text;
    v_claw   numeric;
    v_lost0  numeric;
    v_lost1  numeric;
    v_state  text;
    v_note   text;
BEGIN
    SELECT * INTO t FROM link_tips WHERE id = p_tip_id FOR UPDATE;
    IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'tip_not_found'); END IF;
    IF p_dispute_status IS NOT NULL AND p_dispute_status NOT IN ('open', 'won', 'lost') THEN
        RETURN jsonb_build_object('success', false, 'error', 'bad_dispute_status');
    END IF;

    -- Only ever up: a late, older event must not undo a newer one.
    v_ref  := LEAST(t.amount, GREATEST(COALESCE(t.refunded_amount, 0), round(COALESCE(p_refunded, 0), 2)));
    v_disp := COALESCE(p_dispute_status, t.dispute_status);
    -- a closed dispute stays closed; a new "open" for it does not reopen it
    IF t.dispute_status IN ('won', 'lost') AND p_dispute_status = 'open' THEN v_disp := t.dispute_status; END IF;
    v_claw := LEAST(t.amount, GREATEST(COALESCE(t.clawed_back_amount, 0), round(COALESCE(p_clawed_back, 0), 2)));

    -- What the staff member has lost of this tip, before and after.
    v_lost0 := GREATEST(COALESCE(t.refunded_amount, 0),
                        CASE WHEN t.dispute_status IN ('open', 'lost') THEN t.amount ELSE 0 END);
    v_lost1 := GREATEST(v_ref, CASE WHEN v_disp IN ('open', 'lost') THEN t.amount ELSE 0 END);

    UPDATE link_tips SET
        refunded_amount    = v_ref,
        dispute_status     = v_disp,
        clawed_back_amount = v_claw,
        reversal_note      = COALESCE(NULLIF(btrim(COALESCE(p_note, '')), ''), CASE WHEN v_claw >= v_lost1 THEN NULL ELSE reversal_note END),
        reversal_at        = CASE WHEN v_lost1 <> v_lost0 OR v_disp IS DISTINCT FROM t.dispute_status OR v_claw <> t.clawed_back_amount
                                  THEN now() ELSE reversal_at END
     WHERE id = p_tip_id
    RETURNING reversal_note INTO v_note;

    IF v_lost1 <> v_lost0 AND t.staff_account_id IS NOT NULL THEN
        UPDATE link_staff_accounts
           SET total_earned = total_earned - (v_lost1 - v_lost0), updated_at = now()
         WHERE id = t.staff_account_id;
    END IF;

    v_state := 'refunded=' || v_ref || ';dispute=' || COALESCE(v_disp, '-') || ';clawed=' || v_claw;
    RETURN jsonb_build_object('success', true,
        'tipId', t.id, 'campId', t.camp_id, 'staffName', t.recipient_name, 'amount', t.amount,
        'refunded', v_ref, 'disputeStatus', v_disp, 'clawedBack', v_claw,
        'lost', v_lost1, 'change', v_lost1 - v_lost0, 'note', v_note,
        'state', v_state, 'alerted', t.reversal_alerted IS NOT DISTINCT FROM v_state
                                    OR (v_lost1 = 0 AND v_disp IS NULL AND t.reversal_alerted IS NULL));
END $$;
REVOKE ALL ON FUNCTION public.record_tip_reversal(uuid, numeric, text, numeric, text) FROM public, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.record_tip_reversal(uuid, numeric, text, numeric, text) TO service_role;

CREATE OR REPLACE FUNCTION public.mark_tip_reversal_alerted(p_tip_id uuid, p_state text)
RETURNS boolean
LANGUAGE sql
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
    UPDATE link_tips SET reversal_alerted = p_state WHERE id = p_tip_id RETURNING true;
$$;
REVOKE ALL ON FUNCTION public.mark_tip_reversal_alerted(uuid, text) FROM public, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.mark_tip_reversal_alerted(uuid, text) TO service_role;


-- ▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼
-- 286_an_old_tab_keeps_the_payers_share.sql
-- ▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲

-- ============================================================================
-- Migration 286: an office computer left open from before keeps a fund's share
-- of a split bill, and the fund's payments.
--
-- Standalone. Paste into the Supabase SQL Editor and click Run. Safe to run
-- more than once. Requires 266, 267 and 272. Run it BEFORE reloading Me.
--
-- ── THE PROBLEM (TED-177) ──────────────────────────────────────────────────
-- "Split between payers" billed a fund its share of a charge and recorded the
-- fund's cheques on the fund itself, in the camp's settings document. A second
-- office computer that had not reloaded (a laptop that was asleep) wrote its
-- older copy of that document back the next time it saved anything: the fund's
-- $800 owing and its $300 cheque were gone, and the household was still billed
-- only its own $200.
--
-- ── THE CHANGE ─────────────────────────────────────────────────────────────
-- Me now keeps a payer's share and payments on the HOUSEHOLD's family record
-- (payerLedger), which is saved as its own row and merged on the server. The
-- merge (_merge_family_from_page, as 272 left it) now also keeps every
-- payerLedger entry the server holds that the page never saw — the list only
-- ever grows; a correction is a new entry that voids an old one.
-- ============================================================================

DO $$
BEGIN
    IF to_regprocedure('public._merge_family_from_page(jsonb,jsonb)') IS NULL
       OR to_regprocedure('public._keep_charge_links(jsonb,jsonb)') IS NULL THEN
        RAISE EXCEPTION '286 needs migrations 266, 267 and 272 — apply those first';
    END IF;
END $$;

CREATE OR REPLACE FUNCTION public._keep_payer_ledger(p_server jsonb, p_merged jsonb)
RETURNS jsonb
LANGUAGE plpgsql
IMMUTABLE
SET search_path = public, pg_catalog
AS $$
DECLARE
    v_pe  jsonb;
    v_ids text[];
    e     jsonb;
BEGIN
    -- IS DISTINCT FROM, not <>: a family with no payer lines has no such key,
    -- and NULL <> 'array' is not true — it would have gained an empty list.
    IF p_server IS NULL OR jsonb_typeof(p_server->'payerLedger') IS DISTINCT FROM 'array'
       OR p_merged IS NULL OR jsonb_typeof(p_merged) IS DISTINCT FROM 'object' THEN
        RETURN p_merged;
    END IF;
    v_pe := CASE WHEN jsonb_typeof(p_merged->'payerLedger') = 'array' THEN p_merged->'payerLedger' ELSE '[]'::jsonb END;
    SELECT COALESCE(array_agg(x->>'id'), '{}') INTO v_ids FROM jsonb_array_elements(v_pe) x;
    FOR e IN SELECT * FROM jsonb_array_elements(p_server->'payerLedger') LOOP
        IF jsonb_typeof(e) = 'object' AND COALESCE(e->>'id', '') <> '' AND NOT (e->>'id' = ANY (v_ids)) THEN
            v_pe := v_pe || jsonb_build_array(e);
        END IF;
    END LOOP;
    RETURN jsonb_set(p_merged, '{payerLedger}', v_pe, true);
END;
$$;
REVOKE ALL ON FUNCTION public._keep_payer_ledger(jsonb, jsonb) FROM public, anon, authenticated;

DO $$
DECLARE
    d   text := pg_get_functiondef('public._merge_family_from_page(jsonb,jsonb)'::regprocedure);
    old text := 'RETURN public._keep_charge_links(p_server, v_out);';
BEGIN
    IF position('_keep_payer_ledger' IN d) > 0 THEN
        RAISE NOTICE '286: _merge_family_from_page already keeps the payers'' entries';
        RETURN;
    END IF;
    IF position(old IN d) = 0 THEN
        RAISE EXCEPTION '286: _merge_family_from_page does not look the way this file expects (run 272 first) — send this message to the builder';
    END IF;
    EXECUTE replace(d, old, 'RETURN public._keep_charge_links(p_server, public._keep_payer_ledger(p_server, v_out));');
END $$;


-- ▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼
-- 287_a_canteen_top_up_refunded_outside_campistry.sql
-- ▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲

-- ============================================================================
-- Migration 287: a canteen top-up refunded in Stripe's own dashboard, or
-- disputed with the parent's bank, comes off the child's wallet — once — and
-- the camp is told.
--
-- Standalone. Paste into the Supabase SQL Editor and click Run. Safe to run
-- more than once. Requires 275 and 278. Run it BEFORE deploying stripe-webhook.
--
-- ── THE PROBLEM (TED-181) ──────────────────────────────────────────────────
-- A $20 canteen top-up refunded from the Stripe dashboard (not from Snacks), or
-- disputed by the parent: the parent had the $20 back, the child could still
-- spend $20, and nobody was told. stripe-webhook looked for a family payment
-- with that id, found none, and logged it.
--
-- ── THE CHANGE ─────────────────────────────────────────────────────────────
-- record_canteen_stripe_reversal(camp, payment, refund-or-dispute id, amount,
-- kind, note) — for stripe-webhook only (service role):
--   kind 'refund'      a refund made outside Campistry: that amount comes off
--                      the child's wallet as a 'refund' line naming the top-up
--                      and the refund (so the top-up can't be refunded again);
--   kind 'dispute'     the bank took the money back: the same, for the
--                      disputed amount;
--   kind 'dispute_won' the camp won: the money goes back on the wallet;
--   once per refund / dispute, however often Stripe says so; never more than
--   the top-up had left. Campistry's own canteen refunds are not touched (they
--   are already on the wallet, by their refund id); nor is a top-up with a
--   Campistry refund still waiting for an answer (the camp is told instead).
-- The camp gets a notice each time, and one saying so when the child's wallet
-- goes below zero (the child had already spent the money).
-- ============================================================================

DO $$
BEGIN
    IF to_regprocedure('public.canteen_account_lock(uuid,text)') IS NULL
       OR to_regprocedure('public.canteen_post(uuid,text,jsonb,text)') IS NULL
       OR to_regclass('public.canteen_refund_holds') IS NULL
       OR to_regprocedure('public.is_money_notice(text)') IS NULL THEN
        RAISE EXCEPTION '287 needs migrations 219, 275 and 278 — apply those first';
    END IF;
END $$;

-- The camp's bell shows money notices by this list (278); one more kind.
CREATE OR REPLACE FUNCTION public.is_money_notice(p_source text)
RETURNS boolean
LANGUAGE sql
IMMUTABLE
SET search_path = public, pg_catalog
AS $$
    SELECT COALESCE(p_source, '') IN (
        'payment_unmatched', 'autopay_blocked', 'chargeback', 'card_expiry',
        'parent_payment_plan_created', 'payout_failed', 'charge_unconfirmed',
        'canteen_autoreload_off', 'tip_transfer_failed', 'telnyx_fee_failed', 'autopay_setup',
        'refund_failed', 'canteen_reversed');
$$;

CREATE OR REPLACE FUNCTION public.record_canteen_stripe_reversal(
    p_camp_id           uuid,
    p_payment_intent_id text,
    p_ref_id            text,
    p_amount            numeric,
    p_kind              text,
    p_note              text DEFAULT NULL)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
DECLARE
    v_pi    text := NULLIF(btrim(COALESCE(p_payment_intent_id, '')), '');
    v_ref   text := NULLIF(btrim(COALESCE(p_ref_id, '')), '');
    dep     canteen_transactions%ROWTYPE;
    v_acct  jsonb;
    v_bal   numeric;
    v_left  numeric;
    v_amt   numeric;
    v_who   text;
    v_sig   text;
    v_n     integer;
    now_ts  timestamptz := now();
BEGIN
    IF p_camp_id IS NULL OR v_pi IS NULL OR v_ref IS NULL OR COALESCE(p_kind, '') NOT IN ('refund', 'dispute', 'dispute_won') THEN
        RETURN jsonb_build_object('success', false, 'error', 'missing_argument');
    END IF;
    SELECT * INTO dep FROM canteen_transactions
     WHERE camp_id = p_camp_id AND payload ->> 'stripePaymentIntentId' = v_pi
       AND tx_type = 'credit' AND COALESCE(payload ->> 'kind', '') = 'deposit'
     ORDER BY first_seen LIMIT 1;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'deposit_not_found');
    END IF;
    v_who := regexp_replace(COALESCE(NULLIF(dep.payload ->> 'camper', ''), dep.camper), '\s#\d+$', '');

    -- the child's wallet lock: two deliveries of the same event queue here
    v_acct := public.canteen_account_lock(p_camp_id, dep.camper);

    IF p_kind = 'dispute_won' THEN
        IF NOT EXISTS (SELECT 1 FROM canteen_transactions WHERE camp_id = p_camp_id AND sig = 'xref:' || v_ref) THEN
            RETURN jsonb_build_object('success', true, 'nothing', 'never_taken');
        END IF;
        v_sig := 'xref_won:' || v_ref;
        IF EXISTS (SELECT 1 FROM canteen_transactions WHERE camp_id = p_camp_id AND sig = v_sig) THEN
            RETURN jsonb_build_object('success', true, 'alreadyRecorded', true);
        END IF;
        SELECT amount INTO v_amt FROM canteen_transactions WHERE camp_id = p_camp_id AND sig = 'xref:' || v_ref;
        v_bal := round(COALESCE(NULLIF(v_acct ->> 'balance', '')::numeric, 0) + v_amt, 2);
        PERFORM public.canteen_account_save(p_camp_id, dep.camper, v_acct || jsonb_build_object('balance', v_bal));
        PERFORM public.canteen_post(p_camp_id, dep.camper, jsonb_build_object(
            'time', to_char(now_ts, 'HH12:MI AM'), 'camper', dep.payload ->> 'camper',
            'items', 'Dispute won — the $' || to_char(v_amt, 'FM999999990.00') || ' is back on the wallet',
            'amount', v_amt, 'type', 'credit', 'kind', 'refund_failed', 'disputeWon', true,
            'stripePaymentIntentId', v_pi, 'stripeDisputeId', v_ref,
            'date', to_char(now_ts, 'YYYY-MM-DD'), 'timestamp', (extract(epoch FROM now_ts) * 1000)::bigint)
            || CASE WHEN dep.camper_id IS NOT NULL AND dep.camper_id ~ '^[0-9]+$' THEN jsonb_build_object('camperId', dep.camper_id::bigint) ELSE '{}'::jsonb END,
            v_sig);
        IF to_regclass('public.notifications') IS NOT NULL THEN
            INSERT INTO notifications (camp_id, source, source_id, title, body, link_target)
            VALUES (p_camp_id, 'canteen_reversed', v_sig, 'A canteen dispute was won',
                    'The bank ruled for the camp on ' || v_who || '''s $' || to_char(v_amt, 'FM999999990.00')
                      || ' top-up, so it is back on ' || v_who || '''s canteen wallet.', 'campistry_snacks.html')
            ON CONFLICT (camp_id, source, source_id) DO NOTHING;
        END IF;
        RETURN jsonb_build_object('success', true, 'amount', v_amt, 'balance', v_bal, 'camper', v_who);
    END IF;

    -- Campistry's own refund: already on the wallet by its id.
    IF p_kind = 'refund' AND EXISTS (SELECT 1 FROM canteen_transactions
                                      WHERE camp_id = p_camp_id AND payload ->> 'stripeRefundId' = v_ref) THEN
        RETURN jsonb_build_object('success', true, 'alreadyRecorded', true, 'own', true);
    END IF;
    v_sig := 'xref:' || v_ref;
    IF EXISTS (SELECT 1 FROM canteen_transactions WHERE camp_id = p_camp_id AND sig = v_sig) THEN
        RETURN jsonb_build_object('success', true, 'alreadyRecorded', true);
    END IF;
    -- A Campistry refund of this top-up still waiting for its answer: its
    -- money is already held off the wallet, and this may be it. Tell, don't take.
    IF p_kind = 'refund' AND EXISTS (SELECT 1 FROM canteen_refund_holds
                                      WHERE camp_id = p_camp_id AND state = 'open' AND payment_ref = v_pi) THEN
        IF to_regclass('public.notifications') IS NOT NULL THEN
            INSERT INTO notifications (camp_id, source, source_id, title, body, link_target)
            VALUES (p_camp_id, 'canteen_reversed', v_sig, 'Check a canteen refund',
                    'A $' || to_char(round(COALESCE(p_amount, 0), 2), 'FM999999990.00') || ' refund of ' || v_who
                      || '''s top-up was made in Stripe while a refund from Snacks was still waiting for an answer. '
                      || 'Open Snacks → Refund All: it looks the waiting refund up. If they are two different refunds, take the second one off '
                      || v_who || '''s wallet by hand.', 'campistry_snacks.html')
            ON CONFLICT (camp_id, source, source_id) DO NOTHING;
        END IF;
        RETURN jsonb_build_object('success', true, 'held', true);
    END IF;

    -- never more than the top-up has left (less what was refunded before, plus
    -- any refund that failed and came back)
    SELECT dep.amount
         - COALESCE(sum(CASE WHEN t.payload ->> 'kind' = 'refund' THEN t.amount ELSE 0 END), 0)
         + COALESCE(sum(CASE WHEN t.payload ->> 'kind' = 'refund_failed' THEN t.amount ELSE 0 END), 0)
      INTO v_left
      FROM canteen_transactions t
     WHERE t.camp_id = p_camp_id AND t.payload ->> 'stripePaymentIntentId' = v_pi
       AND t.payload ->> 'kind' IN ('refund', 'refund_failed');
    v_amt := round(LEAST(GREATEST(COALESCE(p_amount, 0), 0), GREATEST(COALESCE(v_left, dep.amount), 0)), 2);
    IF v_amt <= 0 THEN
        RETURN jsonb_build_object('success', true, 'nothing', 'already_refunded');
    END IF;

    v_bal := round(COALESCE(NULLIF(v_acct ->> 'balance', '')::numeric, 0) - v_amt, 2);
    PERFORM public.canteen_account_save(p_camp_id, dep.camper, v_acct || jsonb_build_object('balance', v_bal));
    PERFORM public.canteen_post(p_camp_id, dep.camper, jsonb_build_object(
        'time', to_char(now_ts, 'HH12:MI AM'), 'camper', dep.payload ->> 'camper',
        'items', CASE WHEN p_kind = 'dispute' THEN 'Top-up disputed with the bank' ELSE 'Top-up refunded in Stripe' END,
        'amount', v_amt, 'type', 'debit', 'kind', 'refund', 'external', true,
        'stripePaymentIntentId', v_pi,
        'note', COALESCE(NULLIF(btrim(COALESCE(p_note, '')), ''), CASE WHEN p_kind = 'dispute' THEN 'Disputed' ELSE 'Refunded outside Campistry' END),
        'by', 'Stripe',
        'date', to_char(now_ts, 'YYYY-MM-DD'), 'timestamp', (extract(epoch FROM now_ts) * 1000)::bigint)
        || CASE WHEN p_kind = 'dispute' THEN jsonb_build_object('stripeDisputeId', v_ref) ELSE jsonb_build_object('stripeRefundId', v_ref) END
        || CASE WHEN dep.camper_id IS NOT NULL AND dep.camper_id ~ '^[0-9]+$' THEN jsonb_build_object('camperId', dep.camper_id::bigint) ELSE '{}'::jsonb END,
        v_sig);

    IF to_regclass('public.notifications') IS NOT NULL THEN
        INSERT INTO notifications (camp_id, source, source_id, title, body, link_target)
        VALUES (p_camp_id, 'canteen_reversed', v_sig,
                CASE WHEN p_kind = 'dispute' THEN 'A canteen top-up was disputed' ELSE 'A canteen top-up was refunded in Stripe' END,
                CASE WHEN p_kind = 'dispute'
                     THEN 'The parent disputed ' || v_who || '''s $' || to_char(v_amt, 'FM999999990.00') || ' top-up with their bank, so it has come off ' || v_who || '''s canteen wallet. If the camp wins the dispute it goes back on. '
                     ELSE 'A $' || to_char(v_amt, 'FM999999990.00') || ' refund of ' || v_who || '''s top-up was made in the Stripe dashboard, so it has come off ' || v_who || '''s canteen wallet. Next time, refund from Snacks. ' END
                  || CASE WHEN v_bal < 0 THEN v_who || ' had already spent it: the wallet is now $' || to_char(v_bal, 'FM999999990.00') || ' — the family owes the canteen that much.' ELSE '' END,
                'campistry_snacks.html')
        ON CONFLICT (camp_id, source, source_id) DO NOTHING;
    END IF;
    RETURN jsonb_build_object('success', true, 'amount', v_amt, 'balance', v_bal, 'camper', v_who, 'overdrawn', v_bal < 0);
END $$;
REVOKE ALL ON FUNCTION public.record_canteen_stripe_reversal(uuid, text, text, numeric, text, text) FROM public, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.record_canteen_stripe_reversal(uuid, text, text, numeric, text, text) TO service_role;


-- ▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼
-- 288_autopay_waits_while_a_payment_is_disputed.sql
-- ▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲

-- ============================================================================
-- Migration 288: while a family's payment is charged back, autopay does not
-- charge them again on its own.
--
-- Standalone. Paste into the Supabase SQL Editor and click Run. Safe to run
-- more than once. Requires 175, 213 and 286. Run it BEFORE deploying stripe-webhook
-- and charge-due-installments, and before reloading Me.
--
-- ── THE PROBLEM (TED-186) ──────────────────────────────────────────────────
-- A chargeback puts the disputed payment back on the family's bill (175) — and
-- that night's autopay charged the same card for it again, while the parent's
-- bank was still deciding: a second charge the parent is already disputing.
-- (The webhook also treated a bank's INQUIRY — a question, no money moved — as
-- a chargeback; that part is fixed in stripe-webhook: an inquiry posts nothing,
-- only a dispute that takes money does.)
--
-- ── THE CHANGE ─────────────────────────────────────────────────────────────
-- (Edited after pass 20 — TED-193/194/196/197: the pause lists every open
-- dispute; a decline mark is kept under it; the runner's own marks never
-- replace it; a dispute already won pauses nothing. Edited after pass 21 —
-- TED-200/201/202: the pause is kept on the FAMILY (disputeHold) and on every
-- plan, autopay on or not, the old single plan too; Billing, Charge Card,
-- Batch Charge, the runner and stripe-charge / payments-charge all refuse a
-- paused family; a lost dispute is marked lost, and Resume is refused while
-- another is still open. Edited after pass 22 — TED-207: the family keeps a
-- lasting disputeLog of lost and resumed disputes, so a late message never
-- re-pauses a family the office resumed, and a loss that arrives first counts.)
-- hold_autopay_for_dispute(camp, family, dispute, hold): for stripe-webhook
-- only. When a chargeback is posted, every autopay plan of that family is
-- marked collectionBlocked {reason 'chargeback', disputeId} — the nightly
-- runner skips a plan marked so, Billing shows "Autopay paused — payment
-- disputed", and the camp gets one notice. When the camp WINS, the mark comes
-- off. When the camp loses, it stays: the office decides whether to charge the
-- family again, with resume_autopay_after_dispute (someone who can edit
-- Billing), from Billing.
-- ============================================================================

DO $$
BEGIN
    IF to_regprocedure('public.camp_family_for_update(uuid,text)') IS NULL
       OR to_regprocedure('public.camp_family_save(uuid,text,jsonb)') IS NULL
       OR to_regprocedure('public.user_section_level(uuid,text)') IS NULL
       OR to_regprocedure('public._keep_payer_ledger(jsonb,jsonb)') IS NULL THEN
        RAISE EXCEPTION '288 needs migrations 213, 286 and the access resolver — apply those first';
    END IF;
END $$;

-- The pause, on ONE plan: a dispute added to it, or taken off. The pause lists
-- every open dispute (disputeIds) and comes off only when none is left
-- (TED-193); a card-decline or no-card mark already on the plan is kept under
-- it (under) and put back when the pause lifts, so its retry date survives
-- (TED-197). Every plan is paused, autopay on or not (TED-200): autopay
-- switched on during the dispute must not charge.
CREATE OR REPLACE FUNCTION public._mark_one_plan_for_dispute(p jsonb, p_dispute_id text, p_hold boolean, p_detail text, p_since text)
RETURNS jsonb
LANGUAGE plpgsql
IMMUTABLE
SET search_path = public, pg_catalog
AS $$
DECLARE
    b     jsonb;
    v_ids jsonb;
BEGIN
    IF jsonb_typeof(p) IS DISTINCT FROM 'object' THEN RETURN p; END IF;
    b := p -> 'collectionBlocked';
    IF COALESCE(jsonb_typeof(b) = 'object' AND b ->> 'reason' = 'chargeback', false) THEN
        v_ids := CASE WHEN jsonb_typeof(b -> 'disputeIds') = 'array' THEN b -> 'disputeIds'
                      WHEN b ? 'disputeId' THEN jsonb_build_array(b ->> 'disputeId') ELSE '[]'::jsonb END;
        IF p_hold THEN
            IF NOT v_ids ? p_dispute_id THEN
                p := jsonb_set(p, '{collectionBlocked}', b || jsonb_build_object('disputeIds', v_ids || to_jsonb(p_dispute_id)), true);
            END IF;
        ELSE
            v_ids := CASE WHEN p_dispute_id IS NULL THEN '[]'::jsonb ELSE v_ids - p_dispute_id END;
            IF jsonb_array_length(v_ids) > 0 THEN
                p := jsonb_set(p, '{collectionBlocked}', b || jsonb_build_object('disputeIds', v_ids, 'disputeId', v_ids ->> 0), true);
            ELSIF jsonb_typeof(b -> 'under') = 'object' THEN
                p := jsonb_set(p, '{collectionBlocked}', b -> 'under', true);
            ELSE
                p := p - 'collectionBlocked';
            END IF;
        END IF;
    ELSIF p_hold THEN
        p := jsonb_set(p, '{collectionBlocked}', jsonb_build_object(
                'reason', 'chargeback', 'disputeId', p_dispute_id, 'disputeIds', jsonb_build_array(p_dispute_id),
                'detail', p_detail, 'since', p_since)
             || CASE WHEN jsonb_typeof(b) = 'object' THEN jsonb_build_object('under', b) ELSE '{}'::jsonb END, true);
    END IF;
    RETURN p;
END $$;
REVOKE ALL ON FUNCTION public._mark_one_plan_for_dispute(jsonb, text, boolean, text, text) FROM public, anon, authenticated;

-- The family with a dispute added to its pause, or taken off it. The pause is
-- kept on the FAMILY (disputeHold: disputeIds, lostIds, since, detail) — so a
-- family that pays by hand, or has no plan yet, is paused too (TED-200) — and
-- on every plan, the old single plan included (TED-201). p_dispute_id NULL
-- with p_hold false: every dispute off (the office's resume).
CREATE OR REPLACE FUNCTION public._mark_plans_for_dispute(p_fam jsonb, p_dispute_id text, p_hold boolean, p_detail text)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SET search_path = public, pg_catalog
AS $$
DECLARE
    v_out   jsonb := p_fam;
    v_plans jsonb := '[]'::jsonb;
    p       jsonb;
    h       jsonb;
    v_ids   jsonb;
    v_lost  jsonb;
    now_ts  text := to_char(now(), 'YYYY-MM-DD"T"HH24:MI:SS"Z"');
BEGIN
    IF jsonb_typeof(p_fam) IS DISTINCT FROM 'object' THEN RETURN p_fam; END IF;

    -- the family's own pause
    h := CASE WHEN jsonb_typeof(p_fam -> 'disputeHold') = 'object' THEN p_fam -> 'disputeHold' END;
    v_ids  := CASE WHEN jsonb_typeof(h -> 'disputeIds') = 'array' THEN h -> 'disputeIds' ELSE '[]'::jsonb END;
    v_lost := CASE WHEN jsonb_typeof(h -> 'lostIds') = 'array' THEN h -> 'lostIds' ELSE '[]'::jsonb END;
    IF p_hold THEN
        IF NOT v_ids ? p_dispute_id THEN v_ids := v_ids || to_jsonb(p_dispute_id); END IF;
        v_out := jsonb_set(v_out, '{disputeHold}',
                   COALESCE(h, jsonb_strip_nulls(jsonb_build_object('since', now_ts, 'detail', p_detail)))
                   || jsonb_build_object('disputeIds', v_ids, 'lostIds', v_lost), true);
    ELSE
        IF p_dispute_id IS NULL THEN
            v_ids := '[]'::jsonb;
        ELSE
            v_ids := v_ids - p_dispute_id;
            v_lost := v_lost - p_dispute_id;
        END IF;
        IF jsonb_array_length(v_ids) > 0 THEN
            v_out := jsonb_set(v_out, '{disputeHold}', h || jsonb_build_object('disputeIds', v_ids, 'lostIds', v_lost), true);
        ELSE
            v_out := v_out - 'disputeHold';
        END IF;
    END IF;

    -- every plan
    IF jsonb_typeof(p_fam -> 'plans') = 'array' THEN
        FOR p IN SELECT * FROM jsonb_array_elements(p_fam -> 'plans') LOOP
            v_plans := v_plans || jsonb_build_array(public._mark_one_plan_for_dispute(p, p_dispute_id, p_hold, p_detail, now_ts));
        END LOOP;
        v_out := jsonb_set(v_out, '{plans}', v_plans, true);
    END IF;
    IF jsonb_typeof(p_fam -> 'plan') = 'object' THEN
        v_out := jsonb_set(v_out, '{plan}', public._mark_one_plan_for_dispute(p_fam -> 'plan', p_dispute_id, p_hold, p_detail, now_ts), true);
    END IF;
    RETURN v_out;
END $$;
REVOKE ALL ON FUNCTION public._mark_plans_for_dispute(jsonb, text, boolean, text) FROM public, anon, authenticated;

CREATE OR REPLACE FUNCTION public.hold_autopay_for_dispute(
    p_camp_id    uuid,
    p_family_key text,
    p_dispute_id text,
    p_hold       boolean,
    p_detail     text DEFAULT NULL)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
DECLARE
    v_fam jsonb;
    v_new jsonb;
BEGIN
    IF p_camp_id IS NULL OR NULLIF(btrim(COALESCE(p_family_key, '')), '') IS NULL
       OR NULLIF(btrim(COALESCE(p_dispute_id, '')), '') IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'missing_argument');
    END IF;
    v_fam := public.camp_family_for_update(p_camp_id, p_family_key);
    IF v_fam IS NULL OR jsonb_typeof(v_fam) <> 'object' THEN
        RETURN jsonb_build_object('success', false, 'error', 'family_not_found');
    END IF;
    -- A late or repeated message for a dispute the camp already won pauses
    -- nothing (TED-196): the win's line is on the family's ledger.
    IF COALESCE(p_hold, false) AND EXISTS (
            SELECT 1 FROM jsonb_array_elements(CASE WHEN jsonb_typeof(v_fam -> 'entries') = 'array'
                                                    THEN v_fam -> 'entries' ELSE '[]'::jsonb END) e
             WHERE e ->> 'id' = 'le_cbwon_' || p_dispute_id)
       -- ...or a canteen top-up's dispute the camp won (290, TED-210)
       OR EXISTS (SELECT 1 FROM canteen_transactions WHERE camp_id = p_camp_id AND sig = 'xref_won:' || p_dispute_id) THEN
        RETURN jsonb_build_object('success', true, 'changed', false, 'alreadyWon', true);
    END IF;
    -- ...nor one the office already resumed (TED-207): a late or routine
    -- message about it never pauses the family again behind the office's back.
    IF COALESCE(p_hold, false) AND COALESCE((v_fam -> 'disputeLog' -> 'resumed') ? p_dispute_id, false) THEN
        RETURN jsonb_build_object('success', true, 'changed', false, 'alreadyResumed', true);
    END IF;
    v_new := public._mark_plans_for_dispute(v_fam, p_dispute_id, COALESCE(p_hold, false), p_detail);
    -- A loss that arrived before the dispute itself (TED-207): already lost.
    IF COALESCE(p_hold, false) AND COALESCE((v_fam -> 'disputeLog' -> 'lost') ? p_dispute_id, false)
       AND jsonb_typeof(v_new -> 'disputeHold') = 'object'
       AND NOT COALESCE((v_new -> 'disputeHold' -> 'lostIds') ? p_dispute_id, false) THEN
        v_new := jsonb_set(v_new, '{disputeHold,lostIds}',
                   COALESCE(v_new -> 'disputeHold' -> 'lostIds', '[]'::jsonb) || to_jsonb(p_dispute_id), true);
    END IF;
    IF v_new IS NOT DISTINCT FROM v_fam THEN
        RETURN jsonb_build_object('success', true, 'changed', false);
    END IF;
    PERFORM public.camp_family_save(p_camp_id, p_family_key, v_new);
    IF p_hold AND to_regclass('public.notifications') IS NOT NULL THEN
        INSERT INTO notifications (camp_id, source, source_id, title, body, link_target)
        VALUES (p_camp_id, 'autopay_blocked', p_family_key || ':chargeback:' || p_dispute_id,
                'A payment was disputed — card charges paused',
                COALESCE(v_fam ->> 'name', p_family_key)
                  || ' disputed a payment with their bank, so their card will not be charged again — not by autopay, not from Billing. '
                  || 'If the camp wins the dispute this lifts by itself; if not, resume it from Billing once you have agreed with the family.',
                'campistry_me.html')
        ON CONFLICT (camp_id, source, source_id) DO NOTHING;
    END IF;
    RETURN jsonb_build_object('success', true, 'changed', true, 'held', COALESCE(p_hold, false));
END $$;
REVOKE ALL ON FUNCTION public.hold_autopay_for_dispute(uuid, text, text, boolean, text) FROM public, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.hold_autopay_for_dispute(uuid, text, text, boolean, text) TO service_role;

-- A dispute the camp LOST (TED-202): the pause stays, but that dispute is
-- marked lost — the office may resume once no dispute is still open.
CREATE OR REPLACE FUNCTION public.note_dispute_lost(p_camp_id uuid, p_family_key text, p_dispute_id text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
DECLARE
    v_fam jsonb;
    v_new jsonb;
    h     jsonb;
    v_lost jsonb;
BEGIN
    IF p_camp_id IS NULL OR NULLIF(btrim(COALESCE(p_family_key, '')), '') IS NULL
       OR NULLIF(btrim(COALESCE(p_dispute_id, '')), '') IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'missing_argument');
    END IF;
    v_fam := public.camp_family_for_update(p_camp_id, p_family_key);
    IF v_fam IS NULL OR jsonb_typeof(v_fam) <> 'object' THEN
        RETURN jsonb_build_object('success', false, 'error', 'family_not_found');
    END IF;
    -- Kept on the family for good (disputeLog), so a loss that arrives before
    -- the dispute itself, or a message after the office resumed, still knows
    -- it was lost (TED-207).
    v_new := v_fam;
    IF NOT COALESCE((v_fam -> 'disputeLog' -> 'lost') ? p_dispute_id, false) THEN
        v_new := jsonb_set(v_new, '{disputeLog}', COALESCE(v_fam -> 'disputeLog', '{}'::jsonb)
                   || jsonb_build_object('lost', COALESCE(v_fam -> 'disputeLog' -> 'lost', '[]'::jsonb) || to_jsonb(p_dispute_id)), true);
    END IF;
    h := CASE WHEN jsonb_typeof(v_new -> 'disputeHold') = 'object' THEN v_new -> 'disputeHold' END;
    IF h IS NOT NULL AND jsonb_typeof(h -> 'disputeIds') = 'array' AND (h -> 'disputeIds') ? p_dispute_id THEN
        v_lost := CASE WHEN jsonb_typeof(h -> 'lostIds') = 'array' THEN h -> 'lostIds' ELSE '[]'::jsonb END;
        IF NOT v_lost ? p_dispute_id THEN
            v_new := jsonb_set(v_new, '{disputeHold,lostIds}', v_lost || to_jsonb(p_dispute_id), true);
        END IF;
    END IF;
    IF v_new IS NOT DISTINCT FROM v_fam THEN
        RETURN jsonb_build_object('success', true, 'changed', false);
    END IF;
    PERFORM public.camp_family_save(p_camp_id, p_family_key, v_new);
    RETURN jsonb_build_object('success', true, 'changed', true);
END $$;
REVOKE ALL ON FUNCTION public.note_dispute_lost(uuid, text, text) FROM public, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.note_dispute_lost(uuid, text, text) TO service_role;

-- The office's own "resume" after a dispute the camp did not win. While a
-- dispute is still open with the bank it is refused (TED-202) unless the
-- office says it is resuming anyway (p_even_open).
DROP FUNCTION IF EXISTS public.resume_autopay_after_dispute(uuid, text);
CREATE OR REPLACE FUNCTION public.resume_autopay_after_dispute(p_camp_id uuid, p_family_key text, p_even_open boolean DEFAULT false)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
DECLARE
    v_fam  jsonb;
    v_new  jsonb;
    h      jsonb;
    v_open integer := 0;
BEGIN
    IF auth.uid() IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'not_authenticated'); END IF;
    IF NOT public.camp_staff_member(p_camp_id)
       OR COALESCE(public.user_section_level(p_camp_id, 'me.billing'), 'none') <> 'edit' THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_authorized',
                                  'message', 'Only someone who can edit Billing can resume autopay.');
    END IF;
    v_fam := public.camp_family_for_update(p_camp_id, p_family_key);
    IF v_fam IS NULL OR jsonb_typeof(v_fam) <> 'object' THEN
        RETURN jsonb_build_object('success', false, 'error', 'family_not_found');
    END IF;
    h := CASE WHEN jsonb_typeof(v_fam -> 'disputeHold') = 'object' THEN v_fam -> 'disputeHold' END;
    IF jsonb_typeof(h -> 'disputeIds') = 'array' THEN
        SELECT count(*) INTO v_open FROM jsonb_array_elements_text(h -> 'disputeIds') d
         WHERE NOT (CASE WHEN jsonb_typeof(h -> 'lostIds') = 'array' THEN h -> 'lostIds' ELSE '[]'::jsonb END) ? d;
    END IF;
    IF v_open > 0 AND NOT COALESCE(p_even_open, false) THEN
        RETURN jsonb_build_object('success', false, 'error', 'dispute_open', 'open', v_open,
            'message', CASE WHEN v_open = 1 THEN 'A dispute is still open with the bank.'
                            ELSE v_open || ' disputes are still open with the bank.' END);
    END IF;
    v_new := public._mark_plans_for_dispute(v_fam, NULL, false, NULL);
    -- The disputes resumed are remembered (TED-207): a late or routine message
    -- about one of them never pauses the family again.
    IF jsonb_typeof(h -> 'disputeIds') = 'array' AND jsonb_array_length(h -> 'disputeIds') > 0 THEN
        v_new := jsonb_set(v_new, '{disputeLog}', COALESCE(v_fam -> 'disputeLog', '{}'::jsonb)
                   || jsonb_build_object('resumed', COALESCE(v_fam -> 'disputeLog' -> 'resumed', '[]'::jsonb)
                        || (SELECT COALESCE(jsonb_agg(d), '[]'::jsonb) FROM jsonb_array_elements(h -> 'disputeIds') d
                             WHERE NOT COALESCE((v_fam -> 'disputeLog' -> 'resumed') @> jsonb_build_array(d), false))), true);
    END IF;
    IF v_new IS DISTINCT FROM v_fam THEN
        PERFORM public.camp_family_save(p_camp_id, p_family_key, v_new);
    END IF;
    RETURN jsonb_build_object('success', true, 'changed', v_new IS DISTINCT FROM v_fam);
END $$;
REVOKE ALL ON FUNCTION public.resume_autopay_after_dispute(uuid, text, boolean) FROM public, anon;
GRANT EXECUTE ON FUNCTION public.resume_autopay_after_dispute(uuid, text, boolean) TO authenticated;

-- The family's pause is the server's (TED-200): an office computer that
-- loaded the family before the dispute (or after it was lifted) never writes
-- its own copy back. _merge_family_from_page (as 286 left it) takes the
-- server's disputeHold, or none, whatever the page sent.
CREATE OR REPLACE FUNCTION public._keep_dispute_hold(p_server jsonb, p_merged jsonb)
RETURNS jsonb
LANGUAGE plpgsql
IMMUTABLE
SET search_path = public, pg_catalog
AS $$
BEGIN
    IF p_merged IS NULL OR jsonb_typeof(p_merged) IS DISTINCT FROM 'object'
       OR p_server IS NULL OR jsonb_typeof(p_server) IS DISTINCT FROM 'object' THEN
        RETURN p_merged;
    END IF;
    p_merged := CASE WHEN jsonb_typeof(p_server -> 'disputeLog') = 'object'
                     THEN jsonb_set(p_merged, '{disputeLog}', p_server -> 'disputeLog', true)
                     ELSE p_merged - 'disputeLog' END;
    IF jsonb_typeof(p_server -> 'disputeHold') = 'object' THEN
        RETURN jsonb_set(p_merged, '{disputeHold}', p_server -> 'disputeHold', true);
    END IF;
    RETURN p_merged - 'disputeHold';
END $$;
REVOKE ALL ON FUNCTION public._keep_dispute_hold(jsonb, jsonb) FROM public, anon, authenticated;

DO $$
DECLARE
    d   text := pg_get_functiondef('public._merge_family_from_page(jsonb,jsonb)'::regprocedure);
    old text := 'public._keep_payer_ledger(p_server, v_out)';
BEGIN
    IF position('_keep_dispute_hold' IN d) > 0 THEN
        RAISE NOTICE '288: _merge_family_from_page already keeps the dispute pause';
        RETURN;
    END IF;
    IF position(old IN d) = 0 THEN
        RAISE EXCEPTION '288: _merge_family_from_page does not look the way this file expects (run 286 first) — send this message to the builder';
    END IF;
    EXECUTE replace(d, old, 'public._keep_dispute_hold(p_server, ' || old || ')');
END $$;

-- The nightly runner's own marks (a declined card, no card on file) never
-- replace a dispute pause (TED-194): flag_plan_collection (214) keeps the
-- pause and records its mark under it, to come back when the pause lifts.
DO $$
DECLARE
    d  text := pg_get_functiondef('public.flag_plan_collection(uuid,text,text,text,text)'::regprocedure);
    a1 text := '    v_next   date;';
    b1 text := '    v_next   date;' || chr(10) || '    v_cb     jsonb;';
    a2 text := '    v_prev := v_plan->''collectionBlocked'';';
    b2 text := '    v_prev := v_plan->''collectionBlocked'';' || chr(10)
            || '    -- 288 (TED-194): under a dispute pause, work on the mark kept under it' || chr(10)
            || '    IF COALESCE(jsonb_typeof(v_prev) = ''object'' AND v_prev->>''reason'' = ''chargeback'', false) THEN' || chr(10)
            || '        v_cb := v_prev;' || chr(10)
            || '        v_prev := CASE WHEN jsonb_typeof(v_cb->''under'') = ''object'' THEN v_cb->''under'' END;' || chr(10)
            || '        v_plan := CASE WHEN v_prev IS NULL THEN v_plan - ''collectionBlocked'' ELSE jsonb_set(v_plan, ''{collectionBlocked}'', v_prev, true) END;' || chr(10)
            || '        v_had := v_prev IS NOT NULL;' || chr(10)
            || '    END IF;';
    -- (269 made the write-back go through _plan_path)
    a3 text := '    v_fam := jsonb_set(v_fam, public._plan_path(v_fam, p_plan_id), v_plan, true);';
    b3 text := '    IF v_cb IS NOT NULL THEN' || chr(10)
            || '        v_plan := jsonb_set(v_plan, ''{collectionBlocked}'', (v_cb - ''under'')' || chr(10)
            || '            || CASE WHEN v_plan ? ''collectionBlocked'' THEN jsonb_build_object(''under'', v_plan->''collectionBlocked'') ELSE ''{}''::jsonb END, true);' || chr(10)
            || '    END IF;' || chr(10)
            || '    v_fam := jsonb_set(v_fam, public._plan_path(v_fam, p_plan_id), v_plan, true);';
BEGIN
    IF position('v_cb' IN d) > 0 THEN
        RAISE NOTICE '288: flag_plan_collection already keeps a dispute pause';
        RETURN;
    END IF;
    IF position(a1 IN d) = 0 OR position(a2 IN d) = 0 OR position(a3 IN d) = 0 THEN
        RAISE EXCEPTION '288: flag_plan_collection does not look the way this file expects (run 214 and 269 first) — send this message to the builder';
    END IF;
    EXECUTE replace(replace(replace(d, a1, b1), a2, b2), a3, b3);
END $$;


-- ▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼
-- 289_a_register_sale_keeps_what_it_sold.sql
-- ▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲

-- ============================================================================
-- Migration 289: a register sale keeps what it sold, by item id — so voiding
-- it puts exactly those items back in stock.
--
-- Standalone. Paste into the Supabase SQL Editor and click Run. Safe to run
-- more than once. Requires 283 and 284. Run it BEFORE reloading the register
-- (POS). A register that has not reloaded keeps working as it did.
--
-- ── THE PROBLEM (TED-192) ──────────────────────────────────────────────────
-- A sale's line said what was sold only in words ("Trail Mix 2, Chips, BBQ").
-- Voiding it (284) read the items back from those words: an item whose name
-- has a comma, or ends in a number, was never offered back to stock.
--
-- ── THE CHANGE ─────────────────────────────────────────────────────────────
-- submit_canteen_purchase_once takes the items the register sold, by id and
-- quantity (p_sold), and keeps them on the sale's line (soldItems). The void
-- (284) restocks by those ids, never more than the sale had; older sales still
-- go by their words. The old signature is replaced in the same step (two
-- versions differing by a defaulted argument confuse the API — see 247), so a
-- register that has not reloaded, which sends no p_sold, reaches this one.
-- ============================================================================

DO $$
BEGIN
    IF to_regprocedure('public.submit_canteen_purchase(uuid,text,numeric,text,date,bigint)') IS NULL
       OR to_regclass('public.canteen_sale_keys') IS NULL THEN
        RAISE EXCEPTION '289 needs migrations 247 and 283 — apply those first';
    END IF;
END $$;

DROP FUNCTION IF EXISTS public.submit_canteen_purchase_once(uuid, text, text, numeric, text, date, bigint);

CREATE OR REPLACE FUNCTION public.submit_canteen_purchase_once(
    p_camp_id     uuid,
    p_sale_key    text,
    p_camper_name text,
    p_amount      numeric,
    p_items       text   DEFAULT '',
    p_date        date   DEFAULT NULL,
    p_camper_id   bigint DEFAULT NULL,
    p_sold        jsonb  DEFAULT NULL)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
DECLARE
    v_key  text := NULLIF(btrim(COALESCE(p_sale_key, '')), '');
    v_fp   text := COALESCE(p_camper_id::text, 'n:' || btrim(COALESCE(p_camper_name, ''))) || '|' || round(COALESCE(p_amount, 0), 2)::text;
    v_n    integer := 0;
    v_prev public.canteen_sale_keys%ROWTYPE;
    v_sold jsonb;
    r      jsonb;
BEGIN
    IF auth.uid() IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'not_authenticated'); END IF;
    IF p_camp_id IS NULL OR NOT public.camp_staff_member(p_camp_id) THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_authorized');
    END IF;

    -- What was sold, cleaned: [{id, qty}] with a whole quantity 1..100.
    IF jsonb_typeof(p_sold) = 'array' THEN
        SELECT COALESCE(jsonb_agg(jsonb_build_object('id', x -> 'id', 'qty', floor((x ->> 'qty')::numeric))), '[]'::jsonb)
          INTO v_sold
          FROM jsonb_array_elements(p_sold) x
         WHERE jsonb_typeof(x) = 'object' AND x ? 'id' AND jsonb_typeof(x -> 'qty') = 'number'
           AND floor((x ->> 'qty')::numeric) BETWEEN 1 AND 100;
    END IF;

    IF v_key IS NOT NULL THEN
        -- A few days is all a retry ever needs.
        DELETE FROM canteen_sale_keys WHERE camp_id = p_camp_id AND created_at < now() - interval '3 days';
        INSERT INTO canteen_sale_keys (camp_id, sale_key, fingerprint) VALUES (p_camp_id, v_key, v_fp)
            ON CONFLICT (camp_id, sale_key) DO NOTHING;
        GET DIAGNOSTICS v_n = ROW_COUNT;
        IF v_n = 0 THEN
            SELECT * INTO v_prev FROM canteen_sale_keys WHERE camp_id = p_camp_id AND sale_key = v_key;
            IF v_prev.fingerprint IS DISTINCT FROM v_fp THEN
                RETURN jsonb_build_object('success', false, 'error', 'sale_key_reused');
            END IF;
            IF v_prev.result IS NOT NULL THEN
                RETURN v_prev.result || jsonb_build_object('replayed', true);
            END IF;
            RETURN jsonb_build_object('success', false, 'error', 'sale_in_progress');
        END IF;
    END IF;

    r := public.submit_canteen_purchase(p_camp_id, p_camper_name, p_amount, p_items, p_date, p_camper_id);
    IF COALESCE((r ->> 'success')::boolean, false) THEN
        -- The sale's own line: posted by this call, in this transaction, under
        -- the child's wallet lock (first_seen is this transaction's clock).
        IF v_sold IS NOT NULL AND jsonb_array_length(v_sold) > 0 THEN
            UPDATE canteen_transactions
               SET payload = payload || jsonb_build_object('soldItems', v_sold)
             WHERE camp_id = p_camp_id AND first_seen = now() AND tx_type = 'debit'
               AND amount = p_amount AND NOT (payload ? 'kind');
        END IF;
        IF v_key IS NOT NULL THEN
            UPDATE canteen_sale_keys SET result = r WHERE camp_id = p_camp_id AND sale_key = v_key;
        END IF;
    ELSIF v_key IS NOT NULL THEN
        -- Nothing was charged: the same sale may be tried again.
        DELETE FROM canteen_sale_keys WHERE camp_id = p_camp_id AND sale_key = v_key;
    END IF;
    RETURN r;
END $$;
REVOKE ALL ON FUNCTION public.submit_canteen_purchase_once(uuid, text, text, numeric, text, date, bigint, jsonb) FROM public, anon;
GRANT EXECUTE ON FUNCTION public.submit_canteen_purchase_once(uuid, text, text, numeric, text, date, bigint, jsonb) TO authenticated;

DO $$
BEGIN
    IF (SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
         WHERE n.nspname = 'public' AND p.proname = 'submit_canteen_purchase_once') <> 1 THEN
        RAISE EXCEPTION '289: submit_canteen_purchase_once must have exactly one signature';
    END IF;
END $$;


-- ▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼▼
-- 290_a_disputed_top_up_pauses_auto_reload.sql
-- ▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲

-- ============================================================================
-- Migration 290: a canteen top-up disputed with the bank switches that child's
-- auto-reload off, until the parent switches it back on.
--
-- Standalone. Paste into the Supabase SQL Editor and click Run. Safe to run
-- more than once. Requires 229, 234, 248, 282, 287 and 288. Run it BEFORE deploying
-- stripe-webhook and canteen-auto-reload.
--
-- ── THE PROBLEM (TED-205) ──────────────────────────────────────────────────
-- A parent disputed a $20 auto-reload. The dispute correctly took the $20 off
-- the child's wallet (287) — which left it empty, exactly what auto-reload
-- answers: the next day it charged the same card $20 again, and again each
-- time it ran low, while the parent's bank was still deciding. Nobody was told.
--
-- ── THE CHANGE ─────────────────────────────────────────────────────────────
-- pause_canteen_autoreload_for_dispute (stripe-webhook only): the child whose
-- top-up it was has auto-reload switched off, with a note Link shows the
-- parent ("switched off because a top-up was disputed …"), and the camp gets a
-- notice. The nightly run's own bookkeeping write (update_canteen_autoreload_
-- state), which carries the copy it read before the dispute, keeps it off; only
-- the parent's own save in Link (set_canteen_auto_reload) switches it back on.
-- (A family whose tuition payment is disputed — 288 — is skipped by the
-- nightly auto-reload run itself, in canteen-auto-reload.)
-- (Edited after pass 23 — TED-210/211: the webhooks also pause the child's
-- FAMILY (288's hold) for a disputed top-up, so a brother's or sister's
-- auto-reload, tuition autopay and Charge Card on that card wait too; a
-- Cardknox/Banquest top-up, found by its transaction number, is taken off
-- the wallet and paused the same way; a won dispute pauses nothing again.)
-- ============================================================================

DO $$
BEGIN
    IF to_regprocedure('public.record_canteen_stripe_reversal(uuid,text,text,numeric,text,text)') IS NULL
       OR to_regprocedure('public.canteen_account_lock(uuid,text)') IS NULL
       OR to_regprocedure('public.set_canteen_auto_reload(uuid,text,jsonb,bigint)') IS NULL
       OR COALESCE(to_regprocedure('public._update_canteen_autoreload_state__by_name(uuid,text,jsonb)'),
                   to_regprocedure('public.update_canteen_autoreload_state(uuid,text,jsonb)')) IS NULL THEN
        RAISE EXCEPTION '290 needs migrations 229, 231, 248 and 287 — apply those first';
    END IF;
END $$;

-- The canteen top-up a dispute is about: a Stripe payment id, or a
-- Cardknox/Banquest transaction number (TED-211).
CREATE OR REPLACE FUNCTION public._canteen_deposit_of(p_camp_id uuid, p_ref text)
RETURNS canteen_transactions
LANGUAGE sql
STABLE
SET search_path = public, pg_catalog
AS $$
    SELECT * FROM canteen_transactions
     WHERE camp_id = p_camp_id AND tx_type = 'credit' AND COALESCE(payload ->> 'kind', '') = 'deposit'
       AND (payload ->> 'stripePaymentIntentId' = p_ref OR payload ->> 'byopTransactionId' = p_ref)
     ORDER BY first_seen LIMIT 1
$$;
REVOKE ALL ON FUNCTION public._canteen_deposit_of(uuid, text) FROM public, anon, authenticated;

-- The family whose child's top-up it was (for the webhooks: that family's
-- card is paused as for a tuition dispute — TED-210).
CREATE OR REPLACE FUNCTION public.canteen_dispute_family(p_camp_id uuid, p_ref text)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
DECLARE
    dep canteen_transactions%ROWTYPE;
BEGIN
    dep := public._canteen_deposit_of(p_camp_id, NULLIF(btrim(COALESCE(p_ref, '')), ''));
    IF dep.camp_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'deposit_not_found');
    END IF;
    RETURN jsonb_build_object('success', true, 'camper', dep.camper,
        'familyKey', public.camp_family_key_for_person(p_camp_id,
            CASE WHEN dep.camper_id ~ '^[0-9]+$' THEN dep.camper_id::bigint END, dep.camper));
END $$;
REVOKE ALL ON FUNCTION public.canteen_dispute_family(uuid, text) FROM public, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.canteen_dispute_family(uuid, text) TO service_role;
-- The nightly auto-reload run asks which family a child is in, by camper
-- number (TED-213).
GRANT EXECUTE ON FUNCTION public.camp_family_key_for_person(uuid, bigint, text) TO service_role;

CREATE OR REPLACE FUNCTION public.pause_canteen_autoreload_for_dispute(
    p_camp_id           uuid,
    p_payment_intent_id text,
    p_dispute_id        text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
DECLARE
    v_pi   text := NULLIF(btrim(COALESCE(p_payment_intent_id, '')), '');
    v_ref  text := NULLIF(btrim(COALESCE(p_dispute_id, '')), '');
    dep    canteen_transactions%ROWTYPE;
    v_acct jsonb;
    v_ar   jsonb;
    v_who  text;
    v_fam  text;
    now_ts text := to_char(now(), 'YYYY-MM-DD"T"HH24:MI:SS"Z"');
BEGIN
    IF p_camp_id IS NULL OR v_pi IS NULL OR v_ref IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'missing_argument');
    END IF;
    dep := public._canteen_deposit_of(p_camp_id, v_pi);
    IF dep.camp_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'deposit_not_found');
    END IF;
    v_who := regexp_replace(COALESCE(NULLIF(dep.payload ->> 'camper', ''), dep.camper), '\s#\d+$', '');
    v_fam := public.camp_family_key_for_person(p_camp_id,
                 CASE WHEN dep.camper_id ~ '^[0-9]+$' THEN dep.camper_id::bigint END, dep.camper);

    -- A late message for a dispute the camp already won pauses nothing.
    IF EXISTS (SELECT 1 FROM canteen_transactions WHERE camp_id = p_camp_id AND sig = 'xref_won:' || v_ref) THEN
        RETURN jsonb_build_object('success', true, 'changed', false, 'alreadyWon', true, 'familyKey', v_fam);
    END IF;

    v_acct := public.canteen_account_lock(p_camp_id, dep.camper);
    v_ar := CASE WHEN jsonb_typeof(v_acct) = 'object' THEN v_acct -> 'autoReload' END;
    IF jsonb_typeof(v_ar) IS DISTINCT FROM 'object' OR NOT COALESCE((v_ar ->> 'enabled')::boolean, false) THEN
        RETURN jsonb_build_object('success', true, 'changed', false, 'reason', 'auto_reload_off', 'familyKey', v_fam);
    END IF;
    PERFORM public.canteen_account_save(p_camp_id, dep.camper, jsonb_set(v_acct, '{autoReload}', v_ar || jsonb_build_object(
        'enabled', false,
        'disputePausedAt', now_ts, 'disputeId', v_ref,
        'disabledAt', now_ts,
        'disabledReason', 'switched off because a top-up was disputed with the bank — switch it back on once that is settled'), true));
    IF to_regclass('public.notifications') IS NOT NULL THEN
        INSERT INTO notifications (camp_id, source, source_id, title, body, link_target)
        VALUES (p_camp_id, 'canteen_autoreload_off', dep.camper || ':dispute:' || v_ref,
                'Canteen auto-reload switched off — a top-up was disputed',
                v_who || '''s parent disputed a canteen top-up with their bank, so auto-reload has been switched off '
                  || 'and will not charge that card again. It stays off until the parent switches it back on in Link.',
                'campistry_snacks.html')
        ON CONFLICT (camp_id, source, source_id) DO NOTHING;
    END IF;
    RETURN jsonb_build_object('success', true, 'changed', true, 'camper', v_who, 'familyKey', v_fam);
END $$;
REVOKE ALL ON FUNCTION public.pause_canteen_autoreload_for_dispute(uuid, text, text) FROM public, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.pause_canteen_autoreload_for_dispute(uuid, text, text) TO service_role;

-- A Cardknox/Banquest top-up is taken off the wallet (and put back if won) the
-- same way as a Stripe one (TED-211): 287 finds the top-up by either id.
DO $$
DECLARE
    d   text := pg_get_functiondef('public.record_canteen_stripe_reversal(uuid,text,text,numeric,text,text)'::regprocedure);
    old text := $o$payload ->> 'stripePaymentIntentId' = v_pi
       AND tx_type = 'credit'$o$;
    new text := $n$(payload ->> 'stripePaymentIntentId' = v_pi OR payload ->> 'byopTransactionId' = v_pi)
       AND tx_type = 'credit'$n$;
BEGIN
    IF position('byopTransactionId' IN d) > 0 THEN
        RAISE NOTICE '290: record_canteen_stripe_reversal already finds a Cardknox/Banquest top-up';
        RETURN;
    END IF;
    IF position(old IN d) = 0 THEN
        RAISE EXCEPTION '290: record_canteen_stripe_reversal does not look the way this file expects (run 287 first) — send this message to the builder';
    END IF;
    EXECUTE replace(d, old, new);
END $$;

-- The nightly run writes back the copy it read: that copy never switches a
-- dispute pause back on.
DO $$
DECLARE
    p   regprocedure := COALESCE(to_regprocedure('public._update_canteen_autoreload_state__by_name(uuid,text,jsonb)'),
                                 to_regprocedure('public.update_canteen_autoreload_state(uuid,text,jsonb)'));
    d   text := pg_get_functiondef(p);
    old text := $o$    v_acct := jsonb_set(v_acct, '{autoReload}', p_autoreload, true);$o$;
    new text := $n$    -- 290 (TED-205): a dispute pause stays off until the parent's own save.
    IF jsonb_typeof(v_prev) = 'object' AND v_prev ? 'disputePausedAt' AND NOT p_autoreload ? 'disputePausedAt' THEN
        p_autoreload := p_autoreload || jsonb_build_object('enabled', false,
            'disputePausedAt', v_prev -> 'disputePausedAt', 'disputeId', v_prev -> 'disputeId',
            'disabledAt', v_prev -> 'disabledAt', 'disabledReason', v_prev -> 'disabledReason');
    END IF;
    v_acct := jsonb_set(v_acct, '{autoReload}', p_autoreload, true);$n$;
BEGIN
    IF position('disputePausedAt' IN d) > 0 THEN
        RAISE NOTICE '290: the nightly run''s write already keeps a dispute pause';
        RETURN;
    END IF;
    IF position(old IN d) = 0 THEN
        RAISE EXCEPTION '290: update_canteen_autoreload_state does not look the way this file expects — send this message to the builder';
    END IF;
    EXECUTE replace(d, old, new);
END $$;

-- The parent's own save in Link switches it back on: the pause note goes (as
-- 282 does for the camp's other notes).
DO $$
DECLARE
    d   text := pg_get_functiondef('public.set_canteen_auto_reload(uuid,text,jsonb,bigint)'::regprocedure);
    old text := $o$    v_ar := (v_ar - 'disabledReason') - 'disabledAt';$o$;
    new text := $n$    v_ar := (((v_ar - 'disabledReason') - 'disabledAt') - 'disputePausedAt') - 'disputeId';$n$;
BEGIN
    IF position('disputePausedAt' IN d) > 0 THEN
        RAISE NOTICE '290: a parent''s save already clears the dispute pause';
        RETURN;
    END IF;
    IF position(old IN d) = 0 THEN
        RAISE EXCEPTION '290: set_canteen_auto_reload does not look the way this file expects (run 282 first) — send this message to the builder';
    END IF;
    EXECUTE replace(d, old, new);
END $$;
